if os.environ.get("LEGAL_KB_DEBUG_ACCESS_LOG"):
    import time as _time
    from starlette.middleware.base import BaseHTTPMiddleware

    class _DebugAccessLogMiddleware(BaseHTTPMiddleware):
        async def dispatch(self, request, call_next):
            start = _time.time()
            response = await call_next(request)
            path = request.url.path
            q = request.url.query
            try:
                with open("/tmp/legalkb_access.log", "a", encoding="utf-8") as f:
                    f.write(f"{_time.strftime('%H:%M:%S')} {request.method} {path}?{q} -> {response.status_code} ({(_time.time()-start)*1000:.0f}ms)\n")
            except Exception:
                pass
            return response

    app.add_middleware(_DebugAccessLogMiddleware)

