def require_remote_management_enabled(request: Optional[Request] = None):
    # 私有部署只禁止从远端执行清理、启动等机器管理动作；浏览器通过
    # localhost 使用时仍应允许。只信任 socket 对端地址，不读取转发头。
    client_host = request.client.host if request and request.client else ""
    if request is not None and is_loopback_client(client_host):
        return
    if not allow_remote_management():
        raise HTTPException(status_code=403, detail="私有部署模式已禁用远程管理功能")


