def _mask_api_key(value: str) -> str:
    if not value:
        return ""
    if len(value) <= 8:
        return "••••••••"
    return f"{value[:3]}••••••••{value[-4:]}"


def _current_ai_value(name: str, default: str = "") -> str:
    return str(getattr(ai_config_module, name, default) or default)


def _local_ai_value(name: str, default: str = "") -> str:
    local_secrets = getattr(ai_config_module, "_local_ai_secrets", None)
    return str(getattr(local_secrets, name, default) or default) if local_secrets is not None else default


def _provider_payload(provider_id: str) -> Dict[str, Any]:
    if provider_id.startswith('custom_'):
        from .ai_custom import find
        item=find(provider_id)
        if not item:raise HTTPException(404,'未找到该自定义 API')
        hidden=set(ai_config_module.load_ai_prefs()['hidden_models'])
        return {"id":item['id'],"name":item['name'],"caption":"自定义 API","configured":bool(item['api_key']),
            "key_masked":_mask_api_key(item['api_key']),"api_url":item['api_url'],"protocol":item['protocol'],
            "models":[{"model":item['id']+':'+m,"label":m,"hidden":item['id']+':'+m in hidden} for m in item['models']],
            "color":"#64748b","managed_key":False,"managed_url":False,"custom":True,
            "test":_AI_PROVIDER_TEST_RESULTS.get(provider_id),"balance":None,"portal_url":""}
    definition = AI_PROVIDER_DEFINITIONS[provider_id]
    key = _current_ai_value(definition["key_name"])
    url = _current_ai_value(definition["url_name"], definition["default_url"])
    test_result = _AI_PROVIDER_TEST_RESULTS.get(provider_id)
    hidden_models = set(ai_config_module.load_ai_prefs()["hidden_models"])
    models = [
        {
            "model": model,
            "label": label,
            "hidden": model in hidden_models,
        }
        for model, label in ai_config_module.ask_models(provider_id)
    ]
    return {
        "id": provider_id,
        "name": definition["name"],
        "caption": definition["caption"],
        "configured": bool(key and url),
        "key_masked": _mask_api_key(key),
        "api_url": url,
        "models": models,
        "color": definition["color"],
        "managed_key": definition["key_name"] in os.environ,
        "managed_url": definition["url_name"] in os.environ,
        "test": test_result,
        "balance": _AI_PROVIDER_BALANCES.get(provider_id),
        "portal_url": definition.get("portal_url", ""),
    }


def _write_local_ai_settings(values: Dict[str, str]) -> None:
    secrets_path = ai_config_module.configuration_directory() / "local_ai_secrets.py"
    preserved = {
        name: value
        for name, value in vars(getattr(ai_config_module, "_local_ai_secrets", object())).items()
        if name.isupper() and isinstance(value, str)
    } if getattr(ai_config_module, "_local_ai_secrets", None) is not None else {}
    preserved.update(values)
    lines = [
        '"""Private AI credentials managed by the Legal Knowledge Base UI."""',
        "",
    ]
    for name in sorted(preserved):
        lines.append(f"{name} = {preserved[name]!r}")
    lines.append("")
    secrets_path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary_name = tempfile.mkstemp(prefix=".local_ai_secrets.", suffix=".tmp", dir=str(secrets_path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as file:
            file.write("\n".join(lines))
            file.flush()
            os.fsync(file.fileno())
        os.chmod(temporary_name, 0o600)
        os.replace(temporary_name, secrets_path)
    finally:
        if os.path.exists(temporary_name):
            os.unlink(temporary_name)


def _reload_ai_runtime() -> None:
    global DEEPSEEK_API_KEY, DEEPSEEK_API_URL, SILICONFLOW_API_KEY, SILICONFLOW_API_URL
    global SCNET_API_KEY, SCNET_API_URL, ARK_API_KEY, ARK_API_URL
    global CC2API_API_KEY, CC2API_API_URL
    global OPENCODE_API_KEY, OPENCODE_API_URL
    global DEFAULT_AI_MODEL
    previous_allowed = ALLOWED_MODELS
    importlib.reload(ai_config_module)
    previous_allowed.clear(); previous_allowed.update(ai_config_module.ALLOWED_MODELS)
    ai_config_module.ALLOWED_MODELS = previous_allowed
    for name in (
        "DEEPSEEK_API_KEY", "DEEPSEEK_API_URL", "SILICONFLOW_API_KEY", "SILICONFLOW_API_URL",
        "SCNET_API_KEY", "SCNET_API_URL", "ARK_API_KEY", "ARK_API_URL",
        "OPENCODE_API_KEY", "OPENCODE_API_URL",
        "CC2API_API_KEY", "CC2API_API_URL",
    ):
        value = getattr(ai_config_module, name)
        globals()[name] = value
        setattr(ai_client_module, name, value)
    default_model = ai_config_module.effective_default_model()
    ai_config_module.DEFAULT_AI_MODEL = default_model
    globals()["DEFAULT_AI_MODEL"] = default_model
    # 其他模块若在导入时快照了 DEFAULT_AI_MODEL，也会拿到最新值。
    for module_name in ("case_manager", "recording_routes", "judicial_messages"):
        module = _sys.modules.get(f"backend.{module_name}")
        if module is not None:
            setattr(module, "DEFAULT_AI_MODEL", default_model)


@app.on_event("startup")
async def _restore_ai_defaults_on_startup():
    """服务器重启后立即恢复管理页保存的 AI 默认模型，避免回落到官方 DeepSeek。"""
    _reload_ai_runtime()


async def _fetch_deepseek_balance(key: str) -> Dict[str, Any]:
    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            response = await client.get(
                "https://api.deepseek.com/user/balance",
                headers={"Authorization": f"Bearer {key}", "Accept": "application/json"},
            )
    except Exception:
        return {"ok": False, "message": "无法连接余额接口"}
    if response.status_code == 401:
        return {"ok": False, "message": "密钥无效或已失效"}
    if response.status_code != 200:
        return {"ok": False, "message": f"余额接口返回 {response.status_code}"}
    try:
        payload = response.json()
    except Exception:
        return {"ok": False, "message": "余额接口返回格式无法识别"}
    infos = payload.get("balance_infos") or []
    info = next((item for item in infos if item.get("currency") == "CNY"), None) or (infos[0] if infos else None)
    if not info:
        return {
            "ok": True,
            "available": bool(payload.get("is_available", True)),
            "balance": 0,
            "currency": "CNY",
            "message": "账户暂无余额信息",
        }
    return {
        "ok": True,
        "available": bool(payload.get("is_available", True)),
        "balance": float(info.get("total_balance") or 0),
        "currency": info.get("currency") or "CNY",
        "granted": info.get("granted_balance"),
        "topped_up": info.get("topped_up_balance"),
    }


async def _fetch_siliconflow_balance(key: str) -> Dict[str, Any]:
    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            response = await client.get(
                "https://api.siliconflow.cn/v1/user/info",
                headers={"Authorization": f"Bearer {key}", "Accept": "application/json"},
            )
    except Exception:
        return {"ok": False, "message": "无法连接余额接口"}
    if response.status_code == 401:
        return {"ok": False, "message": "密钥无效或已失效"}
    if response.status_code != 200:
        return {"ok": False, "message": f"余额接口返回 {response.status_code}"}
    try:
        payload = response.json()
    except Exception:
        return {"ok": False, "message": "余额接口返回格式无法识别"}
    data = payload.get("data") or {} if isinstance(payload, dict) else {}
    code = payload.get("code") if isinstance(payload, dict) else None
    if code not in (None, 20000):
        return {"ok": False, "message": str(payload.get("message") or "余额接口返回异常")}
    try:
        total = float(data.get("totalBalance") or 0)
        charge = float(data.get("chargeBalance") or 0)
        granted = float(data.get("balance") or 0)
    except (TypeError, ValueError):
        return {"ok": False, "message": "余额接口返回格式无法识别"}
    return {
        "ok": True,
        "available": total > 0,
        "balance": total,
        "currency": "CNY",
        "charge": charge,
        "granted": granted,
    }


async def _fetch_ai_provider_balance(provider_id: str) -> Dict[str, Any]:
    definition = AI_PROVIDER_DEFINITIONS.get(provider_id)
    if not definition:
        raise HTTPException(status_code=404, detail="未找到该 AI 服务")
    key = _current_ai_value(definition["key_name"])
    if not key:
        raise HTTPException(status_code=400, detail="请先配置 API 密钥")
    if provider_id == "deepseek":
        return await _fetch_deepseek_balance(key)
    if provider_id == "siliconflow":
        return await _fetch_siliconflow_balance(key)
    return {"ok": False, "unsupported": True, "message": "该平台未提供公开的余额查询接口"}


@app.get("/api/ai-providers")
async def list_ai_providers():
    from .ai_custom import providers as custom_providers
    providers = [_provider_payload(provider_id) for provider_id in [*AI_PROVIDER_DEFINITIONS,*(item['id'] for item in custom_providers())]]
    prefs = ai_config_module.load_ai_prefs()
    default_model = ai_config_module.effective_default_model()
    return {
        "providers": providers,
        "configured_count": sum(1 for item in providers if item["configured"]),
        "total_count": len(providers),
        "default_provider": prefs["default_provider"],
        "default_model": default_model,
        "default_label": ai_config_module.ask_model_label(default_model),
        "security_note": "API 密钥仅保存在本机私有配置中，页面不会返回完整密钥。",
    }


class AIProviderPreferences(BaseModel):
    default_provider: Optional[str] = None
    default_model: Optional[str] = None


@app.put("/api/ai-providers/preferences")
async def update_ai_provider_preferences(payload: AIProviderPreferences, request: Request):
    require_remote_management_enabled(request)
    prefs = ai_config_module.load_ai_prefs()
    if payload.default_provider is not None:
        provider_id = payload.default_provider.strip()
        if provider_id not in AI_PROVIDER_DEFINITIONS and not ai_config_module.ask_models(provider_id):
            raise HTTPException(status_code=400, detail="未找到该 AI 服务")
        prefs["default_provider"] = provider_id
    if payload.default_model is not None:
        model = payload.default_model.strip()
        if model not in ALLOWED_MODELS:
            raise HTTPException(status_code=400, detail="不支持的 AI 模型")
        prefs["default_model"] = model
    ai_config_module.save_ai_prefs(prefs)
    _reload_ai_runtime()
    return {
        "success": True,
        "default_provider": prefs["default_provider"],
        "default_model": ai_config_module.effective_default_model(),
    }


class AIModelVisibility(BaseModel):
    model: str
    hidden: bool


@app.get("/api/ai-providers/purposes")
async def list_ai_purpose_models():
    """各业务功能（文章摘要、法答网核心结论、研究项目备忘录、法律晨报、
    降级备用模型）当前生效的默认模型。"""
    prefs = ai_config_module.load_ai_prefs()
    purpose_models = prefs.get("purpose_models") or {}
    purposes = []
    for purpose in ai_config_module.AI_PURPOSE_LABELS:
        selected = purpose_models.get(purpose, "")
        effective = ai_config_module.effective_purpose_model(purpose)
        purposes.append({
            "key": purpose,
            "label": ai_config_module.AI_PURPOSE_LABELS[purpose],
            "default_model": ai_config_module.AI_PURPOSE_DEFAULTS.get(purpose, ""),
            "model": effective,
            "overridden": bool(selected),
            "model_label": ai_config_module.ask_model_label(effective),
        })
    return {
        "purposes": purposes,
        "default_provider": prefs["default_provider"],
        "default_model": ai_config_module.effective_default_model(),
    }


class AIPurposeModelsUpdate(BaseModel):
    purpose_models: Dict[str, str] = {}


@app.put("/api/ai-providers/purposes")
async def update_ai_purpose_models(payload: AIPurposeModelsUpdate, request: Request):
    """保存各业务功能的默认模型（网关由模型名前缀决定）。

    purpose_models 中 value 为空字符串表示“跟随 AI 增强默认模型”，
    即清除该功能的单独设置并回退到内置默认。
    """
    require_remote_management_enabled(request)
    unknown = [key for key in payload.purpose_models if key not in ai_config_module.AI_PURPOSE_LABELS]
    if unknown:
        raise HTTPException(status_code=400, detail=f"未知功能：{','.join(unknown)}")
    invalid = [model for model in payload.purpose_models.values() if model and model not in ALLOWED_MODELS]
    if invalid:
        raise HTTPException(status_code=400, detail=f"不支持的 AI 模型：{','.join(invalid)}")
    prefs = ai_config_module.load_ai_prefs()
    purpose_models = dict(prefs.get("purpose_models") or {})
    for key, value in payload.purpose_models.items():
        if value:
            purpose_models[key] = value
        else:
            purpose_models.pop(key, None)
    prefs["purpose_models"] = purpose_models
    ai_config_module.save_ai_prefs(prefs)
    return {
        "success": True,
        "purposes": [
            {
                "key": purpose,
                "label": ai_config_module.AI_PURPOSE_LABELS[purpose],
                "model": ai_config_module.effective_purpose_model(purpose),
                "default_model": ai_config_module.AI_PURPOSE_DEFAULTS.get(purpose, ""),
            }
            for purpose in ai_config_module.AI_PURPOSE_LABELS
        ],
    }


@app.put("/api/ai-providers/{provider_id}/models")
async def update_ai_provider_model_visibility(provider_id: str, payload: AIModelVisibility, request: Request):
    require_remote_management_enabled(request)
    if provider_id not in AI_PROVIDER_DEFINITIONS and not ai_config_module.ask_models(provider_id):
        raise HTTPException(status_code=404, detail="未找到该 AI 服务")
    catalog_models = [model for model, _ in ai_config_module.ask_models(provider_id)]
    if payload.model not in catalog_models:
        raise HTTPException(status_code=404, detail="该服务下不存在此模型")
    prefs = ai_config_module.load_ai_prefs()
    hidden = set(prefs["hidden_models"])
    if payload.hidden:
        hidden.add(payload.model)
    else:
        hidden.discard(payload.model)
    prefs["hidden_models"] = sorted(hidden)
    ai_config_module.save_ai_prefs(prefs)
    return {"success": True, "provider": provider_id, "model": payload.model, "hidden": payload.hidden}


@app.get("/api/ai-ask-models")
async def list_ai_ask_models():
    prefs = ai_config_module.load_ai_prefs()
    hidden = set(prefs["hidden_models"])
    groups = []
    for provider in ai_config_module.ASK_MODEL_CATALOG:
        visible = [
            {"value": model, "label": label}
            for model, label in provider["models"]
            if model not in hidden
        ]
        if visible:
            groups.append({"provider": provider["id"], "label": provider["group"], "models": visible})
    default_model = ai_config_module.effective_default_model()
    return {
        "groups": groups,
        "default_model": default_model,
        "default_provider": prefs["default_provider"],
        "default_label": ai_config_module.ask_model_label(default_model),
    }


class AIModelBulkVisibility(BaseModel):
    hidden: bool


@app.put("/api/ai-providers/{provider_id}/models/bulk")
async def update_ai_provider_all_models_visibility(provider_id: str, payload: AIModelBulkVisibility, request: Request):
    """一键隐藏/显示某个 API 服务下的全部大模型（AI 增强中不再/重新显示）。"""
    require_remote_management_enabled(request)
    if provider_id not in AI_PROVIDER_DEFINITIONS and not ai_config_module.ask_models(provider_id):
        raise HTTPException(status_code=404, detail="未找到该 AI 服务")
    catalog_models = [model for model, _ in ai_config_module.ask_models(provider_id)]
    if not catalog_models:
        raise HTTPException(status_code=404, detail="该服务下没有可管理的大模型")
    prefs = ai_config_module.load_ai_prefs()
    hidden = set(prefs["hidden_models"])
    if payload.hidden:
        hidden.update(catalog_models)
    else:
        hidden.difference_update(catalog_models)
    prefs["hidden_models"] = sorted(hidden)
    ai_config_module.save_ai_prefs(prefs)
    return {"success": True, "provider": provider_id, "hidden": payload.hidden, "models": catalog_models}


