# ─────────────────────────────────────────────
# 刑民交叉专用分类函数（必须在 init_db 之前定义）
# ─────────────────────────────────────────────

def _is_xingmin_cross(text: str) -> bool:
    """
    判断文章是否属于刑民交叉领域。
    规则：必须同时满足刑事方向 AND 民商事方向的条件。
    
    刑事方向（满足任一）：
      A. 含"刑民交叉/先刑后民"等强特征词（出现≥1次）
      B. 核心刑事罪名关键词（不含软词）总得分≥3
    
    民商事方向（满足任一）：
      C. 民商事争议关键词总得分≥8
      D. 含≥6个不同的民商事核心词（说明有广泛民商事讨论）
    """
    # ── 强特征词：只要出现就直接算刑事方向达标 ──
    STRONG_MARKERS = ["刑民交叉", "刑民并案", "刑民交织", "先刑后民", "先民后刑"]
    criminal_strong = sum(text.count(kw) for kw in STRONG_MARKERS)
    
    # ── 核心刑事罪名关键词（排除在民事语境中高频出现的"软词"）──
    CRIMINAL_KW_HARD = [
        "合同诈骗", "经济犯罪", "职务犯罪", "职务侵占", "挪用资金",
        "非法吸收公众存款", "集资诈骗", "诈骗罪", "拒不执行判决",
        "非法经营", "骗取贷款", "违法发放贷款",
        "非国家工作人员受贿", "背信损害上市公司利益",
        "拒不支付劳动报酬", "恶意欠薪",
        "刑事指控", "刑事侦查",
    ]
    # ── 软刑事词（在纯民事文章中也可能高频出现，单独不计分）──
    # 如："虚假诉讼"（民事法官讨论防范）、"刑事责任/案件/立案/判决"（法规条款常见）
    
    criminal_hard_score = sum(text.count(kw) for kw in CRIMINAL_KW_HARD)
    
    # ── 民商事争议关键词 ──
    CIVIL_KW = [
        "合同", "建设工程", "工程施工", "工程款", "承包", "发包",
        "股权", "股东", "公司", "破产", "破产清算", "破产重整",
        "执行异议", "执行之诉", "查封", "拍卖",
        "借款", "贷款", "担保", "抵押", "质押",
        "房地产", "商品房", "房屋买卖", "不动产",
        "仲裁", "商事", "侵权", "损害赔偿",
        "债权", "债务", "债务重组",
        "劳动争议", "劳动仲裁", "劳动合同",
        "知识产权", "商标", "专利", "著作权",
        "税务", "税收", "发票",
        "金融", "证券", "信托", "保险", "基金",
    ]
    civil_score = sum(text.count(kw) for kw in CIVIL_KW)
    
    # 统计不同民商事核心词出现数（避免单一高频词刷分）
    civil_variety = sum(1 for kw in CIVIL_KW if text.count(kw) > 0)
    
    # 刑事方向判定：强特征词≥2次 或 (强特征词1次+核心罪名词≥1) 或 核心罪名词≥3
    criminal_ok = (criminal_strong >= 2) or (criminal_strong >= 1 and criminal_hard_score >= 1) or (criminal_hard_score >= 3)
    # 民商事方向判定：高总频或高多样性
    civil_ok = (civil_score >= 8) or (civil_variety >= 6)
    
    return criminal_ok and civil_ok


def _xingmin_score(text: str) -> int:
    """计算刑民交叉的综合得分（用于排序）"""
    CRIMINAL_KW = [
        "刑民交叉", "刑民并案", "刑民交织", "先刑后民", "先民后刑",
        "合同诈骗", "经济犯罪", "职务犯罪", "职务侵占", "挪用资金",
        "非法吸收公众存款", "集资诈骗", "诈骗罪", "拒不执行判决",
        "虚假诉讼", "非法经营", "骗取贷款", "违法发放贷款",
        "刑事附带民事", "刑事责任", "刑事指控",
    ]
    return sum(text.count(kw) for kw in CRIMINAL_KW)


# ─────────────────────────────────────────────
# 核心分类工具函数（必须在 init_db 之前定义）
# ─────────────────────────────────────────────

def classify_domains(text: str) -> List[str]:
    """
    根据文章内容精准识别法律领域。
    多维度评分机制：
      1. 强特征词：每次出现计5分（高区分度词）
      2. 普通关键词：每次出现计1分
      3. 标题加权：前150字视为"标题区"，关键词在此区额外×4权重
      4. 密度过滤：综合得分 ÷ 文章千字数 < min_density 则排除
      5. 最低分过滤：综合得分 < min_score 则排除
      6. 强特征词命中约束：不同强词命中数 < min_strong_hits 则排除
         （防止纯靠普通词堆分，文章根本不涉及该领域核心概念的情况）
    """
    found = []
    text_len_k = max(len(text) / 1000, 0.5)  # 文章字数（千字），最小0.5防除零

    # 取前150字作为"标题区"（标题+摘要），这些区域权重更高
    title_zone = text[:150]

    for domain, cfg in LEGAL_DOMAINS_V2.items():
        # 刑民交叉使用专用组合逻辑
        if domain == "刑民交叉":
            if _is_xingmin_cross(text):
                score = _xingmin_score(text)
                found.append((domain, score))
            continue

        keywords = cfg.get("keywords", [])
        min_score = cfg.get("min_score", 10)
        min_density = cfg.get("min_density", 1.5)
        min_strong_hits = cfg.get("min_strong_hits", 1)
        min_category_hits = cfg.get("min_category_hits", 0)

        # ── 收集所有强词（支持单组或多组分类）──
        # 多组格式：strong_words（默认）+ strong_words_2/3/4...（按类别分组）
        all_strong_word_lists = []
        for k in list(cfg.keys()):
            if k.startswith("strong_words") and k != "strong_words_":
                all_strong_word_lists.append(cfg[k])
        if not all_strong_word_lists:
            all_strong_word_lists = [cfg.get("strong_words", [])]

        # 收集所有强词（扁平，用于得分计算）
        all_strong_words = []
        for lst in all_strong_word_lists:
            all_strong_words.extend(lst)

        # ── 计算得分 ──
        score = 0
        strong_hit_count = 0   # 命中了多少个不同的强特征词
        strong_hit_total = 0   # 强特征词总出现次数（含重复）
        category_hit_count = 0  # 命中了多少个不同类别

        # 强特征词：全文计数×5，标题区额外再加权×4
        for w in all_strong_words:
            cnt_body = text.count(w)
            cnt_title = title_zone.count(w)
            if cnt_body > 0:
                strong_hit_count += 1
                strong_hit_total += cnt_body
            score += cnt_body * 5
            score += cnt_title * 4 * 5

        # 按类别统计有多少个类别至少命中1个词
        for lst in all_strong_word_lists:
            if any(text.count(w) > 0 for w in lst):
                category_hit_count += 1

        # ── 强特征词命中约束（核心过滤）──
        real_title_zone = text[:40]
        title_strong_in_real_title = any(real_title_zone.count(w) > 0 for w in all_strong_words)
        if strong_hit_count < min_strong_hits:
            continue
        if strong_hit_total < 2 and not title_strong_in_real_title:
            continue
        # 多类别过滤：至少命中 min_category_hits 个不同类别
        if min_category_hits > 0 and category_hit_count < min_category_hits:
            continue

        # 普通关键词：全文计数×1，标题区额外×4
        for w in keywords:
            cnt_body = text.count(w)
            cnt_title = title_zone.count(w)
            score += cnt_body * 1
            score += cnt_title * 4  # 标题区普通词额外 ×4

        # ── 密度过滤 ──
        density = score / text_len_k
        if density < min_density:
            continue

        # ── 最低分过滤 ──
        if score < min_score:
            continue

        found.append((domain, score))

    found.sort(key=lambda x: -x[1])
    result = [d[0] for d in found[:5]]
    return result if result else ["综合法律"]


def auto_tag_by_domain(text: str, existing_tags: list) -> list:
    """根据文本内容，将匹配的领域名自动加入标签列表（使用精准分类算法，不重复）"""
    tags = list(existing_tags)
    matched = classify_domains(text)
    for domain_name in matched:
        if domain_name != "综合法律" and domain_name not in tags:
            tags.append(domain_name)
    return tags


def _normalize_domain_list(value) -> List[str]:
    """Return a de-duplicated, non-empty list of domain names."""
    if isinstance(value, str):
        try:
            value = json.loads(value or "[]")
        except (TypeError, json.JSONDecodeError):
            value = []
    if not isinstance(value, list):
        return []

    result = []
    for item in value:
        name = str(item).strip() if item is not None else ""
        if name and name not in result:
            result.append(name)
    return result


def _domain_assignment_state(text: str, selected_domains=None, manual_domains=None,
                             excluded_auto_domains=None, migrate_legacy: bool = False):
    """Build the persisted domain state without losing explicit user choices.

    ``domains`` is the effective list shown by the application.  The two metadata
    lists keep user-added domains separate from classifier output and remember
    auto domains the user explicitly removed.
    """
    auto_domains = _normalize_domain_list(classify_domains(text))
    if auto_domains == ["综合法律"]:
        auto_domains = []

    if migrate_legacy:
        selected = _normalize_domain_list(selected_domains)
        manual = [name for name in selected if name not in auto_domains]
        excluded = [name for name in auto_domains if name not in selected]
    elif selected_domains is not None:
        selected = _normalize_domain_list(selected_domains)
        manual = [name for name in selected if name not in auto_domains]
        excluded = [name for name in auto_domains if name not in selected]
    else:
        manual = _normalize_domain_list(manual_domains)
        excluded = _normalize_domain_list(excluded_auto_domains)

    effective = [name for name in auto_domains if name not in excluded]
    effective.extend(name for name in manual if name not in effective)
    return effective, manual, excluded


