def escape_like_pattern(pattern: str) -> str:
    """转义LIKE查询中的特殊字符"""
    # 转义 SQLite LIKE 中的特殊字符
    return pattern.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')


_CHINESE_NUMBER_DIGITS = {
    '零': 0, '〇': 0, '一': 1, '二': 2, '两': 2, '三': 3, '四': 4,
    '五': 5, '六': 6, '七': 7, '八': 8, '九': 9,
}
_CHINESE_NUMBER_UNITS = {'十': 10, '百': 100, '千': 1000, '万': 10000}


def _int_to_chinese_number(value: int) -> str:
    """Convert a non-negative integer used in a provision number to Chinese numerals."""
    if value == 0:
        return '零'
    if value < 0 or value > 99999:
        return str(value)

    def under_ten_thousand(number: int) -> str:
        digits = '零一二三四五六七八九'
        units = ('', '十', '百', '千')
        result = []
        pending_zero = False
        for position in range(3, -1, -1):
            unit_value = 10 ** position
            digit = number // unit_value
            number %= unit_value
            if digit:
                if pending_zero and result:
                    result.append('零')
                result.append(digits[digit])
                result.append(units[position])
                pending_zero = False
            elif result and number:
                pending_zero = True
        text = ''.join(result)
        return text[1:] if text.startswith('一十') else text

    if value < 10000:
        return under_ten_thousand(value)
    high, low = divmod(value, 10000)
    result = under_ten_thousand(high) + '万'
    if low:
        if low < 1000:
            result += '零'
        result += under_ten_thousand(low)
    return result


def _chinese_number_to_int(text: str) -> Optional[int]:
    """Parse the conventional Chinese numerals used in Chinese legal provisions."""
    if not text or any(ch not in _CHINESE_NUMBER_DIGITS and ch not in _CHINESE_NUMBER_UNITS for ch in text):
        return None
    if all(ch in _CHINESE_NUMBER_DIGITS for ch in text):
        try:
            return int(''.join(str(_CHINESE_NUMBER_DIGITS[ch]) for ch in text))
        except ValueError:
            return None
    total = section = number = 0
    for ch in text:
        if ch in _CHINESE_NUMBER_DIGITS:
            number = _CHINESE_NUMBER_DIGITS[ch]
            continue
        unit = _CHINESE_NUMBER_UNITS[ch]
        if unit == 10000:
            section += number
            total += section * unit
            section = number = 0
        else:
            if number == 0:
                number = 1
            section += number * unit
            number = 0
    return total + section + number


def _legal_provision_numbers(question: str) -> list[int]:
    """Return provision numbers mentioned as either 第100条 or 第一百条."""
    pattern = re.compile(r'第\s*(\d{1,5}|[零〇一二两三四五六七八九十百千万]+)\s*条')
    numbers = []
    for match in pattern.finditer(question or ''):
        raw = match.group(1)
        value = int(raw) if raw.isdigit() else _chinese_number_to_int(raw)
        if value is not None and value not in numbers:
            numbers.append(value)
    # Also tolerate the common shorthand "100条原文" without 第.
    if not numbers:
        for match in re.finditer(r'(?<!\d)(\d{1,5})\s*条', question or ''):
            value = int(match.group(1))
            if value not in numbers:
                numbers.append(value)
    return numbers


def _legal_provision_locators(question: str) -> list[str]:
    """Generate storage-compatible locator variants for provision references."""
    locators = []
    for number in _legal_provision_numbers(question):
        for locator in (f'第{number}条', f'第{_int_to_chinese_number(number)}条'):
            if locator not in locators:
                locators.append(locator)
    return locators

