def _pdf_title_is_noise(title: str) -> bool:
    """识别 PDF 文字层错序产生的乱码标题（中英碎片穿插、随机字母串）。

    - 全拉丁标题：必须有命中常用英文词表的 4+ 字母单词，否则视为乱码；
    - 中英混合标题：非白名单缩写/字母碎片每个计 4 分，碎片段数、中英
      交替边界数、超长与中文字数再各加分，总分 >= 5 视为乱码。
    """
    raw = title or ""
    compact = re.sub(r"\s+", "", raw)
    if not compact:
        return False
    frags = re.findall(r"[A-Za-z]+", raw)
    if not frags:
        return False
    cjk = len(re.findall(r"[\u4e00-\u9fff]", compact))
    if cjk == 0:
        return not any(f.lower() in _PDF_TITLE_COMMON_WORDS for f in frags if len(f) >= 4)
    score = 0
    for frag in frags:
        if frag.lower() in _PDF_TITLE_ABBR:
            continue
        score += 4
    if len(frags) >= 3:
        score += 2
    if len(re.findall(r"[\u4e00-\u9fff][A-Za-z]|[A-Za-z][\u4e00-\u9fff]", compact)) >= 4:
        score += 2
    if len(compact) > 30:
        score += 1
    if cjk >= 4:
        score += 1
    return score >= 5


def _pdf_page_corner_title(words: List[list], page_width: float, page_height: float, page_text: str = "") -> str:
    """提取 PDF 页面左上角小标题，供「页面N：标题」智能目录使用。

    规则：取页面顶部 18% 高度、左起 80% 宽度区域内最靠上的第一行文字
    （PPT/文档每页左上角的小标题通常位于此处）。词坐标为空时退回取
    页面文本的首个非空行。返回空字符串表示该页没有可用的标题。
    """
    region = [
        w for w in words
        if len(w) >= 5 and str(w[4] or "").strip()
        and float(w[1]) < page_height * 0.18 and float(w[0]) < page_width * 0.8
    ]
    title = ""
    if region:
        region.sort(key=lambda w: (float(w[1]), float(w[0])))
        first_y = float(region[0][1])
        tolerance = max(3.0, (float(region[0][3]) - float(region[0][1])) * 0.5)
        line_words = [str(w[4]) for w in region if abs(float(w[1]) - first_y) <= tolerance]
        title = _pdf_join_words(line_words).strip()
    if not title and page_text:
        for raw_line in (page_text or "").splitlines():
            line = raw_line.strip()
            if line:
                title = line
                break
    title = re.sub(r"[\s\u00a0\u3000]+", " ", title).strip(" ：:、·-—~")
    if _pdf_title_is_noise(title):
        return ""
    if len(title) > 40:
        title = title[:40].rstrip() + "…"
    return title


def parse_pdf_as_pages(file_path: str) -> dict:
    """
    「PDF 不解析为文本」模式：
    - 逐页渲染为 JPEG（150 DPI，最长边不超过 2000px，质量 85）保留原排版，
      阅读页按页平铺图片；相比无损 PNG 可节省约 5 倍页面图片空间；
    - 文字层优先取 PDF 自带文字层（词级坐标）；扫描件才用本机 OCR，
      且 OCR 只用于生成阅读时可拖动选中、作笔记的文字层；
    - 页面图片与文字层坐标 JSON 写入 article_images/pdf-<token>/；
    - 智能目录：按「页面N：页面左上角小标题」生成逐页目录（隐藏段落
      pdf-page-toc-entry），渲染时转入左侧智能目录栏，点击跳转对应页面；
    - 返回 content 为按页平铺的 HTML，末尾附隐藏纯文本段供全文检索、摘要与打标。
    """
    import fitz

    dpi = 150
    max_dim = 2000

    doc = fitz.open(file_path)
    page_count = len(doc)
    if page_count <= 0:
        doc.close()
        raise HTTPException(status_code=400, detail="PDF 文档为空，无法按页收录")

    # 预检：是否有文字层。扫描件页数太多时逐页 OCR 会超时。
    layer_words_total = 0
    for page in doc:
        layer_words_total += len(page.get_text("words") or [])
    is_scanned = layer_words_total < max(page_count, 1) * 8
    if is_scanned and page_count > 60:
        doc.close()
        raise HTTPException(
            status_code=400,
            detail="该 PDF 无文字层且超过 60 页，逐页 OCR 生成选中文字层耗时过长，"
                   "建议关闭「PDF 不解析为文本」后按普通方式收录",
        )

    token = uuid.uuid4().hex
    page_dir = ARTICLE_IMAGE_DIR / f"pdf-{token}"
    page_dir.mkdir(parents=True, exist_ok=True)

    try:
        pages_html = []
        page_texts = []
        page_titles = []
        ocr_used = False
        for idx, page in enumerate(doc):
            page_no = idx + 1
            zoom = dpi / 72.0
            if max(page.rect.width, page.rect.height) * zoom > max_dim:
                zoom = max_dim / max(page.rect.width, page.rect.height)
            pix = page.get_pixmap(matrix=fitz.Matrix(zoom, zoom), alpha=False)
            img_name = f"page-{page_no:03d}.jpg"
            img_path = page_dir / img_name
            pix.save(str(img_path), jpg_quality=85)

            # 优先使用 PDF 自带文字层。
            # 关键对齐细节：
            # 1. get_text 返回未旋转页面的坐标，而渲染图已按页面旋转输出，
            #    必须先用 rotation_matrix 变换到渲染坐标系；
            # 2. 渲染图尺寸 = page.rect（已含旋转）× zoom，缩放比例逐页
            #    按实际输出像素计算，避免四舍五入的累积误差。
            words = []
            rm = page.rotation_matrix
            sx = pix.width / page.rect.width
            sy = pix.height / page.rect.height
            for item in (page.get_text("words") or []):
                x0, y0, x1, y1, word = item[0], item[1], item[2], item[3], item[4]
                p0 = fitz.Point(x0, y0) * rm
                p1 = fitz.Point(x1, y1) * rm
                words.append([
                    round(min(p0.x, p1.x) * sx, 1), round(min(p0.y, p1.y) * sy, 1),
                    round(max(p0.x, p1.x) * sx, 1), round(max(p0.y, p1.y) * sy, 1),
                    str(word),
                ])
            page_text = (page.get_text("text") or "").strip()

            # OCR 只在页面完全没有文字层时启用（真扫描件）。有原生文字层的
            # 页面即使词数较少也保留 PDF 文字层：原生层与渲染图逐像素对齐，
            # 而 OCR 会把描边/填充双绘制的标题和图片内文字误读成重叠碎片，
            # 混入选中层后导致文字层与页面视觉“错位”、无法准确选中。
            if not words and len(re.sub(r"\s+", "", page_text or "")) < 20:
                ocr_words, ocr_text = _ocr_words_from_page_image(str(img_path))
                if ocr_words:
                    words = ocr_words
                    ocr_used = True
                if ocr_text:
                    page_text = ocr_text

            layer_payload = {"width": pix.width, "height": pix.height, "words": words}
            with open(page_dir / f"page-{page_no:03d}.words.json", "w", encoding="utf-8") as layer_file:
                json.dump(layer_payload, layer_file, ensure_ascii=False)

            page_texts.append(page_text)
            page_titles.append((page_no, _pdf_page_corner_title(words, pix.width, pix.height, page_text)))
            pages_html.append(
                f'<figure class="pdf-page">'
                f'<img class="pdf-page-image" style="display:block;width:100%;height:auto;margin:0;border-radius:0" '
                f'src="/api/article-pdf/{token}/page-{page_no:03d}.jpg" alt="第 {page_no} 页">'
                f'</figure>'
            )

        full_text = "\n".join(t for t in page_texts if t)
        # 隐藏纯文本段按块拆分，保证段落级检索粒度
        hidden_blocks = []
        for start in range(0, len(full_text), 1500):
            chunk = full_text[start:start + 1500]
            if chunk.strip():
                hidden_blocks.append(
                    f'<p class="pdf-source-text" style="display:none">{html.escape(chunk)}</p>'
                )
        # 智能目录隐藏条目：渲染时转入左侧目录栏并从正文中移除
        toc_entries_html = "\n".join(
            f'<p class="pdf-page-toc-entry" style="display:none">页面{page_no}：{html.escape(title)}</p>'
            for page_no, title in page_titles
        )
        content = (
            '<div class="pdf-page-gallery">' + "\n".join(pages_html) + '</div>\n'
            + toc_entries_html + "\n"
            + "\n".join(hidden_blocks)
        )
        title = extract_title_from_text(full_text, Path(file_path).stem) or Path(file_path).stem
        return {
            "title": title,
            "content": content,
            "text": full_text,
            "ocr_used": ocr_used,
            "page_count": page_count,
        }
    finally:
        doc.close()


def parse_txt(file_path: str) -> dict:
    """解析纯文本文件"""
    for enc in ['utf-8', 'gbk', 'gb2312', 'utf-16']:
        try:
            with open(file_path, 'r', encoding=enc) as f:
                content = f.read()
            break
        except Exception:
            content = ""
    title = extract_title_from_text(content, Path(file_path).stem)
    return {"title": title, "content": content}


def parse_xlsx(file_path: str) -> dict:
    """
    解析 Excel 电子表格（.xlsx / .xls）。

    策略：
    - 逐 Sheet 遍历，跳过全空 Sheet
    - 每个单元格值转为字符串，整行用制表符拼接
    - 有效行（非空行）之间用换行符分隔，Sheet 之间用双换行分隔
    - 首行非空内容作为文章标题候选
    """
    import openpyxl

    wb = openpyxl.load_workbook(file_path, data_only=True)
    sheet_blocks = []

    for sheet in wb.worksheets:
        rows_text = []
        for row in sheet.iter_rows(values_only=True):
            # 过滤 None，将每个单元格转为字符串
            cells = [str(v).strip() for v in row if v is not None and str(v).strip()]
            if cells:
                rows_text.append('\t'.join(cells))
        if rows_text:
            block = f"【{sheet.title}】\n" + '\n'.join(rows_text) if len(wb.worksheets) > 1 else '\n'.join(rows_text)
            sheet_blocks.append(block)

    wb.close()
    content = '\n\n'.join(sheet_blocks)

    # 标题：优先用文件名，其次用第一个有效行内容
    stem = Path(file_path).stem
    first_line = sheet_blocks[0].split('\n')[0] if sheet_blocks else ''
    # 去掉 Sheet 名标头
    if first_line.startswith('【') and '】' in first_line:
        first_line = sheet_blocks[0].split('\n')[1] if '\n' in sheet_blocks[0] else ''
    title = first_line if first_line and len(first_line) <= 80 else stem

    return {"title": title, "content": content}


def _plain_article_text(content: str) -> str:
    """Convert stored HTML/plain content to searchable plain text."""
    if not content:
        return ""
    if "<" in content and ">" in content:
        try:
            return html_to_processing_text(content)
        except Exception:
            return BeautifulSoup(content, "html.parser").get_text("\n")
    return content


_TOC_PLACEHOLDER_RE = re.compile(
    r"<p\b[^>]*class=(['\"])([^'\"]*body-toc-(?:heading|entry)[^'\"]*)\1[^>]*>.*?</p>",
    re.IGNORECASE | re.DOTALL,
)


def strip_stale_toc_placeholders(content: str) -> str:
    """Remove stale TOC placeholder paragraphs from stored article HTML.

    Two kinds of leftovers historically get persisted into the article body and
    block the smart TOC from being auto-generated:

    * ``body-toc-generated`` paragraphs (a previously generated TOC was saved
      along with the body);
    * ``body-toc-heading`` / ``body-toc-entry`` paragraphs whose text has been
      deleted (empty placeholder).

    The renderer regenerates the TOC from current headings, so these placeholders
    are never needed. A genuine TOC imported from Word (non-empty, without the
    ``body-toc-generated`` class) is kept untouched.
    """
    if not content or "<p" not in content:
        return content
    if "body-toc-" not in content:
        return content

    def _repl(match: "re.Match[str]") -> str:
        classes = match.group(2) or ""
        inner_text = re.sub(r"<[^>]+>", "", match.group(0))
        inner_text = inner_text.replace("\xa0", " ").replace("\u3000", " ").strip()
        if "body-toc-generated" in classes or not inner_text:
            return ""
        return match.group(0)

    return _TOC_PLACEHOLDER_RE.sub(_repl, content)


def _split_article_paragraphs(content: str) -> list:
    text = _plain_article_text(content)
    text = re.sub(r'\r\n?', '\n', text or '')
    blocks = []
    if re.search(r'<\w+[^>]*>', content[:2000] if content else ''):
        soup = BeautifulSoup(content, 'html.parser')
        for node in soup.select('p, h1, h2, h3, h4, h5, h6, li, blockquote'):
            clean = re.sub(r'\s+', ' ', node.get_text(' ', strip=True)).strip()
            if not clean:
                continue
            tag = (node.name or '').lower()
            block_class = classify_article_block(
                clean,
                source_tag=tag,
                explicit_heading=tag.startswith('h'),
            )
            blocks.append((clean, block_class))
    else:
        raw_blocks = [b.strip() for b in re.split(r'\n{2,}', text) if b.strip()]
        for raw in raw_blocks:
            lines = [line.strip() for line in raw.split('\n') if line.strip()]
            if len(lines) > 1 and sum(bool(classify_article_block(line)) for line in lines) >= 1:
                candidates = lines
            else:
                candidates = [re.sub(r'\s+', ' ', raw).strip()]
            for clean in candidates:
                blocks.append((clean, classify_article_block(clean)))

    paragraphs = []
    offset = 0
    heading = ""
    for clean, block_class in blocks:
        if is_heading_class(block_class):
            heading = clean[:80]
        # 纯目录标题、元信息和过短装饰符不作为可引用正文段落。
        if block_class in {'body-toc-heading', 'body-document-meta', 'body-meta-line'}:
            continue
        if len(clean) < 2 or not re.search(r'[\u4e00-\u9fffA-Za-z0-9]', clean):
            continue
        start = text.find(clean, offset)
        if start < 0:
            start = offset
        end = start + len(clean)
        paragraphs.append({
            "paragraph_index": len(paragraphs) + 1,
            "text": clean[:4000],
            "char_start": start,
            "char_end": end,
            "heading": heading,
        })
        offset = end
    if not paragraphs and text.strip():
        compact = re.sub(r'\s+', ' ', text).strip()
        for i in range(0, len(compact), 1800):
            chunk = compact[i:i + 1800].strip()
            if chunk:
                paragraphs.append({
                    "paragraph_index": len(paragraphs) + 1,
                    "text": chunk,
                    "char_start": i,
                    "char_end": i + len(chunk),
                    "heading": "",
                })
    return paragraphs


def rebuild_article_paragraphs(conn: sqlite3.Connection, article_id: int, content: str = None) -> int:
    if content is None:
        row = conn.execute("SELECT content FROM articles WHERE id=?", (article_id,)).fetchone()
        if not row:
            return 0
        content = row["content"] or ""
    now = datetime.datetime.now().isoformat()
    paragraphs = _split_article_paragraphs(content)
    conn.execute("DELETE FROM article_paragraphs WHERE article_id=?", (article_id,))
    conn.executemany(
        """
        INSERT INTO article_paragraphs
        (article_id, paragraph_index, text, char_start, char_end, heading, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """,
        [
            (
                article_id,
                p["paragraph_index"],
                p["text"],
                p["char_start"],
                p["char_end"],
                p.get("heading", ""),
                now,
            )
            for p in paragraphs
        ]
    )
    return len(paragraphs)


def compute_hash(text: str) -> str:
    return hashlib.md5(text.encode('utf-8')).hexdigest()


def save_article(title, content, summary, domains, source_type, source_url=None, source_filename=None, source_localpath=None, tags=None, check_duplicate=True) -> int:
    """
    保存文章到数据库。

    Args:
        title: 文章标题
        content: 文章正文
        summary: 文章摘要
        domains: 领域分类
        source_type: 来源类型 (url|file|localpath)
        source_url: 来源URL (url类型)
        source_filename: 文件名 (file类型)
        source_localpath: 本地路径 (localpath类型)
        tags: 标签列表
        check_duplicate: 是否检查重复 (默认True)

    Returns:
        文章ID

    Raises:
        ValueError: 如果检测到重复文章
    """
    # 清理标题：去除首尾空白和异常空格
    title = ' '.join(title.strip().split())
    source_hash = compute_hash(content[:2000])
    conn = get_db()

    # 检查重复
    if check_duplicate:
        existing = conn.execute("SELECT id, title FROM articles WHERE source_hash=?", (source_hash,)).fetchone()
        if existing:
            conn.close()
            raise ValueError(f"文章已存在！\n已存在的文章标题：{existing['title']}")

    now = datetime.datetime.now().isoformat()
    tags_json = json.dumps(tags if tags else [], ensure_ascii=False)
    cur = conn.execute(
        """INSERT INTO articles (title, content, summary, domains, source_type, source_url, source_filename, source_localpath, source_hash, created_at, tags)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (title, content, summary, json.dumps(domains, ensure_ascii=False),
         source_type, source_url, source_filename, source_localpath, source_hash, now, tags_json)
    )
    conn.commit()
    article_id = cur.lastrowid
    try:
        rebuild_article_paragraphs(conn, article_id, content)
        conn.commit()
    except Exception as e:
        print(f"[paragraphs] build failed for article {article_id}: {e}")
    knowledge_job_created = False
    try:
        article_meta = {"title": title, "summary": summary, "domains": domains, "content": content}
        if is_knowledge_article(article_meta):
            _job_id, knowledge_job_created = create_extraction_job(
                conn, article_id, trigger_type="import", model=DEFAULT_AI_MODEL
            )
            conn.commit()
    except Exception as e:
        # 知识层提取不能阻断原始资料入库。
        print(f"[legal-knowledge] enqueue failed for article {article_id}: {e}")
    conn.close()
    if knowledge_job_created:
        try:
            _knowledge_worker_event.set()
        except NameError:
            pass
    return article_id


