@app.post("/api/submit/url")
async def submit_url(request: Request, background_tasks: BackgroundTasks):
    """提交网页链接（支持 JSON 和 Form 格式）

    支持从探索传入预抓取的正文内容（content），跳过重复抓取，
    保证排版与手动添加链接完全一致。
    """
    try:
        # 尝试解析 JSON 格式
        content_type = request.headers.get("content-type", "")
        if "application/json" in content_type:
            body = await request.json()
            url = body.get("url", "")
            fetch_url = body.get("fetch_url", "") or url
            title_override = body.get("title", "")
            source_override = body.get("source", "")
            domain_override = body.get("domain", "")
            # 探索预抓取的正文（保留段落结构）
            pre_content = body.get("content", "")
            pre_author = body.get("author", "") or ""
        else:
            data_form = await request.form()
            url = data_form.get("url", "")
            fetch_url = url
            title_override = ""
            source_override = ""
            domain_override = ""
            pre_content = ""
            pre_author = ""

        if not url:
            raise HTTPException(status_code=400, detail="URL不能为空")
        if fetch_url != url and not (is_authoritative_url(url) and is_authoritative_url(fetch_url)):
            raise HTTPException(status_code=400, detail="仅权威官网结果可使用独立文档提取地址")

        # ── 核心修复：探索预抓内容直接使用，跳过重复 fetch_webpage ──
        # 这样保证了排版与手动添加链接完全一致（extract_text_with_structure + normalize_content）
        if pre_content:
            # 预抓内容已包含正确的段落结构，再过一次 normalize_content 确保排版一致
            content = normalize_content(pre_content)
            # 从预抓内容中提取标题
            title = title_override if title_override else extract_title_from_text(pre_content, "")
            # 从预抓内容中提取作者
            author = pre_author
            if not author:
                # 从正文中提取作者
                author_match = re.search(r'作者[:：]\s*([^\s，,。.]+)', pre_content[:500])
                if author_match:
                    author = author_match.group(1).strip()
            print(f"[DEBUG] submit_url (探索预抓): author='{author}', content_len={len(content)}")
        elif 'mp.weixin.qq.com' in fetch_url:
            # 微信公众号：优先用浏览器动态加载，静态 requests 容易只拿到装饰图或残缺正文。
            try:
                data = await fetch_weixin_article_async(fetch_url)
                # 动态请求成功不等于正文提取成功。质量不足时立即转静态抓取；
                # 部分微信文章在浏览器执行脚本后 DOM 反而会丢失原始正文。
                ensure_meaningful_weixin_content(data.get("content", ""), fetch_url)
            except Exception as weixin_e:
                print(f"[DEBUG] dynamic weixin fetch failed: {weixin_e}")
                try:
                    data = await run_in_threadpool(fetch_webpage, fetch_url)
                except Exception as static_e:
                    raise HTTPException(
                        status_code=400,
                        detail=f"微信公众号正文抓取失败：动态抓取失败：{weixin_e}；静态抓取失败：{static_e}"
                    )
            content = data["content"]
            ensure_meaningful_weixin_content(content, fetch_url)
            title = data["title"]
            if title_override:
                title = title_override
            else:
                title_override = title
            author = data.get("author", "")
        elif 'toutiao.com' in fetch_url:
            # 今日头条：异步抓取
            data = await fetch_toutiao_article_async(fetch_url)
            content = data["content"]
            title = data["title"]
            if title_override:
                title = title_override
            else:
                title_override = title
            author = data.get("author", "")
        else:
            # 普通链接：抓取 + 排版（与手动添加链接完全相同）
            data = fetch_webpage(fetch_url)
            content = data["content"]
            title = data["title"]
            if title_override:
                title = title_override
            else:
                title_override = title
            author = data.get("author", "")
        print(f"[DEBUG] submit_url: author='{author}', type={type(author)}")
        processing_text = html_to_processing_text(content)
        if not is_meaningful_article_text(processing_text, min_len=50):
            if 'mp.weixin.qq.com' in url and '<img' in content:
                raise HTTPException(
                    status_code=400,
                    detail="该微信文章正文主要以图片或动态内容呈现，系统未能识别出足够的可检索文字；请尝试复制正文粘贴导入，或上传原始文档。"
                )
            if len(content) < 50:
                raise HTTPException(status_code=400, detail="无法提取有效正文，请检查链接是否可访问")
        # 先用规则摘要完成入库；AI 摘要在响应返回后于后台更新。
        summary_source = processing_text if processing_text else content
        summary = extract_summary(summary_source)
        domains = classify_domains(summary_source + " " + title)

        # 构建tags：确保所有文章都有作者标签
        tags = []
        if author and author.strip():
            tags.append(f"作者:{author}")
            print(f"[DEBUG] Added author tag: {tags}")
        else:
            # 如果没有提取到作者,添加默认作者标签
            tags.append("作者:未知")
            print(f"[DEBUG] No author found, added default tag: {tags}")

        # 添加来源标签（扩充自检来源）
        if source_override:
            tags.append(f"来源:{source_override}")

        # 不再自动打自定义标签（domains 字段仍由 classify_domains 生成）

        try:
            article_id = save_article(
                title=title, content=content, summary=summary,
                domains=domains, source_type="url", source_url=url,
                tags=tags, check_duplicate=True
            )
            ai_summary_pending = is_meaningful_article_text(summary_source, min_len=80)
            if ai_summary_pending:
                background_tasks.add_task(
                    _generate_and_store_ai_summary,
                    article_id,
                    title,
                    summary_source,
                    summary,
                )
            print(f"[DEBUG] Saved article with tags: {tags}")
            return {
                "success": True,
                "id": article_id,
                "title": title,
                "domains": domains,
                "summary": summary,
                "ai_summary": False,
                "ai_summary_pending": ai_summary_pending,
            }
        except ValueError as e:
            # 重复文章
            # 返回既有文章 id，供飞书在此前摘要生成失败时继续重试；普通前端
            # 仍可按 duplicate 字段维持原有交互。
            conn = get_db()
            try:
                existing = conn.execute(
                    "SELECT id,title,content,summary FROM articles WHERE source_url=? ORDER BY id DESC LIMIT 1",
                    (url,),
                ).fetchone()
            finally:
                conn.close()
            existing_text = html_to_processing_text(existing["content"] or "") if existing else ""
            return {
                "success": False,
                "duplicate": True,
                "message": str(e),
                "id": existing["id"] if existing else None,
                "title": existing["title"] if existing else title,
                "summary": existing["summary"] if existing else "",
                "ai_summary": False,
                "ai_summary_pending": bool(existing and is_meaningful_article_text(existing_text, min_len=80)),
            }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"抓取失败：{str(e)}")


@app.post("/api/submit/file")
async def submit_file(
    background_tasks: BackgroundTasks,
    file: UploadFile = File(...),
    pdf_image_mode: int = Form(0),
):
    """上传文档文件。

    pdf_image_mode=1 且文件为 PDF 时走「PDF 不解析为文本」模式：
    逐页渲染为图片平铺进正文，文字层仅供阅读时选中文字作笔记。
    """
    suffix = Path(file.filename).suffix.lower()
    if suffix not in ['.pdf', '.docx', '.doc', '.txt', '.xlsx', '.xls']:
        raise HTTPException(status_code=400, detail="仅支持 PDF、Word (.docx)、Excel (.xlsx)、TXT 格式")
    save_path = UPLOAD_DIR / file.filename
    async with aiofiles.open(str(save_path), 'wb') as f:
        await f.write(await file.read())
    try:
        # 解析放入线程池执行：扫描件 OCR 内含同步网络请求与 sleep，
        # 直接在事件循环中运行会阻塞整个服务长达数分钟
        if suffix == '.pdf' and pdf_image_mode:
            data = await run_in_threadpool(parse_pdf_as_pages, str(save_path))
            content = data["content"]
            title = data["title"]
            ocr_used = data.get("ocr_used", False)
            page_count = data.get("page_count", 0)
            plain_text = data.get("text", "")
            if len(re.sub(r'\s+', '', plain_text or '')) < 20:
                raise HTTPException(
                    status_code=400,
                    detail="PDF 无法生成可选中文字层：页面既无文字层，本机 OCR 也未识别到内容，"
                           "请确认图像质量或关闭「PDF 不解析为文本」",
                )
            # 摘要与领域打标使用页面提取文本，正文存按页平铺的图片 HTML
            summary = extract_summary(plain_text)
            domains = classify_domains(plain_text + " " + title)
        else:
            if suffix == '.docx' or suffix == '.doc':
                data = await run_in_threadpool(parse_docx, str(save_path))
            elif suffix == '.pdf':
                data = await run_in_threadpool(parse_pdf, str(save_path))
            elif suffix in ('.xlsx', '.xls'):
                data = await run_in_threadpool(parse_xlsx, str(save_path))
            else:
                data = await run_in_threadpool(parse_txt, str(save_path))
            content = data["content"]
            title = data["title"]
            ocr_used = data.get("ocr_used", False)
            page_count = data.get("page_count", 0)
            if len(content) < 20:
                if ocr_used:
                    raise HTTPException(status_code=400, detail="扫描件 OCR 识别结果为空，请检查 PDF 图像质量是否清晰")
                elif suffix == '.pdf' and page_count > 0:
                    raise HTTPException(status_code=400, detail="PDF 文档内容为空，若为扫描件请确认网络连接正常后重试（系统会自动调用 OCR 识别）")
                else:
                    raise HTTPException(status_code=400, detail="文档内容为空或无法解析")
            # 规则摘要随正文立即入库，AI 摘要改由后台生成。
            summary = extract_summary(content)
            domains = classify_domains(content + " " + title)
        
        # 确保所有文章都有作者标签（不再自动打自定义标签）
        tags = ["作者:未知"]
        
        try:
            article_id = save_article(
                title=title, content=content, summary=summary,
                domains=domains, source_type="file", source_filename=file.filename,
                tags=tags, check_duplicate=True
            )
            background_tasks.add_task(
                _generate_and_store_ai_summary,
                article_id,
                title,
                content,
                summary,
            )
            return {
                "success": True,
                "id": article_id,
                "title": title,
                "domains": domains,
                "summary": summary,
                "ai_summary": False,
                "ai_summary_pending": True,
                "ocr_used": ocr_used,
                "pdf_pages": bool(pdf_image_mode and suffix == '.pdf'),
            }
        except ValueError as e:
            # 重复文章
            return {"success": False, "duplicate": True, "message": str(e)}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"解析失败：{str(e)}\n{traceback.format_exc()}")


class _FeishuArticleSubmitRequest:
    """Minimal request adapter so Feishu imports follow the normal URL workflow."""
    headers = {"content-type": "application/json"}

    def __init__(self, url: str):
        self._body = {"url": url}

    async def json(self):
        return self._body


async def _import_feishu_article_url(url: str) -> Dict[str, Any]:
    # Reuse the same fetch, validation, de-duplication and article-list insertion
    # path as a link submitted from the local user interface.
    result = await submit_url(_FeishuArticleSubmitRequest(url), BackgroundTasks())
    # submit_url 把 AI 摘要任务加在入参 background_tasks 上，只有在通过
    # FastAPI 请求生命周期调用时才会被执行。飞书同步是直接函数调用，这里
    # 必须显式调度，否则新收录文章永远停留在规则摘要（正文片段）。
    if (
        result.get("ai_summary_pending")
        and result.get("id")
    ):
        article_id = int(result["id"])
        conn = get_db()
        try:
            row = conn.execute(
                "SELECT title, content, summary FROM articles WHERE id=?", (article_id,)
            ).fetchone()
        finally:
            conn.close()
        if row:
            processing_text = html_to_processing_text(row["content"] or "")
            # 飞书同步不再派发一个无人跟踪的临时任务。等待摘要实际写入后再
            # 将表单记录标记为已同步，避免进程重启或调用失败后永久保留规则摘要。
            ai_summary_saved = await _generate_and_store_ai_summary(
                article_id,
                row["title"] or "",
                processing_text,
                row["summary"] or "",
            )
            if ai_summary_saved:
                result["ai_summary"] = True
                result["ai_summary_pending"] = False
                with get_db() as refreshed_conn:
                    refreshed = refreshed_conn.execute(
                        "SELECT summary FROM articles WHERE id=?", (article_id,)
                    ).fetchone()
                if refreshed:
                    result["summary"] = refreshed["summary"] or result.get("summary", "")
            else:
                # 交给飞书同步器保留“摘要待重试”状态，下一轮继续调用最新模型。
                result["ai_summary_pending"] = True
    return result


from .platform_capabilities import enabled as platform_enabled, register_routes as register_platform_routes
register_platform_routes(app)
if platform_enabled("feishu"):
    from .feishu_article_sync import register_feishu_article_routes
    register_feishu_article_routes(app, get_db, _import_feishu_article_url)


@app.get("/api/articles")
def list_articles(
    q: Optional[str] = None,
    fuzzy: bool = True,
    domain: Optional[str] = None,
    subcategory_id: Optional[int] = None,
    classification_status: Optional[str] = None,
    author: Optional[str] = None,
    custom_tag: Optional[str] = None,
    custom_tags: Optional[str] = None,   # 逗号分隔的多个标签名（二级目录筛选）
    source_type: Optional[str] = None,
    search_scope: Optional[str] = None,  # 搜索范围：all/title/summary/content/tags/notes
    page: int = Query(1, ge=1),
    page_size: int = Query(20, ge=1, le=100),
    tag_group_id: Optional[int] = None,  # 标签组ID，支持按标签组返回置顶状态
    pin_scope: Optional[str] = None,     # 当前文章列表置顶作用域
):
    """获取文章列表，支持搜索和筛选（包括笔记内容）"""
    conn = get_db()
    conditions = []
    params = []
    scope = "all"  # 搜索范围默认值

    # ── 搜索范围映射 ──
    # scope → (字段列表, 是否需要子查询 notes)
    SCOPE_FIELDS = {
        "title":   ["title"],
        "summary": ["summary"],
        "content": ["content"],
        "tags":    ["tags"],
        "notes":   [],       # 特殊处理：走子查询
        "all":     ["title", "content", "summary"],
    }

    # 作者搜索特殊处理：精确匹配标签前缀 "作者:query"
    # 不走 SCOPE_FIELDS，在下方独立处理
    is_author_scope = (search_scope == "author")
    fts_ids = []

    if q:
        # 移除搜索词前后的空格
        q = q.strip()
        escaped_q = q.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')

        if is_author_scope:
            # 作者范围只匹配作者标签，不额外要求作者名出现在标题或正文中。
            scope = "author"
            conditions.append("tags LIKE ? ESCAPE '\\'")
            params.append(f"%作者:{escaped_q}%")
        else:
            scope = search_scope if search_scope in SCOPE_FIELDS else "all"
            fields = SCOPE_FIELDS[scope]
            if fuzzy and scope != "notes":
                fts_columns = None if scope == "all" else fields
                fts_ids = search_article_ids(conn, q, columns=fts_columns)

        if is_author_scope:
            pass
        elif scope == "notes":
            # 仅搜索笔记
            like = f"%{escaped_q}%"
            conditions.append("""
                id IN (
                    SELECT DISTINCT article_id FROM notes
                    WHERE content LIKE ? ESCAPE '\\' OR selected_text LIKE ? ESCAPE '\\'
                )
            """)
            params += [like, like]
        else:
            # 按指定字段搜索（可能含笔记子查询）
            like_parts = []
            like = f"%{escaped_q}%"
            for field in fields:
                like_parts.append(f"{field} LIKE ? ESCAPE '\\'")
                params.append(like)
            # "全部"模式下也搜索笔记
            if scope == "all":
                like_parts.append("""
                    id IN (
                        SELECT DISTINCT article_id FROM notes
                        WHERE content LIKE ? ESCAPE '\\' OR selected_text LIKE ? ESCAPE '\\'
                    )
                """)
                params += [like, like]
            if fts_ids:
                like_parts.append("id IN (" + ",".join("?" * len(fts_ids)) + ")")
                params += fts_ids
            conditions.append("(" + " OR ".join(like_parts) + ")")

    if domain:
        conditions.append("EXISTS (SELECT 1 FROM json_each(articles.domains) d WHERE d.value=?)")
        params.append(domain)

    if subcategory_id is not None:
        conditions.append("articles.id IN (SELECT article_id FROM article_subcategory_choices WHERE subcategory_id=? AND mode<>'excluded')")
        params.append(subcategory_id)

    if classification_status == "needs_review":
        conditions.append("id IN (SELECT article_id FROM domain_classification_jobs WHERE status='needs_review')")

    if author:
        conditions.append("tags LIKE ?")
        params.append(f'%作者:{author}%')

    if custom_tag:
        conditions.append("tags LIKE ?")
        params.append(f'%"{custom_tag}"%')

    if custom_tags:
        # 多个标签名（OR 关系，匹配任一标签即可）
        tag_list = [t.strip() for t in custom_tags.split(',') if t.strip()]
        if tag_list:
            sub_conditions = ["tags LIKE ?"] * len(tag_list)
            conditions.append("(" + " OR ".join(sub_conditions) + ")")
            params += [f'%"{t}"%' for t in tag_list]

    if source_type:
        conditions.append("source_type = ?")
        params.append(source_type)

    where = ("WHERE " + " AND ".join(conditions)) if conditions else ""
    total = conn.execute(f"SELECT COUNT(*) FROM articles {where}", params).fetchone()[0]

    offset = (page - 1) * page_size
    fts_order = case_order_expression(fts_ids)
    if not pin_scope:
        if tag_group_id is not None:
            pin_scope = f"tag_group:{tag_group_id}"
        elif domain:
            pin_scope = f"domain:{domain}"
        elif author:
            pin_scope = f"author:{author}"
        elif custom_tag:
            pin_scope = f"tag:{custom_tag}"
        elif custom_tags:
            pin_scope = "custom_tags:" + hashlib.sha1(custom_tags.encode("utf-8")).hexdigest()
        elif source_type:
            pin_scope = f"source:{source_type}"
        else:
            pin_scope = "view:all"
    if pin_scope:
        pin_scope = pin_scope.strip()[:200]

    # ── 置顶状态计算逻辑 ──
    # pin_scope 表示当前文章列表；置顶只在该列表作用域内生效。
    if pin_scope:
        select_cols = "articles.id, articles.title, articles.summary, articles.content, articles.domains, articles.source_type, articles.source_url, articles.source_filename, articles.source_localpath, articles.created_at, articles.tags, articles.pinned"
        query = f"""
            SELECT {select_cols},
                   COALESCE(list_pin.pinned, 0) AS effective_pinned
            FROM articles
            LEFT JOIN article_list_pins list_pin
                   ON list_pin.article_id = articles.id
                   AND list_pin.list_key = ?
            {where}
            ORDER BY effective_pinned DESC{', ' + fts_order if fts_order else ''}, articles.created_at DESC
            LIMIT ? OFFSET ?
        """
        rows = conn.execute(query, [pin_scope] + params + [page_size, offset]).fetchall()
    else:
        rows = []
    child_labels = article_subcategory_labels(conn, [row["id"] for row in rows])
    conn.close()

    def extract_content_snippets(content: str, keyword: str, context: int = 60) -> list:
        """从正文中提取关键词命中的上下文片段列表（不限数量）"""
        if not keyword or not content:
            return []
        # 先剥离 HTML 标签，避免片段中包含 <p>、</p> 等裸标签
        import re as _re
        plain = _re.sub(r'<[^>]+>', '', content)
        # 还原常见 HTML 实体
        plain = plain.replace('&amp;', '&').replace('&lt;', '<').replace('&gt;', '>') \
                     .replace('&quot;', '"').replace('&#039;', "'").replace('&nbsp;', ' ')
        kw_lower = keyword.lower()
        text_lower = plain.lower()
        snippets = []
        start = 0
        while True:
            idx = text_lower.find(kw_lower, start)
            if idx == -1:
                break
            s = max(0, idx - context)
            e = min(len(plain), idx + len(keyword) + context)
            prefix = '…' if s > 0 else ''
            suffix = '…' if e < len(plain) else ''
            snippets.append({
                "text": prefix + plain[s:e] + suffix,
                "offset": idx   # 关键词在纯文本中的字符偏移，供前端定位
            })
            start = idx + len(keyword)
        return snippets

    articles = []
    for r in rows:
        a = dict(r)
        a["domains"] = json.loads(a["domains"] or "[]")
        a["tags"] = json.loads(a["tags"] or "[]")
        a["subcategories"] = child_labels.get(a["id"], [])
        a["subcategory_ids"] = [child["id"] for child in a["subcategories"]]
        # 列表置顶优先：若查询中有 effective_pinned 字段则用它，否则用 articles.pinned
        if "effective_pinned" in a:
            a["pinned"] = bool(a.pop("effective_pinned"))
        else:
            a["pinned"] = bool(a.get("pinned", 0))
        # 当有搜索词且正文命中时，附加上下文片段
        # 仅在搜索范围包含"正文"（scope=all 或 scope=content）时提取
        if q and a.get("content") and scope in ("all", "content"):
            a["content_snippets"] = extract_content_snippets(a["content"], q)
        else:
            a["content_snippets"] = []
        del a["content"]  # 不在列表接口中返回全文
        articles.append(a)

    return {"total": total, "page": page, "page_size": page_size, "articles": articles}


ARTICLE_OFFLINE_MAX_CONTENT_BYTES = 800 * 1024


@app.get("/api/articles/offline-snapshot")
def articles_offline_snapshot(limit: int = 100):
    """最近文章离线快照：排除超大正文，避免浏览器离线缓存占用过多内存。"""
    max_items = max(1, min(int(limit or 100), 200))
    conn = get_db()
    rows = conn.execute(
        """SELECT * FROM articles
           WHERE length(CAST(content AS BLOB)) <= ?
           ORDER BY datetime(created_at) DESC, id DESC
           LIMIT ?""",
        (ARTICLE_OFFLINE_MAX_CONTENT_BYTES, max_items),
    ).fetchall()
    excluded_oversized = conn.execute(
        "SELECT COUNT(*) FROM articles WHERE length(CAST(content AS BLOB)) > ?",
        (ARTICLE_OFFLINE_MAX_CONTENT_BYTES,),
    ).fetchone()[0]
    children = {}
    snapshot_ids = [row["id"] for row in rows]
    placeholders = ",".join("?" for _ in snapshot_ids) or "NULL"
    for row in conn.execute(f"SELECT article_id,subcategory_id FROM article_subcategory_choices WHERE mode<>'excluded' AND article_id IN ({placeholders})", snapshot_ids):
        children.setdefault(row[0], []).append(row[1])
    statuses = {row[0]: row[1] for row in conn.execute(f"SELECT article_id,status FROM domain_classification_jobs WHERE article_id IN ({placeholders})", snapshot_ids)}
    conn.close()
    articles = []
    allowed_fields = {
        "id",
        "title",
        "content",
        "summary",
        "domains",
        "source_type",
        "source_url",
        "source_filename",
        "created_at",
        "tags",
        "pinned",
    }
    for row in rows:
        raw = dict(row)
        a = {key: raw.get(key) for key in allowed_fields}
        a["domains"] = json.loads(a["domains"] or "[]")
        a["tags"] = json.loads(a["tags"] or "[]")
        a["pinned"] = bool(a.get("pinned", 0))
        a["subcategory_ids"] = children.get(a["id"], [])
        a["classification_status"] = statuses.get(a["id"], "done")
        articles.append(a)
    return {
        "version": 3,
        "generated_at": datetime.datetime.now().isoformat(timespec="seconds"),
        "limit": max_items,
        "max_content_bytes": ARTICLE_OFFLINE_MAX_CONTENT_BYTES,
        "excluded_oversized": excluded_oversized,
        "articles": articles,
    }


class ArticleTrashSelection(BaseModel):
    trash_ids: List[int] = Field(default_factory=list)
    clear_all: bool = False


@app.get("/api/articles/trash")
def get_article_trash(limit: int = Query(100, ge=1, le=200), offset: int = Query(0, ge=0)):
    """List recoverable articles; each item expires 30 days after deletion."""
    conn = get_db()
    try:
        purge_expired_articles(conn)
        conn.commit()
        return list_trashed_articles(conn, limit, offset)
    finally:
        conn.close()


@app.post("/api/articles/trash/restore")
def restore_article_trash(body: ArticleTrashSelection):
    ids = list(dict.fromkeys(article_id for article_id in body.trash_ids if article_id > 0))
    if not ids or len(ids) > 500:
        raise HTTPException(status_code=400, detail="请选择1至500篇待恢复文章")
    conn = get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        purge_expired_articles(conn)
        result = restore_trashed_articles(conn, ids)
        conn.commit()
        return {"success": True, **result}
    except TrashRestoreConflict as exc:
        conn.rollback()
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except Exception as exc:
        conn.rollback()
        raise HTTPException(status_code=500, detail=f"恢复文章失败: {exc}") from exc
    finally:
        conn.close()


@app.delete("/api/articles/trash")
def purge_article_trash(body: ArticleTrashSelection):
    ids = list(dict.fromkeys(article_id for article_id in body.trash_ids if article_id > 0))
    if not body.clear_all and (not ids or len(ids) > 500):
        raise HTTPException(status_code=400, detail="请选择1至500篇待彻底删除文章")
    conn = get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        purge_expired_articles(conn)
        deleted_count = purge_trashed_articles(conn, None if body.clear_all else ids)
        conn.commit()
        return {"success": True, "deleted_count": deleted_count}
    except Exception as exc:
        conn.rollback()
        raise HTTPException(status_code=500, detail=f"清理回收站失败: {exc}") from exc
    finally:
        conn.close()


def _cleanup_expired_article_trash() -> int:
    conn = get_db()
    try:
        count = purge_expired_articles(conn)
        conn.commit()
        return count
    finally:
        conn.close()


_article_trash_cleanup_task = None


async def _article_trash_cleanup_loop():
    while True:
        try:
            await run_in_threadpool(_cleanup_expired_article_trash)
        except Exception as exc:
            print(f"[article-trash] cleanup failed: {exc}")
        await asyncio.sleep(3600)


@app.on_event("startup")
async def start_article_trash_cleanup():
    global _article_trash_cleanup_task
    if _article_trash_cleanup_task is None or _article_trash_cleanup_task.done():
        _article_trash_cleanup_task = asyncio.create_task(_article_trash_cleanup_loop())


@app.on_event("shutdown")
async def stop_article_trash_cleanup():
    global _article_trash_cleanup_task
    if _article_trash_cleanup_task:
        _article_trash_cleanup_task.cancel()
        _article_trash_cleanup_task = None


def article_subcategory_labels(conn, article_ids):
    """Resolve confirmed choices in one query; excluded choices are not labels."""
    result = {article_id: [] for article_id in article_ids}
    if not article_ids:
        return result
    placeholders = ",".join("?" for _ in article_ids)
    rows = conn.execute(f"""
        SELECT choice.article_id, child.id, child.name, child.parent_id, parent.name AS domain
        FROM article_subcategory_choices choice
        JOIN domain_taxonomy child ON child.id=choice.subcategory_id
        JOIN domain_taxonomy parent ON parent.id=child.parent_id
        WHERE choice.article_id IN ({placeholders}) AND choice.mode<>'excluded'
        ORDER BY parent.sort_order,parent.id,child.sort_order,child.id
    """, article_ids)
    for row in rows:
        result[row["article_id"]].append({key: row[key] for key in ("id", "name", "parent_id", "domain")})
    return result


@app.get("/api/articles/{article_id}")
def get_article(article_id: int):
    """获取文章详情"""
    conn = get_db()
    row = conn.execute("SELECT * FROM articles WHERE id=?", (article_id,)).fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="文章不存在")
    a = dict(row)
    a["domains"] = json.loads(a["domains"] or "[]")
    a["tags"] = json.loads(a["tags"] or "[]")
    a["subcategories"] = article_subcategory_labels(conn, [article_id])[article_id]
    a["subcategory_ids"] = [child["id"] for child in a["subcategories"]]
    classification = conn.execute("SELECT status FROM domain_classification_jobs WHERE article_id=?", (article_id,)).fetchone()
    a["classification_status"] = classification[0] if classification else "done"
    a.pop("starred", None)  # 兼容旧数据库列，但不再向客户端暴露已移除功能
    a["pinned"] = bool(a.get("pinned", 0))
    conn.close()
    return a


@app.post("/api/articles/blank")
async def create_blank_article(request: Request):
    """Create a user-authored knowledge item without importing a source file."""
    body = await request.json()
    title = str(body.get("title") or "未命名知识").strip()[:200] or "未命名知识"
    # source_hash has a database uniqueness constraint. Give every new blank article
    # an invisible seed so users can create more than one empty knowledge item.
    blank_content = f'<p style="--manual-article-seed:{uuid.uuid4().hex}"><br></p>'
    article_id = save_article(
        title=title,
        content=blank_content,
        summary="",
        domains=[],
        source_type="manual",
        tags=[],
        check_duplicate=False,
    )
    return {"success": True, "id": article_id, "title": title}


@app.get("/api/files/open")
def open_file(filename: str, request: Request):
    """打开本地文件"""
    require_remote_management_enabled(request)
    file_path = UPLOAD_DIR / filename
    if not file_path.exists():
        raise HTTPException(status_code=404, detail=f"文件不存在：{filename}")

    try:
        import subprocess
        import platform

        system = platform.system()
        if system == "Darwin":  # macOS
            subprocess.run(["open", str(file_path)], check=True)
        elif system == "Linux":
            subprocess.run(["xdg-open", str(file_path)], check=True)
        elif system == "Windows":
            os.startfile(str(file_path))
        else:
            raise HTTPException(status_code=500, detail=f"不支持的操作系统：{system}")

        return {"success": True, "message": f"已打开文件：{filename}"}
    except subprocess.CalledProcessError as e:
        raise HTTPException(status_code=500, detail=f"打开文件失败：{str(e)}")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"打开文件失败：{str(e)}")


@app.post("/api/submit/localpath")
async def submit_localpath(request: Request, background_tasks: BackgroundTasks, path: str = Form(...)):
    """通过本地文件路径导入文件（支持 PDF、Word、TXT 及无后缀文本文件）"""
    require_remote_management_enabled(request)
    import platform

    local_path = Path(path.strip())

    # 安全检查：路径不能是目录
    if local_path.is_dir():
        raise HTTPException(status_code=400, detail=f"该路径是一个目录，请提供文件路径：{path}")

    # 若路径不存在，尝试两种模糊匹配方式
    if not local_path.exists():
        found = None

        # 方式1: 简单拼接后缀（针对用户漏掉后缀的情况）
        for ext in ['.pdf', '.docx', '.doc', '.txt']:
            candidate = Path(str(local_path) + ext)
            if candidate.exists():
                found = candidate
                break

        # 方式2: 通过目录扫描匹配（针对路径中间有多余空格或小拼写错误的情况）
        if not found:
            # 提取文件名（不带后缀）
            target_name = local_path.name
            parent = local_path.parent

            # 找到第一个存在的父目录（逐级向上查找）
            search_start = parent
            while search_start != Path('.') and not search_start.exists():
                search_start = search_start.parent

            if search_start.exists() and search_start.is_dir():
                # 从搜索起始点开始，逐级匹配子目录和文件
                # 提取从搜索起始点开始的相对路径部分
                relative_parts = list(local_path.relative_to(search_start).parts)
                if len(relative_parts) > 1:
                    # 有子目录需要匹配
                    current_dir = search_start
                    matched = True

                    # 逐个匹配中间的子目录（忽略空格）
                    for part in relative_parts[:-1]:  # 最后一个部分是文件名
                        part_normalized = part.replace(' ', '')
                        dir_found = None
                        for item in current_dir.iterdir():
                            if item.is_dir():
                                item_normalized = item.name.replace(' ', '')
                                # 模糊匹配：是否包含关系
                                if part_normalized in item_normalized or item_normalized in part_normalized:
                                    dir_found = item
                                    break
                        if dir_found:
                            current_dir = dir_found
                        else:
                            matched = False
                            break

                    if matched:
                        # 匹配文件
                        for item in current_dir.iterdir():
                            if item.is_file():
                                item_name_no_ext = item.stem
                                if target_name.lower().replace(' ', '') in item_name_no_ext.lower().replace(' ', '') or \
                                   item_name_no_ext.lower().replace(' ', '') in target_name.lower().replace(' ', ''):
                                    found = item
                                    break
                else:
                    # 直接在当前目录匹配文件
                    for item in current_dir.iterdir():
                        if item.is_file():
                            item_name_no_ext = item.stem
                            if target_name.lower().replace(' ', '') in item_name_no_ext.lower().replace(' ', '') or \
                               item_name_no_ext.lower().replace(' ', '') in target_name.lower().replace(' ', ''):
                                found = item
                                break

        if found:
            local_path = found
        else:
            raise HTTPException(status_code=404, detail=f"文件不存在，请检查路径是否正确：{path}")

    suffix = local_path.suffix.lower()
    supported = ['.pdf', '.docx', '.doc', '.txt', '.xlsx', '.xls', '']
    if suffix not in supported:
        raise HTTPException(status_code=400, detail=f"暂不支持该文件格式「{suffix or '无后缀'}」，支持：PDF、Word (.docx)、Excel (.xlsx)、TXT 及无后缀文本文件")

    try:
        # 解析放入线程池执行：扫描件 OCR 内含同步网络请求与 sleep，
        # 直接在事件循环中运行会阻塞整个服务长达数分钟
        if suffix == '.docx' or suffix == '.doc':
            data = await run_in_threadpool(parse_docx, str(local_path))
        elif suffix == '.pdf':
            data = await run_in_threadpool(parse_pdf, str(local_path))
        elif suffix in ('.xlsx', '.xls'):
            data = await run_in_threadpool(parse_xlsx, str(local_path))
        else:
            # .txt 或无后缀，尝试文本解析
            data = await run_in_threadpool(parse_txt, str(local_path))

        content = data["content"]
        # 若解析标题为空，用文件名（不含后缀）作为标题
        title = data.get("title") or local_path.stem or local_path.name
        ocr_used = data.get("ocr_used", False)
        page_count = data.get("page_count", 0)

        if len(content) < 20:
            if ocr_used:
                raise HTTPException(status_code=400, detail="扫描件 OCR 识别结果为空，请检查 PDF 图像质量是否清晰")
            elif suffix == '.pdf' and page_count > 0:
                raise HTTPException(status_code=400, detail="PDF 文档内容为空，若为扫描件请确认网络连接正常后重试（系统会自动调用 OCR 识别）")
            else:
                raise HTTPException(status_code=400, detail="文件内容为空或无法解析，请检查文件是否正常")

        # 规则摘要随正文立即入库，AI 摘要改由后台生成。
        summary = extract_summary(content)
        domains = classify_domains(content + " " + title)

        # 确保所有文章都有作者标签（不再自动打自定义标签）
        tags = ["作者:未知"]

        try:
            article_id = save_article(
                title=title,
                content=content,
                summary=summary,
                domains=domains,
                source_type="file",
                source_localpath=str(local_path),
                tags=tags, check_duplicate=True
            )
            background_tasks.add_task(
                _generate_and_store_ai_summary,
                article_id,
                title,
                content,
                summary,
            )
            return {
                "success": True,
                "id": article_id,
                "title": title,
                "domains": domains,
                "summary": summary,
                "ai_summary": False,
                "ai_summary_pending": True,
                "ocr_used": ocr_used,
                "source_localpath": str(local_path)
            }
        except ValueError as e:
            # 重复文章
            return {
                "success": False,
                "duplicate": True,
                "message": str(e)
            }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"解析失败：{str(e)}\n{traceback.format_exc()}")


@app.get("/api/files/open_localpath")
def open_localpath(path: str, request: Request):
    """按本地绝对路径打开文件"""
    require_remote_management_enabled(request)
    import subprocess
    import platform

    local_path = Path(path)

    # 优化：如果路径直接存在，立即打开，跳过所有模糊匹配逻辑
    if local_path.exists():
        try:
            system = platform.system()
            if system == "Darwin":
                subprocess.run(["open", str(local_path)], check=True)
            elif system == "Linux":
                subprocess.run(["xdg-open", str(local_path)], check=True)
            elif system == "Windows":
                os.startfile(str(local_path))
            else:
                raise HTTPException(status_code=500, detail=f"不支持的操作系统：{system}")
            return {"success": True, "message": f"已打开：{local_path.name}"}
        except subprocess.CalledProcessError as e:
            raise HTTPException(status_code=500, detail=f"打开文件失败：{str(e)}")
        except Exception as e:
            raise HTTPException(status_code=500, detail=f"打开文件失败：{str(e)}")

    # 文件不存在时才进行模糊匹配（简化版，限制目录扫描）
    found = None

    # 方式1: 简单拼接后缀（最快的匹配方式）
    for ext in ['.pdf', '.docx', '.doc', '.txt']:
        candidate = Path(str(local_path) + ext)
        if candidate.exists():
            found = candidate
            break

    # 方式2: 轻量级目录扫描（仅扫描一级，避免深度遍历）
    if not found:
        target_name = local_path.name
        parent = local_path.parent

        if parent.exists() and parent.is_dir():
            for item in parent.iterdir():
                if item.is_file():
                    item_name_no_ext = item.stem
                    # 快速模糊匹配：忽略空格比较
                    if target_name.replace(' ', '') == item_name_no_ext.replace(' ', ''):
                        found = item
                        break

    if found:
        try:
            system = platform.system()
            if system == "Darwin":
                subprocess.run(["open", str(found)], check=True)
            elif system == "Linux":
                subprocess.run(["xdg-open", str(found)], check=True)
            elif system == "Windows":
                os.startfile(str(found))
            else:
                raise HTTPException(status_code=500, detail=f"不支持的操作系统：{system}")
            return {"success": True, "message": f"已打开：{found.name}"}
        except subprocess.CalledProcessError as e:
            raise HTTPException(status_code=500, detail=f"打开文件失败：{str(e)}")
        except Exception as e:
            raise HTTPException(status_code=500, detail=f"打开文件失败：{str(e)}")

    raise HTTPException(status_code=404, detail=f"文件不存在：{path}")



