@app.put("/api/articles/{article_id}/content")
async def update_article_content(article_id: int, request: Request):
    """更新文章正文内容，支持 JSON 大文本，兼容旧 Form 提交。"""
    content_type = request.headers.get("content-type", "")
    if "application/json" in content_type:
        body = await request.json()
        content = body.get("content", "")
    else:
        form = await request.form()
        content = form.get("content", "")
    if not isinstance(content, str) or not content.strip():
        raise HTTPException(status_code=400, detail="正文内容不能为空")

    # 目录占位残留（历史生成的目录被存进正文 / 文字已删空的目录段）会阻止
    # 智能目录自动生成，入库前统一剥离；渲染时会按当前标题重新生成。
    content = strip_stale_toc_placeholders(content)

    conn = get_db()
    current = conn.execute("SELECT content FROM articles WHERE id=?", (article_id,)).fetchone()
    if not current:
        conn.close()
        raise HTTPException(status_code=404, detail="文章不存在")
    if (current["content"] or "") == content:
        conn.close()
        return {
            "success": True,
            "content": content,
            "unchanged": True,
            "knowledge_claims_invalidated": [],
            "knowledge_job_id": None,
        }
    affected_claims = mark_article_claims_needs_review(conn, article_id, "原文章正文已修改，需重新核验")
    conn.execute(
        "UPDATE articles SET content=? WHERE id=?",
        (content, article_id)
    )
    rebuild_article_paragraphs(conn, article_id, content)
    conn.commit()
    conn.close()
    job_id = None
    with get_db() as check_conn:
        article = check_conn.execute("SELECT id,title,summary,domains,content FROM articles WHERE id=?", (article_id,)).fetchone()
        has_knowledge = bool(affected_claims) or bool(check_conn.execute(
            """SELECT 1 FROM knowledge_claim_evidence WHERE article_id=? LIMIT 1""", (article_id,)
        ).fetchone())
        should_extract = bool(article and (has_knowledge or is_knowledge_article(article)))
    if should_extract:
        job_id, _ = _enqueue_knowledge_job(article_id, "content_update", force=True)
    return {"success": True, "content": content, "knowledge_claims_invalidated": affected_claims, "knowledge_job_id": job_id}


def _article_editor_margins(conn, article_id: int) -> dict:
    defaults = {"top": 2.54, "bottom": 2.54, "left": 2.6, "right": 2.6}
    row = conn.execute("SELECT value_json FROM app_preferences WHERE preference_key=?",
                       (f"article_editor_margins:{article_id}",)).fetchone()
    if not row:
        return defaults
    try:
        stored = json.loads(row["value_json"])
        return {side: max(0.5, min(8.0, float(stored.get(side, value))))
                for side, value in defaults.items()}
    except (TypeError, ValueError, AttributeError):
        return defaults


@app.get("/api/articles/{article_id}/editor-layout")
def get_article_editor_layout(article_id: int):
    conn = get_db()
    try:
        if not conn.execute("SELECT 1 FROM articles WHERE id=?", (article_id,)).fetchone():
            raise HTTPException(status_code=404, detail="文章不存在")
        return {"margins": _article_editor_margins(conn, article_id)}
    finally:
        conn.close()


@app.put("/api/articles/{article_id}/editor")
async def save_article_editor(article_id: int, request: Request):
    """Atomically save title, body, and per-article layout with conflict detection."""
    import math
    body = await request.json()
    title = str(body.get("title") or "").strip()[:200]
    content = body.get("content")
    if not title or not isinstance(content, str) or not content.strip():
        raise HTTPException(status_code=400, detail="标题和正文不能为空")
    content = strip_stale_toc_placeholders(content)
    requested = body.get("margins")
    if not isinstance(requested, dict):
        raise HTTPException(status_code=400, detail="页边距格式无效")
    try:
        margins = {side: float(requested[side]) for side in ("top", "bottom", "left", "right")}
    except (KeyError, TypeError, ValueError):
        raise HTTPException(status_code=400, detail="页边距格式无效")
    if any(not math.isfinite(value) or not 0.5 <= value <= 8 for value in margins.values()):
        raise HTTPException(status_code=400, detail="页边距必须在 0.5 至 8 厘米之间")
    conn = get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        current = conn.execute("SELECT title,content,summary,domains FROM articles WHERE id=?", (article_id,)).fetchone()
        if not current:
            raise HTTPException(status_code=404, detail="文章不存在")
        expected = body.get("base_content")
        expected_title = body.get("base_title")
        if (not isinstance(expected, str) or expected != (current["content"] or "")
                or not isinstance(expected_title, str) or expected_title != (current["title"] or "")):
            raise HTTPException(status_code=409, detail="文章已在其他位置修改，请重新载入后核对草稿")
        changed = content != (current["content"] or "")
        affected_claims = mark_article_claims_needs_review(conn, article_id, "原文章正文已修改，需重新核验") if changed else []
        conn.execute("UPDATE articles SET title=?,content=? WHERE id=?", (title, content, article_id))
        if changed:
            rebuild_article_paragraphs(conn, article_id, content)
        conn.execute("""INSERT INTO app_preferences(preference_key,value_json,updated_at) VALUES(?,?,?)
                        ON CONFLICT(preference_key) DO UPDATE SET value_json=excluded.value_json,updated_at=excluded.updated_at""",
                     (f"article_editor_margins:{article_id}", json.dumps(margins), datetime.datetime.now().isoformat()))
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    job_id = None
    if changed:
        with get_db() as check_conn:
            article = check_conn.execute("SELECT id,title,summary,domains,content FROM articles WHERE id=?", (article_id,)).fetchone()
            has_knowledge = bool(affected_claims) or bool(check_conn.execute(
                "SELECT 1 FROM knowledge_claim_evidence WHERE article_id=? LIMIT 1", (article_id,)
            ).fetchone())
            should_extract = bool(article and (has_knowledge or is_knowledge_article(article)))
        if should_extract:
            job_id, _ = _enqueue_knowledge_job(article_id, "content_update", force=True)
    return {"success": True, "content": content, "title": title, "margins": margins,
            "knowledge_claims_invalidated": affected_claims, "knowledge_job_id": job_id}


@app.post("/api/articles/{article_id}/images")
async def upload_article_body_image(article_id: int, file: UploadFile = File(...)):
    """保存从正文编辑器剪贴板粘贴的图片。"""
    with get_db() as conn:
        if not conn.execute("SELECT 1 FROM articles WHERE id=?", (article_id,)).fetchone():
            raise HTTPException(status_code=404, detail="文章不存在")

    max_bytes = 12 * 1024 * 1024
    raw = await file.read(max_bytes + 1)
    if not raw:
        raise HTTPException(status_code=400, detail="图片内容为空")
    if len(raw) > max_bytes:
        raise HTTPException(status_code=413, detail="单张图片不能超过 12 MB")

    try:
        from PIL import Image, UnidentifiedImageError
        with Image.open(BytesIO(raw)) as image:
            image_format = str(image.format or "").upper()
            width, height = image.size
            image.verify()
    except (UnidentifiedImageError, OSError, ValueError, Image.DecompressionBombError):
        raise HTTPException(status_code=400, detail="剪贴板内容不是有效图片")

    extensions = {"PNG": "png", "JPEG": "jpg", "WEBP": "webp", "GIF": "gif"}
    media_types = {"PNG": "image/png", "JPEG": "image/jpeg", "WEBP": "image/webp", "GIF": "image/gif"}
    extension = extensions.get(image_format)
    if not extension:
        raise HTTPException(status_code=400, detail="仅支持 PNG、JPG、WebP 或 GIF 图片")
    if width <= 0 or height <= 0 or width * height > 40_000_000:
        raise HTTPException(status_code=400, detail="图片尺寸无效或过大")

    filename = f"article-{article_id}-{uuid.uuid4().hex}.{extension}"
    target = ARTICLE_IMAGE_DIR / filename
    async with aiofiles.open(str(target), "wb") as output:
        await output.write(raw)
    return {
        "success": True,
        "url": f"/api/article-images/{filename}",
        "filename": filename,
        "content_type": media_types[image_format],
        "width": width,
        "height": height,
    }


@app.get("/api/article-images/{filename}")
def get_article_body_image(filename: str):
    """读取正文图片；文件名严格限制为本应用生成的格式。"""
    if not re.fullmatch(r"article-\d+-[0-9a-f]{32}\.(?:png|jpg|webp|gif)", filename):
        raise HTTPException(status_code=404, detail="图片不存在")
    target = ARTICLE_IMAGE_DIR / filename
    if not target.is_file():
        raise HTTPException(status_code=404, detail="图片不存在")
    media_type = {
        ".png": "image/png", ".jpg": "image/jpeg",
        ".webp": "image/webp", ".gif": "image/gif",
    }[target.suffix.lower()]
    return FileResponse(target, media_type=media_type, headers={"Cache-Control": "public, max-age=31536000, immutable"})


@app.get("/api/article-pdf/{token}/{filename}")
def get_article_pdf_page(token: str, filename: str):
    """读取「PDF 不解析为文本」模式的页面图片与可选中文字层 JSON。"""
    if not re.fullmatch(r"[0-9a-f]{32}", token):
        raise HTTPException(status_code=404, detail="文件不存在")
    image_match = re.fullmatch(r"page-\d{3,4}\.(png|jpe?g)", filename)
    if image_match:
        target = ARTICLE_IMAGE_DIR / f"pdf-{token}" / filename
        if not target.is_file():
            raise HTTPException(status_code=404, detail="页面不存在")
        media_type = "image/png" if image_match.group(1) == "png" else "image/jpeg"
        return FileResponse(
            target, media_type=media_type,
            headers={"Cache-Control": "public, max-age=31536000, immutable"},
        )
    if re.fullmatch(r"page-\d{3,4}\.words\.json", filename):
        target = ARTICLE_IMAGE_DIR / f"pdf-{token}" / filename
        if not target.is_file():
            raise HTTPException(status_code=404, detail="文字层不存在")
        return FileResponse(
            target, media_type="application/json",
            headers={"Cache-Control": "public, max-age=86400"},
        )
    raise HTTPException(status_code=404, detail="文件不存在")


@app.put("/api/articles/{article_id}/pinned")
def toggle_article_pinned(
    article_id: int,
    pinned: int = Form(...),
    tag_group_id: Optional[int] = None,
    pin_scope: Optional[str] = None,
):
    """
    切换文章置顶状态。

    - 若提供了 pin_scope：在 article_list_pins 表中设置该文章在当前列表下的置顶状态；
      此时全局 pinned 字段不变。
    - 若仅提供了 tag_group_id：兼容旧调用，转换为 tag_group:{id} 作用域。
    - 若未提供作用域：默认写入“全部知识”列表作用域，不再写全局 pinned 字段。
    """
    conn = get_db()
    if not pin_scope and tag_group_id is not None:
        pin_scope = f"tag_group:{tag_group_id}"

    if pin_scope:
        pin_scope = pin_scope.strip()[:200]
        conn.execute(
            "INSERT OR REPLACE INTO article_list_pins (article_id, list_key, pinned) VALUES (?, ?, ?)",
            (article_id, pin_scope, 1 if pinned else 0)
        )
        conn.commit()
    else:
        # 旧客户端兜底：不再写全局置顶，默认写入“全部知识”列表作用域。
        conn.execute(
            "INSERT OR REPLACE INTO article_list_pins (article_id, list_key, pinned) VALUES (?, 'view:all', ?)",
            (article_id, 1 if pinned else 0)
        )
        conn.commit()
    conn.close()
    return {"success": True, "pinned": bool(pinned)}


@app.put("/api/articles/{article_id}/tags")
async def update_article_tags(
    article_id: int,
    tags: str = Form(...),
    domains: str = Form(None),
    new_tags: str = Form(None),   # 前端传来的"本次新增"标签列表，用于同步到自定义库
):
    """更新文章标签和领域"""
    conn = get_db()

    # 验证文章是否存在
    row = conn.execute("SELECT id, title, content FROM articles WHERE id=?", (article_id,)).fetchone()
    if not row:
        conn.close()
        raise HTTPException(status_code=404, detail="文章不存在")

    try:
        # 解析标签JSON
        tags_list = json.loads(tags)

        # 保留作者标签（如果已存在）
        existing_row = conn.execute("SELECT tags FROM articles WHERE id=?", (article_id,)).fetchone()
        existing_tags = json.loads(existing_row["tags"] or "[]")
        author_tags = [t for t in existing_tags if t.startswith('作者:')]

        # 合并标签（作者标签 + 新的自定义标签）
        final_tags = author_tags + [t for t in tags_list if not t.startswith('作者:')]

        # 解析领域 JSON，并将人工选择与自动分类结果分开持久化。
        # 服务器重启后可以重新运行分类器，但不会再覆盖人工添加/移除的领域。
        requested_domains = json.loads(domains) if domains else []
        domains_list, manual_domains, excluded_domains = _domain_assignment_state(
            (row["title"] or "") + " " + (row["content"] or ""),
            selected_domains=requested_domains,
        )
        classification = conn.execute(
            "SELECT auto_domains_json,content_hash FROM domain_classification_jobs WHERE article_id=?",
            (article_id,),
        ).fetchone()
        if classification and classification["content_hash"]:
            auto_roots = domain_taxonomy_module._items(classification["auto_domains_json"])
            domains_list = list(dict.fromkeys(requested_domains))
            manual_domains = [name for name in domains_list if name not in auto_roots]
            excluded_domains = [name for name in auto_roots if name not in domains_list]

        # 更新文章标签
        conn.execute(
            """UPDATE articles
               SET tags=?, domains=?, manual_domains=?, excluded_auto_domains=?
               WHERE id=?""",
            (
                json.dumps(final_tags, ensure_ascii=False),
                json.dumps(domains_list, ensure_ascii=False),
                json.dumps(manual_domains, ensure_ascii=False),
                json.dumps(excluded_domains, ensure_ascii=False),
                article_id,
            )
        )
        for child in conn.execute("""SELECT child.id,root.name AS parent_name FROM domain_taxonomy child
                                     JOIN domain_taxonomy root ON root.id=child.parent_id"""):
            if child["parent_name"] not in domains_list:
                conn.execute("UPDATE article_subcategory_choices SET mode='excluded' WHERE article_id=? AND subcategory_id=?",
                             (article_id, child["id"]))

        # ── 将用户本次新输入的标签同步到自定义库（tag_groups 表）──
        # new_tags 仅包含用户在编辑标签弹窗中手动输入的新标签，不含系统自动标签
        if new_tags:
            new_tags_list = [t for t in json.loads(new_tags) if t and not t.startswith('作者:')]
            if new_tags_list:
                # 获取第一个二级目录（sort_order 最小）
                default_cat = conn.execute(
                    "SELECT id FROM tag_categories ORDER BY sort_order ASC, id ASC LIMIT 1"
                ).fetchone()
                if default_cat:
                    default_cat_id = default_cat["id"]
                    now_ts = datetime.datetime.now().isoformat()
                    purged_tag_names = _get_purged_tag_names(conn)
                    for tag_name in new_tags_list:
                        # 该标签名在 tag_groups 任意目录下均不存在时才插入
                        exists = conn.execute(
                            "SELECT id FROM tag_groups WHERE name = ?", (tag_name,)
                        ).fetchone()
                        if not exists:
                            purged_tag_names.discard(tag_name)
                            max_order = conn.execute(
                                "SELECT MAX(sort_order) FROM tag_groups WHERE category_id = ?",
                                (default_cat_id,)
                            ).fetchone()[0]
                            conn.execute(
                                "INSERT INTO tag_groups (name, category_id, sort_order, created_at) VALUES (?, ?, ?, ?)",
                                (tag_name, default_cat_id, (max_order or 0) + 1, now_ts)
                            )
                    _set_purged_tag_names(conn, purged_tag_names)

        conn.commit()
        conn.close()

        return {"success": True, "tags": final_tags, "domains": domains_list}
    except json.JSONDecodeError:
        conn.close()
        raise HTTPException(status_code=400, detail="标签或领域格式错误")
    except Exception as e:
        conn.close()
        raise HTTPException(status_code=500, detail=f"更新标签失败: {str(e)}")


class BulkArticleTagsUpdate(BaseModel):
    article_ids: List[int]
    tags: List[str]


@app.post("/api/articles/bulk/tags")
def bulk_add_article_tags(body: BulkArticleTagsUpdate):
    """为多篇文章追加自定义标签，保留各文章已有标签。"""
    article_ids = list(dict.fromkeys(article_id for article_id in body.article_ids if article_id > 0))
    tags = list(dict.fromkeys(tag.strip() for tag in body.tags if tag.strip()))

    if not article_ids:
        raise HTTPException(status_code=400, detail="请至少选择一篇文章")
    if not tags:
        raise HTTPException(status_code=400, detail="请至少添加一个标签")
    if any(tag.startswith("作者:") for tag in tags):
        raise HTTPException(status_code=400, detail="作者标签由系统自动生成，不能手动添加")
    if len(tags) > 50 or any(len(tag) > 100 for tag in tags):
        raise HTTPException(status_code=400, detail="单次最多添加50个标签，且每个标签不超过100个字符")

    conn = get_db()
    try:
        updated = 0
        unchanged = 0
        missing_ids = []
        for article_id in article_ids:
            article = conn.execute("SELECT tags FROM articles WHERE id = ?", (article_id,)).fetchone()
            if not article:
                missing_ids.append(article_id)
                continue
            existing_tags = json.loads(article["tags"] or "[]")
            final_tags = existing_tags + [tag for tag in tags if tag not in existing_tags]
            if final_tags == existing_tags:
                unchanged += 1
                continue
            conn.execute(
                "UPDATE articles SET tags = ? WHERE id = ?",
                (json.dumps(final_tags, ensure_ascii=False), article_id),
            )
            updated += 1

        # 新输入的标签同时登记到自定义标签库，方便后续筛选和复用。
        default_cat = conn.execute(
            "SELECT id FROM tag_categories ORDER BY sort_order ASC, id ASC LIMIT 1"
        ).fetchone()
        if default_cat:
            default_cat_id = default_cat["id"]
            max_order = conn.execute(
                "SELECT MAX(sort_order) FROM tag_groups WHERE category_id = ?", (default_cat_id,)
            ).fetchone()[0] or 0
            now_ts = datetime.datetime.now().isoformat()
            next_order = max_order + 1
            purged_tag_names = _get_purged_tag_names(conn)
            for tag in tags:
                exists = conn.execute("SELECT id FROM tag_groups WHERE name = ?", (tag,)).fetchone()
                if not exists:
                    purged_tag_names.discard(tag)
                    conn.execute(
                        "INSERT INTO tag_groups (name, category_id, sort_order, created_at) VALUES (?, ?, ?, ?)",
                        (tag, default_cat_id, next_order, now_ts),
                    )
                    next_order += 1
            _set_purged_tag_names(conn, purged_tag_names)

        conn.commit()
        return {
            "success": True,
            "updated_articles": updated,
            "unchanged_articles": unchanged,
            "missing_article_ids": missing_ids,
            "tags": tags,
        }
    except (json.JSONDecodeError, TypeError):
        conn.rollback()
        raise HTTPException(status_code=500, detail="部分文章的标签数据格式错误")
    except HTTPException:
        conn.rollback()
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=f"批量添加标签失败: {str(e)}")
    finally:
        conn.close()


def get_articles_list_internal(params: dict):
    """获取文章列表的内部函数，支持多种筛选条件"""
    conn = get_db()
    page = params.get("page", 1)
    page_size = params.get("page_size", 20)
    fuzzy = params.get("fuzzy", True)
    q = params.get("q", "")
    source_type = params.get("source_type")
    domain = params.get("domain")
    author = params.get("author")

    # 构建查询条件
    where_clauses = []
    where_params = []

    if q:
        if fuzzy:
            # 简单的模糊搜索（LIKE）
            where_clauses.append("(title LIKE ? OR summary LIKE ? OR content LIKE ?)")
            search_pattern = f"%{q}%"
            where_params.extend([search_pattern, search_pattern, search_pattern])
        else:
            # 精确搜索
            where_clauses.append("(title LIKE ? OR summary LIKE ? OR content LIKE ?)")
            search_pattern = f"%{q}%"
            where_params.extend([search_pattern, search_pattern, search_pattern])

    if source_type:
        where_clauses.append("source_type = ?")
        where_params.append(source_type)

    if domain:
        # domains字段是JSON数组
        where_clauses.append("domains LIKE ?")
        where_params.append(f'%"{domain}"%')

    if author:
        # author字段也是JSON数组（在tags中）
        where_clauses.append("tags LIKE ?")
        where_params.append(f'%作者:{author}%')

    where_sql = " AND ".join(where_clauses) if where_clauses else "1=1"

    # 计算总数
    count_sql = f"SELECT COUNT(*) FROM articles WHERE {where_sql}"
    total = conn.execute(count_sql, where_params).fetchone()[0]

    # 分页查询
    offset = (page - 1) * page_size
    order_by = params.get("order_by", "created_at DESC")
    query_sql = f"SELECT * FROM articles WHERE {where_sql} ORDER BY {order_by} LIMIT ? OFFSET ?"
    where_params.extend([page_size, offset])

    rows = conn.execute(query_sql, where_params).fetchall()
    conn.close()

    articles = []
    for row in rows:
        a = dict(row)
        a["domains"] = json.loads(a["domains"] or "[]")
        a["tags"] = json.loads(a["tags"] or "[]")
        a.pop("starred", None)
        a["pinned"] = bool(a.get("pinned", 0))
        articles.append(a)

    return {
        "articles": articles,
        "total": total,
        "page": page,
        "page_size": page_size,
    }


