def _article_classification_text(article: sqlite3.Row) -> str:
    return " ".join((article["title"] or "", article["summary"] or "", _plain_article_text(article["content"] or "")[:9000]))


def _rule_domain_proposal(conn: sqlite3.Connection, article: sqlite3.Row) -> dict:
    text = _article_classification_text(article)
    roots = [name for name in classify_domains(text) if name != "综合法律"]
    catalog = domain_taxonomy_module.taxonomy(conn)
    for root in catalog:
        if root["name"] in roots:
            continue
        keywords = domain_taxonomy_module._items(root["keywords_json"])
        if keywords and domain_taxonomy_module._keywords_match(text, keywords, root["name"]):
            roots.append(root["name"])
    title = article["title"] or ""
    summary = article["summary"] or _plain_article_text(article["content"] or "")[:1000]
    # Historical user-created domains are absent from the predefined root rules.
    # Infer these only when their stable child vocabulary matches the subject.
    for root in catalog:
        if root["name"] not in LEGAL_DOMAINS_V2 and root["name"] not in roots:
            if domain_taxonomy_module.rule_child_candidates(conn, title, summary, [root["name"]]):
                roots.append(root["name"])
    children = domain_taxonomy_module.classified_children(conn, article["id"], title, summary, roots)
    suggestions = domain_taxonomy_module.rule_child_candidates(conn, title, summary, roots)
    covered = {candidate["parent_id"] for candidate in suggestions}
    covered.update(root["id"] for root in catalog if any(child["id"] in children for child in root["children"]))
    unresolved = [root["name"] for root in catalog if root["name"] in roots and root["id"] not in covered]
    return {"domains": roots, "subcategories": children, "suggestions": suggestions,
            "needs_ai": not roots or bool(unresolved)}


async def _classify_queued_article(article_id: int) -> None:
    conn = get_db()
    try:
        article = conn.execute("SELECT id,title,summary,content FROM articles WHERE id=?", (article_id,)).fetchone()
        if article is None:
            conn.execute("DELETE FROM domain_classification_jobs WHERE article_id=?", (article_id,))
            conn.commit()
            return
        fingerprint = hashlib.sha256(((article["title"] or "") + (article["content"] or "")).encode()).hexdigest()
        proposal = _rule_domain_proposal(conn, article)
        catalog = domain_taxonomy_module.taxonomy(conn)
        ai_failed = False
        for candidate in proposal["suggestions"]:
            domain_taxonomy_module.suggest(conn, candidate["name"], candidate["parent_id"], article_id,
                                           candidate["keywords"])
        if proposal["needs_ai"] and _plain_article_text(article["content"] or "").strip():
            options = [{"id": root["id"], "name": root["name"], "children": [{"id": c["id"], "name": c["name"]} for c in root["children"]]} for root in catalog]
            prompt = (
                "根据文章内容进行法律专业领域分类。只能选择目录中的已有类别；如确无合适类别，"
                "仅当现有目录无法容纳，且主题能覆盖多篇不同文章时，才在 suggestions 中提出最多2个新领域或子分类。"
                "子分类须是稳定、宽泛的法律主题，名称不超过12字；一级领域不超过8字。"
                "单篇案例争点、裁判结论、法条名、文章标题及其缩写均不得作为分类建议。"
                "逐一检查每个已识别领域的二级主题，不能因一个领域已有匹配就跳过其余领域。"
                "不得根据网址、作者、来源网站分类。只返回 JSON 对象："
                '{"domains":["现有一级名称"],"subcategories":[现有子类ID],'
                '"suggestions":[{"name":"可复用主题名称","parent_id":现有一级ID或null,"keywords":["识别词"]}]}。'
                f"\n已识别领域：{json.dumps(proposal['domains'], ensure_ascii=False)}"
                f"\n目录：{json.dumps(options, ensure_ascii=False)}"
                f"\n标题：{article['title']}\n摘要：{article['summary']}"
                f"\n正文节选：{_plain_article_text(article['content'] or '')[:5500]}"
            )
            try:
                data, _model = await _call_ai_with_fallback(
                    ai_config_module.effective_purpose_model("summary"),
                    [{"role": "system", "content": "你是法律知识库分类助手。仅根据文章主题判断。"}, {"role": "user", "content": prompt}],
                    temperature=0, max_tokens=450,
                )
                answer, _, finish = _extract_ai_choice(data)
                if finish in {"length", "max_tokens"}:
                    raise ValueError("分类结果不完整")
                parsed = parse_model_json(answer)
                valid_roots = {root["name"] for root in catalog}
                valid_children = {child["id"]: root["name"] for root in catalog for child in root["children"]}
                ai_roots = [name for name in parsed.get("domains", []) if isinstance(name, str) and name in valid_roots]
                ai_children = [cid for cid in parsed.get("subcategories", []) if isinstance(cid, int) and cid in valid_children]
                if ai_roots or ai_children:
                    proposal["domains"] = list(dict.fromkeys([*proposal["domains"], *ai_roots, *(valid_children[cid] for cid in ai_children)]))
                proposal["subcategories"] = list(dict.fromkeys([*proposal["subcategories"], *ai_children]))
                candidates = parsed.get("suggestions")
                if not isinstance(candidates, list):
                    candidates = [parsed.get("suggestion")] if isinstance(parsed.get("suggestion"), dict) else []
                for candidate in candidates[:2]:
                    if not isinstance(candidate, dict):
                        continue
                    parent = candidate.get("parent_id")
                    valid_parent = {root["id"] for root in catalog}
                    if parent is None or parent in valid_parent:
                        domain_taxonomy_module.suggest(
                            conn, candidate.get("name", ""), parent, article_id,
                            [str(word) for word in candidate.get("keywords", []) if isinstance(word, str)][:8],
                        )
            except Exception as exc:
                ai_failed = True
                print(f"[domain-classification] AI unavailable for article {article_id}: {exc}")
        status = "needs_review" if not proposal["domains"] or ai_failed and proposal["needs_ai"] else "done"
        changed = domain_taxonomy_module.apply_classification(
            conn, article_id, proposal["domains"], proposal["subcategories"],
            status=status, expected_hash=fingerprint,
        )
        if changed:
            conn.commit()
        else:
            conn.rollback()
    finally:
        conn.close()


_domain_classification_task = None


async def _domain_classification_loop():
    while True:
        try:
            conn = get_db()
            try:
                rows = conn.execute("SELECT article_id FROM domain_classification_jobs WHERE status='queued' ORDER BY updated_at LIMIT 10").fetchall()
            finally:
                conn.close()
            for row in rows:
                await _classify_queued_article(row[0])
        except Exception as exc:
            print(f"[domain-classification] worker error: {exc}")
        await asyncio.sleep(3)


@app.on_event("startup")
async def start_domain_classification_worker():
    global _domain_classification_task
    if _domain_classification_task is None or _domain_classification_task.done():
        _domain_classification_task = asyncio.create_task(_domain_classification_loop())


@app.on_event("shutdown")
async def stop_domain_classification_worker():
    global _domain_classification_task
    if _domain_classification_task:
        _domain_classification_task.cancel()
        _domain_classification_task = None


@app.post("/api/domains/categories")
def create_domain_category(payload: dict = Body(...)):
    name = str(payload.get("name") or "").strip()
    parent_id = payload.get("parent_id")
    keywords = payload.get("keywords") or []
    if not 2 <= len(name) <= 40 or domain_taxonomy_module.is_source_label(name):
        raise HTTPException(status_code=400, detail="请输入有效的主题分类名称")
    if not isinstance(keywords, list) or any(not isinstance(word, str) for word in keywords) or len(keywords) > 8:
        raise HTTPException(status_code=400, detail="识别词最多8个")
    conn = get_db()
    try:
        if parent_id is not None:
            parent = conn.execute("SELECT id,parent_id FROM domain_taxonomy WHERE id=?", (parent_id,)).fetchone()
            if not parent or parent["parent_id"] is not None:
                raise HTTPException(status_code=400, detail="二级分类只能建在专业领域下")
        siblings = conn.execute("SELECT name FROM domain_taxonomy WHERE parent_id IS ?", (parent_id,)).fetchall()
        normalize = lambda value: re.sub(r"(法|法律|纠纷|争议)$", "", value.strip())
        if any(normalize(row[0]) == normalize(name) for row in siblings):
            raise HTTPException(status_code=409, detail="已有相同或近义分类")
        cur = conn.execute(
            "INSERT INTO domain_taxonomy(name,parent_id,keywords_json,created_at) VALUES (?,?,?,?)",
            (name, parent_id, json.dumps([word.strip()[:30] for word in keywords if word.strip()], ensure_ascii=False), datetime.datetime.now().isoformat()),
        )
        if parent_id is not None:
            conn.execute("DELETE FROM domain_taxonomy_suppressed_children WHERE parent_id=? AND name=?", (parent_id, name))
        parent_name = conn.execute("SELECT name FROM domain_taxonomy WHERE id=?", (parent_id,)).fetchone()[0] if parent_id else None
        for article in conn.execute("SELECT id,domains FROM articles").fetchall():
            if parent_name is None or parent_name in domain_taxonomy_module._items(article["domains"]):
                conn.execute("""INSERT INTO domain_classification_jobs(article_id,status,updated_at)
                                VALUES (?,'queued',?) ON CONFLICT(article_id) DO UPDATE SET status='queued',updated_at=excluded.updated_at""",
                             (article["id"], datetime.datetime.now().isoformat()))
        conn.commit()
        return {"id": cur.lastrowid, "name": name, "parent_id": parent_id}
    finally:
        conn.close()


@app.delete("/api/domains/categories/{category_id}")
def delete_domain_subcategory(category_id: int):
    conn = get_db()
    try:
        child = conn.execute(
            "SELECT id,name,parent_id FROM domain_taxonomy WHERE id=?", (category_id,)
        ).fetchone()
        if child is None:
            raise HTTPException(status_code=404, detail="子分类不存在")
        if child["parent_id"] is None:
            raise HTTPException(status_code=400, detail="此处只能删除二级子分类")
        affected = conn.execute(
            "SELECT COUNT(*) FROM article_subcategory_choices WHERE subcategory_id=? AND mode<>'excluded'",
            (category_id,),
        ).fetchone()[0]
        conn.execute(
            "INSERT OR IGNORE INTO domain_taxonomy_suppressed_children(parent_id,name) VALUES (?,?)",
            (child["parent_id"], child["name"]),
        )
        conn.execute(
            "UPDATE domain_suggestions SET status='dismissed' WHERE parent_id=? AND name=? AND status='pending'",
            (child["parent_id"], child["name"]),
        )
        conn.execute("DELETE FROM domain_taxonomy WHERE id=?", (category_id,))
        conn.commit()
        return {"ok": True, "affected_articles": affected}
    finally:
        conn.close()


@app.put("/api/domains/categories/{category_id}/rename")
def rename_domain_subcategory(category_id: int, payload: dict = Body(...)):
    name = str(payload.get("name") or "").strip()
    if not 2 <= len(name) <= 40 or domain_taxonomy_module.is_source_label(name):
        raise HTTPException(status_code=400, detail="请输入有效的主题分类名称")
    conn = get_db()
    try:
        child = conn.execute("SELECT name,parent_id FROM domain_taxonomy WHERE id=?", (category_id,)).fetchone()
        if not child:
            raise HTTPException(status_code=404, detail="子分类不存在")
        if child["parent_id"] is None:
            raise HTTPException(status_code=400, detail="此处只能重命名二级子分类")
        normalize = lambda value: re.sub(r"(法|法律|纠纷|争议)$", "", value.strip())
        siblings = conn.execute("SELECT name FROM domain_taxonomy WHERE parent_id=? AND id<>?", (child["parent_id"], category_id))
        if any(normalize(row[0]) == normalize(name) for row in siblings):
            raise HTTPException(status_code=409, detail="已有相同或近义分类")
        if name != child["name"]:
            conn.execute("INSERT OR IGNORE INTO domain_taxonomy_suppressed_children(parent_id,name) VALUES (?,?)", (child["parent_id"], child["name"]))
            conn.execute("DELETE FROM domain_taxonomy_suppressed_children WHERE parent_id=? AND name=?", (child["parent_id"], name))
            conn.execute("UPDATE domain_suggestions SET status='dismissed' WHERE parent_id=? AND name=? AND status='pending'", (child["parent_id"], child["name"]))
            conn.execute("UPDATE domain_taxonomy SET name=? WHERE id=?", (name, category_id))
        conn.commit()
        return {"id": category_id, "name": name}
    finally:
        conn.close()


@app.post("/api/domains/categories/reorder")
def reorder_domain_subcategories(payload: dict = Body(...)):
    parent_id = payload.get("parent_id")
    ids = payload.get("ids")
    if not isinstance(parent_id, int) or not isinstance(ids, list) or any(not isinstance(value, int) for value in ids):
        raise HTTPException(status_code=400, detail="子分类顺序格式不正确")
    conn = get_db()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = [row[0] for row in conn.execute(
            "SELECT id FROM domain_taxonomy WHERE parent_id=? ORDER BY sort_order,id", (parent_id,)
        )]
        if not existing or len(ids) != len(existing) or set(ids) != set(existing):
            raise HTTPException(status_code=409, detail="子分类已发生变化，请刷新后重试")
        for index, child_id in enumerate(ids):
            conn.execute("UPDATE domain_taxonomy SET sort_order=? WHERE id=?", (index, child_id))
        conn.commit()
        return {"ids": ids}
    finally:
        conn.close()


@app.get("/api/domains/suggestions")
def list_domain_suggestions():
    conn = get_db()
    try:
        rows = conn.execute("""SELECT s.id,s.name,s.parent_id,s.keywords_json,s.article_id,s.created_at,
                                   p.name AS parent_name,a.title AS article_title,
                                   (SELECT COUNT(*) FROM domain_suggestion_articles e WHERE e.suggestion_id=s.id) AS support_count
                            FROM domain_suggestions s
                            LEFT JOIN domain_taxonomy p ON p.id=s.parent_id
                            LEFT JOIN articles a ON a.id=s.article_id
                            WHERE s.status='pending'
                              AND length(s.name)<=CASE WHEN s.parent_id IS NULL THEN 8 ELSE 12 END
                              AND (SELECT COUNT(*) FROM domain_suggestion_articles e WHERE e.suggestion_id=s.id)>=2
                            ORDER BY support_count DESC,s.id DESC LIMIT 100""").fetchall()
        return [dict(row) for row in rows]
    finally:
        conn.close()


@app.get("/api/domains/suggestions/page")
def page_domain_suggestions(q: str = "", filter: str = "all", offset: int = Query(0, ge=0),
                            limit: int = Query(20, ge=1, le=50)):
    """Bounded review list for large historical classification batches."""
    if filter not in {"all", "supported", "roots"}:
        raise HTTPException(status_code=400, detail="建议筛选条件无效")
    conn = get_db()
    try:
        conditions = ["s.status='pending'",
                      "length(s.name)<=CASE WHEN s.parent_id IS NULL THEN 8 ELSE 12 END",
                      "(SELECT COUNT(*) FROM domain_suggestion_articles e WHERE e.suggestion_id=s.id)>=2"]
        params: list = []
        keyword = "".join(q.split())[:80]
        if keyword:
            conditions.append("(REPLACE(s.name,' ','') LIKE ? ESCAPE '\\' OR REPLACE(p.name,' ','') LIKE ? ESCAPE '\\')")
            escaped = keyword.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
            params.extend([f"%{escaped}%", f"%{escaped}%"])
        if filter == "roots":
            conditions.append("s.parent_id IS NULL")
        base = " FROM domain_suggestions s LEFT JOIN domain_taxonomy p ON p.id=s.parent_id WHERE " + " AND ".join(conditions)
        total = conn.execute("SELECT COUNT(*)" + base, params).fetchone()[0]
        rows = conn.execute("""SELECT s.id,s.name,s.parent_id,s.article_id,s.created_at,
                                p.name AS parent_name,a.title AS article_title,
                                (SELECT COUNT(*) FROM domain_suggestion_articles e WHERE e.suggestion_id=s.id) AS support_count"""
                            + base.replace(" WHERE ", " LEFT JOIN articles a ON a.id=s.article_id WHERE ", 1)
                            + " ORDER BY support_count DESC,s.id DESC LIMIT ? OFFSET ?", [*params, limit, offset]).fetchall()
        return {"total": total, "items": [dict(row) for row in rows], "has_more": offset + len(rows) < total}
    finally:
        conn.close()


