@app.get("/api/kb-stats")
def get_kb_stats():
    """知识库可视化统计 - 多维度数据"""
    import json
    from collections import Counter
    from urllib.parse import urlparse
    
    conn = get_db()
    
    # 1. 基础统计
    total = conn.execute("SELECT COUNT(*) FROM articles").fetchone()[0]
    url_count = conn.execute("SELECT COUNT(*) FROM articles WHERE source_type='url'").fetchone()[0]
    file_count = conn.execute("SELECT COUNT(*) FROM articles WHERE source_type='file'").fetchone()[0]
    
    # 2. 来源类型分布
    source_dist = conn.execute("""
        SELECT source_type, COUNT(*) as count 
        FROM articles GROUP BY source_type
    """).fetchall()
    
    # 3. 最近7天/30天/总文章数趋势（按月份）
    monthly_stats = conn.execute("""
        SELECT 
            strftime('%Y-%m', created_at) as month,
            COUNT(*) as count
        FROM articles 
        GROUP BY month
        ORDER BY month DESC
        LIMIT 24
    """).fetchall()
    
    # 4. 专业领域分布（解析 domains JSON）
    all_articles = conn.execute("SELECT domains FROM articles WHERE domains IS NOT NULL").fetchall()
    domain_counter = Counter()
    for row in all_articles:
        try:
            domains = json.loads(row[0]) if row[0] else []
            for d in domains:
                if d and d.strip():
                    domain_counter[d.strip()] += 1
        except:
            pass
    
    # 5. 笔记数量统计
    note_stats = conn.execute("""
        SELECT COUNT(*) as total_notes,
               COUNT(DISTINCT article_id) as articles_with_notes
        FROM notes
    """).fetchone()
    
    # 7. 平均文章长度
    avg_content_len = conn.execute("""
        SELECT AVG(LENGTH(content)) FROM articles WHERE content IS NOT NULL
    """).fetchone()[0] or 0
    
    # 8. 来源域名分布（提取URL域名）
    url_articles = conn.execute("""
        SELECT source_url FROM articles WHERE source_type='url' AND source_url IS NOT NULL
    """).fetchall()
    domain_counter2 = Counter()
    for row in url_articles:
        url = row[0] or ''
        parsed = urlparse(url)
        domain = parsed.netloc or (url.split('://')[1].split('/')[0] if '://' in url else '')
        if domain:
            domain_counter2[domain] += 1
    
    # 9. 每日新增趋势（最近90天，前端可切换 7/30/90）
    daily_stats = conn.execute("""
        SELECT 
            date(created_at) as day,
            COUNT(*) as count
        FROM articles 
        WHERE created_at >= date('now', '-90 days')
        GROUP BY day
        ORDER BY day ASC
    """).fetchall()
    
    # 10. 作者分布 Top15
    author_rows = conn.execute("""
        SELECT j.value as author, COUNT(*) as cnt
        FROM articles a
        JOIN json_each(a.tags) j
        WHERE a.tags IS NOT NULL AND j.value LIKE '作者:%'
        GROUP BY j.value
        ORDER BY cnt DESC
        LIMIT 15
    """).fetchall()
    
    # 11. 文章长度分段
    len_rows = conn.execute("""
        SELECT 
            CASE
                WHEN LENGTH(content) < 500 THEN '1.<500字'
                WHEN LENGTH(content) < 2000 THEN '2.500-2K'
                WHEN LENGTH(content) < 5000 THEN '3.2K-5K'
                WHEN LENGTH(content) < 10000 THEN '4.5K-1万'
                WHEN LENGTH(content) < 30000 THEN '5.1-3万'
                ELSE '6.>3万'
            END as bucket,
            COUNT(*) as cnt
        FROM articles
        WHERE content IS NOT NULL
        GROUP BY bucket
        ORDER BY
            CASE bucket
                WHEN '1.<500字' THEN 1
                WHEN '2.500-2K' THEN 2
                WHEN '3.2K-5K' THEN 3
                WHEN '4.5K-1万' THEN 4
                WHEN '5.1-3万' THEN 5
                ELSE 6
            END
    """).fetchall()

    # 12. 质量与活跃度指标
    all_rows = conn.execute("""
        SELECT id, title, content, summary, domains, tags, source_type, created_at
        FROM articles
    """).fetchall()

    content_lengths = []
    uncategorized_count = 0
    no_author_count = 0
    no_summary_count = 0
    domain_total_mentions = 0
    recent_7_count = 0
    recent_30_count = 0
    active_day_set = set()
    today = datetime.datetime.now().date()
    longest_articles = []
    needs_summary_articles = []
    uncategorized_articles = []
    no_author_articles = []

    def article_brief(row, content_len=None):
        content_len = len(row["content"] or "") if content_len is None else content_len
        return {
            "id": row["id"],
            "title": (row["title"] or "")[:80],
            "created_at": row["created_at"],
            "source_type": row["source_type"],
            "length": content_len,
        }

    for row in all_rows:
        content = row["content"] or ""
        content_len = len(content)
        content_lengths.append(content_len)
        longest_articles.append({"id": row["id"], "title": row["title"] or "", "length": content_len})

        try:
            domains = json.loads(row["domains"] or "[]")
        except Exception:
            domains = []
        if not domains:
            uncategorized_count += 1
            uncategorized_articles.append(article_brief(row, content_len))
        domain_total_mentions += len(domains)

        try:
            tags = json.loads(row["tags"] or "[]")
        except Exception:
            tags = []
        missing_author = not any(str(t).startswith("作者:") and str(t).strip() not in ("作者:", "作者:未知") for t in tags)
        if missing_author:
            no_author_count += 1
            no_author_articles.append(article_brief(row, content_len))

        if not (row["summary"] or "").strip():
            no_summary_count += 1
            needs_summary_articles.append(article_brief(row, content_len))

        created_raw = (row["created_at"] or "")[:10]
        try:
            created_day = datetime.datetime.strptime(created_raw, "%Y-%m-%d").date()
            delta_days = (today - created_day).days
            if 0 <= delta_days <= 6:
                recent_7_count += 1
            if 0 <= delta_days <= 29:
                recent_30_count += 1
                active_day_set.add(created_raw)
        except Exception:
            pass

    content_lengths.sort()
    median_content_len = 0
    if content_lengths:
        mid = len(content_lengths) // 2
        if len(content_lengths) % 2:
            median_content_len = content_lengths[mid]
        else:
            median_content_len = (content_lengths[mid - 1] + content_lengths[mid]) / 2

    coverage = {
        "summary_rate": round((total - no_summary_count) / total * 100, 1) if total else 0,
        "note_article_rate": round((note_stats[1] if note_stats else 0) / total * 100, 1) if total else 0,
        "categorized_rate": round((total - uncategorized_count) / total * 100, 1) if total else 0,
        "known_author_rate": round((total - no_author_count) / total * 100, 1) if total else 0,
    }

    freshness = {
        "recent_7_count": recent_7_count,
        "recent_30_count": recent_30_count,
        "active_days_30": len(active_day_set),
        "avg_daily_30": round(recent_30_count / 30, 2),
    }

    # 补齐近90天无新增的日期，让前端热力图更科学
    daily_map = {str(r[0]): r[1] for r in daily_stats}
    daily_filled = []
    for i in range(89, -1, -1):
        day = today - datetime.timedelta(days=i)
        day_key = day.isoformat()
        daily_filled.append({"day": day_key, "count": daily_map.get(day_key, 0)})

    longest_articles = sorted(longest_articles, key=lambda x: x["length"], reverse=True)[:8]
    needs_summary_articles = sorted(needs_summary_articles, key=lambda x: x["length"], reverse=True)[:8]
    uncategorized_articles = sorted(uncategorized_articles, key=lambda x: x["created_at"] or "", reverse=True)[:8]
    no_author_articles = sorted(no_author_articles, key=lambda x: x["created_at"] or "", reverse=True)[:8]

    recent_rows = conn.execute("""
        SELECT id, title, created_at, source_type, LENGTH(content) AS content_len
        FROM articles
        ORDER BY created_at DESC
        LIMIT 8
    """).fetchall()
    recent_articles = [{
        "id": r["id"],
        "title": (r["title"] or "")[:80],
        "created_at": r["created_at"],
        "source_type": r["source_type"],
        "length": r["content_len"] or 0,
    } for r in recent_rows]

    noted_rows = conn.execute("""
        SELECT a.id, a.title, a.created_at, a.source_type, LENGTH(a.content) AS content_len,
               COUNT(n.id) AS note_count, MAX(n.created_at) AS latest_note_at
        FROM articles a
        JOIN notes n ON n.article_id = a.id
        GROUP BY a.id
        ORDER BY latest_note_at DESC
        LIMIT 8
    """).fetchall()
    noted_articles = [{
        "id": r["id"],
        "title": (r["title"] or "")[:80],
        "created_at": r["latest_note_at"] or r["created_at"],
        "source_type": r["source_type"],
        "length": r["content_len"] or 0,
        "note_count": r["note_count"] or 0,
    } for r in noted_rows]
    
    conn.close()
    
    return {
        "overview": {
            "total": total,
            "url_count": url_count,
            "file_count": file_count,
            "note_count": note_stats[0] if note_stats else 0,
            "articles_with_notes": note_stats[1] if note_stats else 0,
            "avg_content_length": round(avg_content_len, 0),
            "median_content_length": round(median_content_len, 0),
            "domain_count": len(domain_counter),
            "avg_domains_per_article": round(domain_total_mentions / total, 2) if total else 0,
            "uncategorized_count": uncategorized_count,
            "no_author_count": no_author_count,
            "no_summary_count": no_summary_count,
        },
        "coverage": coverage,
        "freshness": freshness,
        "source_distribution": [{"type": r[0] or "unknown", "count": r[1]} for r in source_dist],
        "monthly_trend": [{"month": r[0], "count": r[1]} for r in monthly_stats],
        "domain_distribution": [{"domain": k, "count": v} for k, v in domain_counter.most_common(15)],
        "source_domains": [{"domain": k, "count": v} for k, v in domain_counter2.most_common(10)],
        "daily_trend": daily_filled,
        "author_distribution": [{"author": (r[0] or "").replace("作者:", "", 1), "count": r[1]} for r in author_rows],
        "content_length_buckets": [{"bucket": r[0], "count": r[1]} for r in len_rows],
        "longest_articles": longest_articles,
        "action_lists": {
            "needs_summary": needs_summary_articles,
            "uncategorized": uncategorized_articles,
            "no_author": no_author_articles,
            "recent": recent_articles,
            "noted": noted_articles,
        },
    }


class RecommendationFeedback(BaseModel):
    article_id: int
    action: str
    context: str = "recommendations"
    recommendation_date: Optional[str] = None
    extra: Optional[dict] = None


def _safe_json_list(raw: str) -> list:
    try:
        value = json.loads(raw or "[]")
        return value if isinstance(value, list) else []
    except Exception:
        return []


def _recommendation_hash(seed: str, article_id: int, modulo: int = 1000) -> int:
    digest = hashlib.sha256(f"{seed}:{article_id}".encode("utf-8")).hexdigest()
    return int(digest[:10], 16) % modulo


def _article_source_label(article: dict) -> str:
    if article.get("source_type") == "url":
        raw = article.get("source_url") or ""
        try:
            host = urlparse(raw).netloc.replace("www.", "")
            return host or "网页"
        except Exception:
            return "网页"
    return article.get("source_filename") or article.get("source_localpath") or "文档"


def _reading_load(content_len: int) -> str:
    if content_len < 1500:
        return "短读"
    if content_len < 6000:
        return "中等"
    if content_len < 30000:
        return "长读"
    return "重读"


def _build_recommendations(limit: int = 8, refresh: int = 0, exclude_ids: Optional[set] = None):
    today = datetime.datetime.now().date()
    today_key = today.isoformat()
    seed = f"{today_key}:{max(0, refresh)}"
    exclude_ids = exclude_ids or set()

    conn = get_db()
    article_rows = conn.execute("""
        SELECT a.id, a.title, a.summary, a.domains, a.tags, a.source_type,
               a.source_url, a.source_filename, a.source_localpath, a.created_at,
               LENGTH(a.content) AS content_len,
               COUNT(n.id) AS note_count
        FROM articles a
        LEFT JOIN notes n ON n.article_id = a.id
        GROUP BY a.id
    """).fetchall()

    interest_rows = conn.execute("""
        SELECT DISTINCT a.domains
        FROM articles a
        LEFT JOIN notes n ON n.article_id = a.id
        WHERE n.id IS NOT NULL
    """).fetchall()
    feedback_rows = conn.execute("""
        SELECT article_id, action, COUNT(*) AS cnt, MAX(created_at) AS latest
        FROM recommendation_feedback
        WHERE created_at >= date('now', '-45 days')
        GROUP BY article_id, action
    """).fetchall()
    conn.close()

    interest_counter = {}
    for row in interest_rows:
        for domain in _safe_json_list(row["domains"]):
            domain = str(domain).strip()
            if domain:
                interest_counter[domain] = interest_counter.get(domain, 0) + 1

    feedback_by_article = {}
    for row in feedback_rows:
        feedback_by_article.setdefault(row["article_id"], {})[row["action"]] = {
            "count": row["cnt"],
            "latest": row["latest"],
        }

    quality_terms = (
        "最高人民法院", "人民法院案例库", "指导性案例", "典型案例", "法院",
        "裁判规则", "司法解释", "公报", "纪要", "案例库",
    )
    scored = []
    for row in article_rows:
        article = dict(row)
        if article["id"] in exclude_ids:
            continue
        title = article.get("title") or ""
        summary = article.get("summary") or ""
        source_label = _article_source_label(article)
        search_text = " ".join([title, summary, source_label, article.get("source_url") or ""])
        domains = [str(d).strip() for d in _safe_json_list(article.get("domains")) if str(d).strip()]
        tags = [str(t).strip() for t in _safe_json_list(article.get("tags")) if str(t).strip()]
        content_len = int(article.get("content_len") or 0)
        feedback = feedback_by_article.get(article["id"], {})

        if feedback.get("not_interested") or feedback.get("dismissed"):
            continue

        score = 20
        reasons = []
        high_quality_source = any(term in search_text for term in quality_terms)
        related_domains = [d for d in domains if d in interest_counter]

        if len(summary.strip()) >= 40:
            score += 18
        elif summary.strip():
            score += 8

        if 600 <= content_len <= 12000:
            score += 18
            reasons.append("阅读负担适中")
        elif 12000 < content_len <= 50000:
            score += 6
        elif content_len > 200000:
            score -= 16

        if high_quality_source:
            score += 26
            reasons.append("权威来源或案例材料")

        if related_domains:
            related_bonus = min(24, 12 + sum(interest_counter.get(d, 0) for d in related_domains) * 3)
            score += related_bonus
            reasons.append(f"与你关注的{related_domains[0]}相关")

        note_count = int(article.get("note_count") or 0)
        if note_count:
            score += min(14, note_count * 4)
            reasons.append("已有笔记主题延伸")

        if not domains:
            score -= 5
            if high_quality_source:
                score += 6
                reasons.append("未分类但来源质量较高")

        created_day = None
        try:
            created_day = datetime.datetime.fromisoformat((article.get("created_at") or "")[:10]).date()
            age_days = (today - created_day).days
            if 0 <= age_days <= 14:
                score += 10
                reasons.append("近期收录但尚未充分利用")
            elif age_days >= 90:
                score += 4
        except Exception:
            age_days = 9999

        if feedback.get("opened"):
            score -= min(28, feedback["opened"]["count"] * 12)
        if feedback.get("skipped"):
            score -= min(22, feedback["skipped"]["count"] * 10)
        if feedback.get("read") or feedback.get("done"):
            score -= 35

        # A tiny deterministic jitter keeps each day fresh without changing on refresh.
        score += _recommendation_hash(seed, article["id"], 15) / 10

        if not reasons:
            if domains:
                reasons.append(f"{domains[0]}领域旧知回看")
            else:
                reasons.append("适合顺手浏览和整理")

        if high_quality_source or score >= 58:
            category = "must_read"
        elif related_domains or note_count:
            category = "related_old"
        elif not domains or "作者:未知" in tags:
            category = "tidy_value"
        else:
            category = "cold_start"

        scored.append({
            "id": article["id"],
            "title": title,
            "summary": summary,
            "domains": domains,
            "tags": tags,
            "source_type": article.get("source_type"),
            "source_url": article.get("source_url"),
            "source_filename": article.get("source_filename"),
            "source_label": source_label,
            "created_at": article.get("created_at"),
            "note_count": note_count,
            "score": round(score, 1),
            "reason": "；".join(reasons[:2]),
            "reading_load": _reading_load(content_len),
            "category": category,
            "sort_key": score * 1000 + _recommendation_hash(seed + ":rank", article["id"], 999),
        })

    scored.sort(key=lambda item: item["sort_key"], reverse=True)

    category_meta = {
        "must_read": {"title": "今日必看", "hint": "权威来源、近期材料或综合评分较高的内容"},
        "related_old": {"title": "相关旧知", "hint": "与你的笔记和常看领域有关"},
        "tidy_value": {"title": "待整理但有价值", "hint": "值得顺手标记、补分类或回看"},
        "cold_start": {"title": "随机发现", "hint": "从旧知识里捞出的备用内容"},
    }
    buckets = {key: [] for key in category_meta}
    used = set()
    quota = {"must_read": 3, "related_old": 3, "tidy_value": 2, "cold_start": 2}
    for item in scored:
        bucket = buckets.get(item["category"], buckets["cold_start"])
        if len(bucket) < quota.get(item["category"], 2):
            bucket.append(item)
            used.add(item["id"])

    flat = [item for key in ("must_read", "related_old", "tidy_value", "cold_start") for item in buckets[key]]
    if len(flat) < limit:
        for item in scored:
            if item["id"] not in used:
                flat.append(item)
                used.add(item["id"])
            if len(flat) >= limit:
                break
    else:
        flat = flat[:limit]

    categories = []
    flat_ids = {item["id"] for item in flat}
    for key in ("must_read", "related_old", "tidy_value", "cold_start"):
        items = [item for item in buckets[key] if item["id"] in flat_ids]
        if items:
            categories.append({"key": key, **category_meta[key], "items": items})

    return {
        "date": today_key,
        "refresh": refresh,
        "total": len(flat),
        "categories": categories,
        "items": flat,
    }


@app.get("/api/recommendations/today")
def get_today_recommendations(limit: int = 8, refresh: int = 0, exclude_ids: Optional[str] = None):
    """今日推荐：规则评分、按日稳定，refresh 用于换一批。"""
    limit = max(1, min(limit, 24))
    refresh = max(0, min(refresh, 30))
    parsed_exclude_ids = set()
    if exclude_ids:
        for raw_id in exclude_ids.split(","):
            raw_id = raw_id.strip()
            if raw_id.isdigit():
                parsed_exclude_ids.add(int(raw_id))
    return _build_recommendations(limit=limit, refresh=refresh, exclude_ids=parsed_exclude_ids)


@app.post("/api/recommendations/feedback")
def record_recommendation_feedback(payload: RecommendationFeedback):
    """记录推荐反馈，用于降低重复推荐。"""
    allowed_actions = {"opened", "skipped", "not_interested", "read", "done", "dismissed"}
    action = (payload.action or "").strip()
    if action not in allowed_actions:
        raise HTTPException(status_code=400, detail="不支持的反馈类型")

    recommendation_date = payload.recommendation_date or datetime.datetime.now().date().isoformat()
    now = datetime.datetime.now().isoformat()
    conn = get_db()
    article = conn.execute("SELECT id FROM articles WHERE id=?", (payload.article_id,)).fetchone()
    if not article:
        conn.close()
        raise HTTPException(status_code=404, detail="文章不存在")
    cur = conn.execute(
        """INSERT INTO recommendation_feedback
           (article_id, action, context, recommendation_date, extra_json, created_at)
           VALUES (?, ?, ?, ?, ?, ?)""",
        (
            payload.article_id,
            action,
            (payload.context or "recommendations")[:60],
            recommendation_date,
            json.dumps(payload.extra or {}, ensure_ascii=False),
            now,
        ),
    )
    conn.commit()
    conn.close()
    return {"success": True, "id": cur.lastrowid, "created_at": now}

