def _knowledge_job_dict(row: sqlite3.Row) -> dict:
    item = dict(row)
    try:
        item["warnings"] = json.loads(item.pop("warnings_json") or "[]")
    except Exception:
        item["warnings"] = []
    return item


def _knowledge_claim_row(conn: sqlite3.Connection, claim_id: int) -> sqlite3.Row:
    row = conn.execute("SELECT * FROM knowledge_claims WHERE id=?", (claim_id,)).fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="知识结论不存在")
    return row


def _knowledge_issue_row(conn: sqlite3.Connection, issue_id: int) -> sqlite3.Row:
    row = conn.execute("SELECT * FROM knowledge_issues WHERE id=?", (issue_id,)).fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="法律问题不存在")
    return row


def _knowledge_claim_quality(row: sqlite3.Row | dict) -> tuple[int, int, int]:
    status_rank = {"approved": 4, "needs_review": 3, "pending": 2, "rejected": 1, "merged": 0}
    return (
        status_rank.get(row["review_status"], 0),
        int(row["evidence_count"] or 0),
        -int(row["id"]),
    )


def _add_claim_to_merged_issue(
    conn: sqlite3.Connection, claim_id: int, issue_id: int, target_issue_id: int, now: str
) -> None:
    exists = conn.execute(
        "SELECT 1 FROM knowledge_claim_issues WHERE claim_id=? AND issue_id=?",
        (claim_id, target_issue_id),
    ).fetchone()
    if exists:
        return
    conn.execute(
        "INSERT INTO knowledge_claim_issues(claim_id,issue_id,is_primary) VALUES (?,?,1)",
        (claim_id, target_issue_id),
    )
    conn.execute(
        """INSERT INTO knowledge_issue_merge_effects
           (issue_id,target_issue_id,claim_id,effect_type,created_at)
           VALUES (?,?,?,'added_target_link',?)""",
        (issue_id, target_issue_id, claim_id, now),
    )


def _merge_knowledge_issue_records(
    conn: sqlite3.Connection, issue_id: int, target_id: int, audit_action: str = "merge"
) -> dict:
    """Merge an issue and consolidate exact duplicate claims without deleting history."""
    source = dict(_knowledge_issue_row(conn, issue_id))
    target = dict(_knowledge_issue_row(conn, target_id))
    if issue_id == target_id:
        raise HTTPException(status_code=400, detail="请选择不同的目标问题")
    if source["status"] != "active" or target["status"] != "active":
        raise HTTPException(status_code=400, detail="只能合并活动问题")
    if source["domain"] != target["domain"]:
        raise HTTPException(status_code=400, detail="不同专业领域的法律问题不能直接合并")

    now = datetime.datetime.now().isoformat()
    conn.execute("DELETE FROM knowledge_issue_merge_effects WHERE issue_id=?", (issue_id,))
    target_claims = conn.execute(
        """SELECT c.*,COUNT(DISTINCT e.id) AS evidence_count
           FROM knowledge_claims c
           JOIN knowledge_claim_issues ci ON ci.claim_id=c.id
           LEFT JOIN knowledge_claim_evidence e ON e.claim_id=c.id AND e.verified=1
           WHERE ci.issue_id=? AND c.review_status<>'merged'
           GROUP BY c.id ORDER BY c.id""",
        (target_id,),
    ).fetchall()
    source_claims = conn.execute(
        """SELECT c.*,COUNT(DISTINCT e.id) AS evidence_count
           FROM knowledge_claims c
           JOIN knowledge_claim_issues ci ON ci.claim_id=c.id
           LEFT JOIN knowledge_claim_evidence e ON e.claim_id=c.id AND e.verified=1
           WHERE ci.issue_id=? AND c.review_status<>'merged'
           GROUP BY c.id ORDER BY c.id""",
        (issue_id,),
    ).fetchall()
    source_claim_ids = {int(claim["id"]) for claim in source_claims}
    by_statement: dict[str, list[sqlite3.Row]] = {}
    for claim in target_claims:
        by_statement.setdefault(claim["normalized_statement"] or "", []).append(claim)

    for source_claim in source_claims:
        normalized = source_claim["normalized_statement"] or ""
        duplicates = [
            claim for claim in by_statement.get(normalized, [])
            if int(claim["id"]) != int(source_claim["id"])
        ] if normalized else []
        if not duplicates:
            _add_claim_to_merged_issue(conn, int(source_claim["id"]), issue_id, target_id, now)
            by_statement.setdefault(normalized, []).append(source_claim)
            continue

        candidates = duplicates + [source_claim]
        canonical = max(candidates, key=_knowledge_claim_quality)
        if int(canonical["id"]) == int(source_claim["id"]):
            _add_claim_to_merged_issue(conn, int(source_claim["id"]), issue_id, target_id, now)
        for duplicate in candidates:
            if int(duplicate["id"]) == int(canonical["id"]) or duplicate["review_status"] == "merged":
                continue
            if int(duplicate["id"]) in source_claim_ids:
                _add_claim_to_merged_issue(conn, int(duplicate["id"]), issue_id, target_id, now)
            before = dict(_knowledge_claim_row(conn, int(duplicate["id"])))
            conn.execute(
                """INSERT INTO knowledge_issue_merge_effects
                   (issue_id,target_issue_id,claim_id,effect_type,before_status,
                    before_merged_into_id,created_at)
                   VALUES (?,?,?,'merged_claim',?,?,?)""",
                (
                    issue_id, target_id, duplicate["id"], before["review_status"],
                    before["merged_into_id"], now,
                ),
            )
            conn.execute(
                """UPDATE knowledge_claims SET review_status='merged',merged_into_id=?,updated_at=?
                   WHERE id=?""",
                (canonical["id"], now, duplicate["id"]),
            )
            after = dict(_knowledge_claim_row(conn, int(duplicate["id"])))
            audit_knowledge_change(
                conn, "claim", int(duplicate["id"]), "merge_exact_claim_with_issue", before, after
            )
        by_statement[normalized] = [canonical]

    conn.execute(
        "UPDATE knowledge_issues SET status='merged',merged_into_id=?,updated_at=? WHERE id=?",
        (target_id, now, issue_id),
    )
    after_issue = dict(_knowledge_issue_row(conn, issue_id))
    audit_knowledge_change(conn, "issue", issue_id, audit_action, source, after_issue)
    return after_issue


def _unmerge_knowledge_issue_records(conn: sqlite3.Connection, issue_id: int) -> dict:
    source = dict(_knowledge_issue_row(conn, issue_id))
    if source["status"] != "merged" or not source["merged_into_id"]:
        raise HTTPException(status_code=400, detail="该法律问题没有处于合并状态")
    collision = conn.execute(
        """SELECT id FROM knowledge_issues
           WHERE normalized_title=? AND domain=? AND status='active' AND id<>?""",
        (source["normalized_title"], source["domain"], issue_id),
    ).fetchone()
    if collision:
        raise HTTPException(status_code=409, detail="存在同名活动问题，无法撤销合并")
    now = datetime.datetime.now().isoformat()
    effects = conn.execute(
        "SELECT * FROM knowledge_issue_merge_effects WHERE issue_id=? ORDER BY id DESC", (issue_id,)
    ).fetchall()
    for effect in effects:
        if effect["effect_type"] == "merged_claim":
            before = dict(_knowledge_claim_row(conn, int(effect["claim_id"])))
            conn.execute(
                """UPDATE knowledge_claims SET review_status=?,merged_into_id=?,updated_at=? WHERE id=?""",
                (
                    effect["before_status"] or "pending", effect["before_merged_into_id"], now,
                    effect["claim_id"],
                ),
            )
            after = dict(_knowledge_claim_row(conn, int(effect["claim_id"])))
            audit_knowledge_change(
                conn, "claim", int(effect["claim_id"]), "unmerge_exact_claim_with_issue", before, after
            )
        elif effect["effect_type"] == "added_target_link":
            conn.execute(
                "DELETE FROM knowledge_claim_issues WHERE claim_id=? AND issue_id=?",
                (effect["claim_id"], effect["target_issue_id"]),
            )
    conn.execute("DELETE FROM knowledge_issue_merge_effects WHERE issue_id=?", (issue_id,))
    conn.execute(
        "UPDATE knowledge_issues SET status='active',merged_into_id=NULL,updated_at=? WHERE id=?",
        (now, issue_id),
    )
    after_issue = dict(_knowledge_issue_row(conn, issue_id))
    audit_knowledge_change(conn, "issue", issue_id, "unmerge", source, after_issue)
    return after_issue


def _repair_legacy_knowledge_issue_merges(conn: sqlite3.Connection) -> int:
    """Backfill claim links/consolidation for issue merges created before merge effects existed."""
    legacy_rows = conn.execute(
        """SELECT i.* FROM knowledge_issues i
           WHERE i.status='merged' AND i.merged_into_id IS NOT NULL
             AND NOT EXISTS (
               SELECT 1 FROM knowledge_issue_merge_effects e WHERE e.issue_id=i.id
             )
           ORDER BY i.id DESC"""
    ).fetchall()
    repaired = 0
    for legacy_row in legacy_rows:
        source = dict(legacy_row)
        target_id = int(source["merged_into_id"])
        visited = {int(source["id"])}
        target = None
        while target_id not in visited:
            visited.add(target_id)
            target_row = conn.execute(
                "SELECT * FROM knowledge_issues WHERE id=?", (target_id,)
            ).fetchone()
            if not target_row:
                break
            target = dict(target_row)
            if target["status"] == "active":
                break
            if target["status"] != "merged" or not target["merged_into_id"]:
                target = None
                break
            target_id = int(target["merged_into_id"])
        if not target or target["status"] != "active" or source["domain"] != target["domain"]:
            continue

        conn.execute(
            "UPDATE knowledge_issues SET status='active',merged_into_id=NULL WHERE id=?",
            (source["id"],),
        )
        try:
            _merge_knowledge_issue_records(
                conn, int(source["id"]), int(target["id"]), "repair_legacy_merge"
            )
        except Exception:
            conn.execute(
                """UPDATE knowledge_issues SET status='merged',merged_into_id=?,updated_at=?
                   WHERE id=?""",
                (source["merged_into_id"], source["updated_at"], source["id"]),
            )
            conn.execute(
                "DELETE FROM knowledge_issue_merge_effects WHERE issue_id=?", (source["id"],)
            )
            continue
        repaired += 1
    return repaired


def _enqueue_knowledge_job(article_id: int, trigger_type: str, force: bool = False) -> tuple[int, bool]:
    with get_db() as conn:
        try:
            job_id, created = create_extraction_job(
                conn, article_id, trigger_type=trigger_type, model=DEFAULT_AI_MODEL, force=force
            )
        except ValueError as exc:
            raise HTTPException(status_code=404, detail=str(exc)) from exc
        conn.commit()
    _knowledge_worker_event.set()
    return job_id, created


def _auto_enqueue_knowledge_if_relevant(article_id: int, trigger_type: str = "import") -> Optional[int]:
    with get_db() as conn:
        article = conn.execute(
            "SELECT id,title,summary,domains,content FROM articles WHERE id=?", (article_id,)
        ).fetchone()
        if not article or not is_knowledge_article(article):
            return None
        # Cost guard: importing or previewing a long article must never enqueue
        # model work before the reader explicitly opens and authorizes it.
        if len(knowledge_article_text(article["content"] or "")) >= RELATION_LONG_ARTICLE_CHARS:
            return None
        if conn.execute(
            "SELECT 1 FROM knowledge_extraction_exclusions WHERE article_id=?", (article_id,)
        ).fetchone():
            return None
    job_id, _ = _enqueue_knowledge_job(article_id, trigger_type)
    return job_id


def _knowledge_extraction_prompt(article: dict, paragraphs: list[dict]) -> list[dict]:
    paragraph_text = "\n\n".join(
        f"[段落 {item['paragraph_index']}] {item.get('heading') or ''}\n{item.get('text') or ''}"
        for item in paragraphs
    )
    schema = {
        "claims": [{
            "domain": "必须从文章专业领域中选择最匹配的一项；没有专业领域则填综合法律",
            "issue_title": "一个明确、可复用的法律问题",
            "statement": "仅依据原文得出的单一规则或观点",
            "claim_type": "rule|exception|procedure|risk|practice",
            "conditions": "原文明示的适用事实条件，没有则为空字符串",
            "exceptions": "原文明示的例外，没有则为空字符串",
            "procedural_stage": "原文明示的程序阶段，没有则为空字符串",
            "jurisdiction": "原文明示的地域，没有则为空字符串",
            "court_level": "原文明示的法院层级，没有则为空字符串",
            "authority_type": "法律/司法解释/案例/会议纪要/文章/其他；无法判断则为空",
            "authority_level": "原文明示的效力层级，没有则为空字符串",
            "valid_from": "原文明示的生效日期，没有则为空字符串",
            "valid_to": "原文明示的失效日期，没有则为空字符串",
            "confidence": 0.0,
            "evidence": [{
                "paragraph_index": 1,
                "stance": "supports|opposes|limits|background",
                "quote": "必须从该段逐字连续复制不少于8个字",
            }],
        }]
    }
    return [
        {
            "role": "system",
            "content": (
                "你是严谨的中国法律知识整理员。只从给定段落提取与文章所属专业领域直接相关、"
                "可复用的中国法律知识。专业领域只能选择文章已有分类之一；文章没有分类时使用综合法律。"
                "不得使用模型记忆，不得补写原文没有的"
                "时间、地域、层级或适用条件。支持观点、反对观点、例外和限制必须拆成不同结论，"
                "不得揉成统一结论。每条结论必须至少有一项逐字引文；无直接依据就不要输出。"
                "只返回JSON对象，不要代码块或解释。"
            ),
        },
        {
            "role": "user",
            "content": (
                f"【文章】{article.get('title') or ''}\n"
                f"【来源类型】{article.get('source_type') or ''}\n\n"
                f"【文章专业领域】{json.dumps(article_knowledge_domains(article), ensure_ascii=False)}\n\n"
                f"【可引用段落】\n{paragraph_text}\n\n"
                f"请严格按以下结构返回：\n{json.dumps(schema, ensure_ascii=False)}"
            ),
        },
    ]


async def _run_knowledge_extraction_job(job_id: int) -> None:
    with get_db() as conn:
        job = conn.execute("SELECT * FROM knowledge_extraction_jobs WHERE id=?", (job_id,)).fetchone()
        if not job or job["status"] not in {"queued", "running"}:
            return
        article = conn.execute("SELECT * FROM articles WHERE id=?", (job["article_id"],)).fetchone()
        if not article:
            conn.execute(
                "UPDATE knowledge_extraction_jobs SET status='failed',error='文章不存在',completed_at=?,updated_at=? WHERE id=?",
                (datetime.datetime.now().isoformat(), datetime.datetime.now().isoformat(), job_id),
            )
            conn.commit()
            return
        paragraphs = conn.execute(
            "SELECT * FROM article_paragraphs WHERE article_id=? ORDER BY paragraph_index", (article["id"],)
        ).fetchall()
        if not paragraphs:
            rebuild_article_paragraphs(conn, article["id"], article["content"] or "")
            paragraphs = conn.execute(
                "SELECT * FROM article_paragraphs WHERE article_id=? ORDER BY paragraph_index", (article["id"],)
            ).fetchall()
        batches = split_paragraph_batches(paragraphs, 18000)
        now = datetime.datetime.now().isoformat()
        conn.execute(
            """UPDATE knowledge_extraction_jobs SET status='running',started_at=COALESCE(started_at,?),
               total_batches=?,error='',updated_at=? WHERE id=?""",
            (now, len(batches), now, job_id),
        )
        # 旧的未审核提取结果不再与新一轮结果混用；保留记录供审计查看。
        conn.execute(
            """UPDATE knowledge_claims SET review_status='rejected',reviewer_note='已由新一轮提取替代',updated_at=?
               WHERE review_status='pending' AND id IN (
                 SELECT DISTINCT c.id FROM knowledge_claims c
                 JOIN knowledge_claim_evidence e ON e.claim_id=c.id
                 WHERE e.article_id=? AND c.extraction_job_id<>?
               )""",
            (now, article["id"], job_id),
        )
        existing_extracted = conn.execute(
            "SELECT COUNT(*) FROM knowledge_claims WHERE extraction_job_id=?", (job_id,)
        ).fetchone()[0]
        conn.commit()
        article_dict = dict(article)

    warnings: list[str] = []
    extracted = int(existing_extracted or 0)
    actual_model = DEFAULT_AI_MODEL
    try:
        for batch_index, batch in enumerate(batches, 1):
            messages = _knowledge_extraction_prompt(article_dict, batch)
            answer, _reasoning, actual_model = await _call_ai_answer_with_continuation(
                DEFAULT_AI_MODEL, messages, temperature=0.1, max_tokens=4000,
                continuation_tokens=2000, max_continuations=1,
            )
            try:
                data = parse_model_json(answer)
            except (ValueError, json.JSONDecodeError) as first_error:
                # 结构化输出偶尔会在长批次中被截断；只重试当前批次一次，
                # 不重复已经成功保存的其他批次。
                repair_messages = messages + [
                    {"role": "assistant", "content": answer},
                    {
                        "role": "user",
                        "content": (
                            "上一份JSON无法解析（可能被截断或缺少逗号）。请重新从本批段落生成一份完整、"
                            "合法的JSON对象；减少结论数量以确保闭合，不要解释，不要使用代码块。"
                        ),
                    },
                ]
                repaired, _repair_reasoning, actual_model = await _call_ai_answer_with_continuation(
                    actual_model, repair_messages, temperature=0.0, max_tokens=5000,
                    continuation_tokens=1000, max_continuations=0,
                )
                try:
                    data = parse_model_json(repaired)
                    warnings.append(f"第{batch_index}批首次JSON无效，已自动重试：{first_error}")
                except (ValueError, json.JSONDecodeError) as repair_error:
                    # 默认模型连续两次无法形成闭合 JSON 时，改用现有备用模型只处理当前批次。
                    # 这不改变日常模型选择，也不会重复已经成功保存的批次。
                    fallback_messages = messages + [{
                        "role": "user",
                        "content": (
                            "默认模型连续两次未能返回合法JSON。请只保留本批最重要且证据完整的结论，"
                            "最多输出6条，严格返回一个闭合的JSON对象，不要解释或使用代码块。"
                        ),
                    }]
                    fallback_answer, _fallback_reasoning, actual_model = await _call_ai_answer_with_continuation(
                        _effective_fallback_model(), fallback_messages, temperature=0.0, max_tokens=5000,
                        continuation_tokens=1000, max_continuations=0,
                    )
                    data = parse_model_json(fallback_answer)
                    warnings.append(
                        f"第{batch_index}批默认模型两次JSON无效，已切换备用模型："
                        f"{first_error}；{repair_error}"
                    )
            with get_db() as conn:
                count, batch_warnings = save_extraction_batch(
                    conn, job_id, int(article_dict["id"]), data, actual_model
                )
                extracted += count
                warnings.extend(batch_warnings)
                conn.execute(
                    """UPDATE knowledge_extraction_jobs SET processed_batches=?,extracted_claims=?,
                       warnings_json=?,model=?,updated_at=? WHERE id=?""",
                    (
                        batch_index, extracted, json.dumps(warnings[-200:], ensure_ascii=False), actual_model,
                        datetime.datetime.now().isoformat(), job_id,
                    ),
                )
                conn.commit()
        with get_db() as conn:
            now = datetime.datetime.now().isoformat()
            conn.execute(
                """UPDATE knowledge_extraction_jobs SET status='completed',processed_batches=total_batches,
                   extracted_claims=?,warnings_json=?,model=?,completed_at=?,updated_at=? WHERE id=?""",
                (extracted, json.dumps(warnings[-200:], ensure_ascii=False), actual_model, now, now, job_id),
            )
            # Reuse the newly verified evidence as relationship candidates.  This
            # is local work and never causes a second model call.
            scan_article_relation_rules(conn, int(article_dict["id"]))
            conn.commit()
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        with get_db() as conn:
            now = datetime.datetime.now().isoformat()
            conn.execute(
                """UPDATE knowledge_claims SET review_status='rejected',
                   reviewer_note='提取任务未完整完成，等待重新提取',updated_at=?
                   WHERE extraction_job_id=? AND review_status='pending'""",
                (now, job_id),
            )
            conn.execute(
                """UPDATE knowledge_extraction_jobs SET status='failed',error=?,warnings_json=?,
                   completed_at=?,updated_at=? WHERE id=?""",
                (str(exc)[:1200], json.dumps(warnings[-200:], ensure_ascii=False), now, now, job_id),
            )
            conn.commit()


def _knowledge_taxonomy_prompt(domain: str, issues: list[dict]) -> list[dict]:
    sample = "\n".join(f"#{item['id']} {item['title']}" for item in issues)
    schema = {
        "categories": [{
            "name": "主题大类",
            "description": "本类边界",
            "children": [{"name": "细分子类", "description": "与相邻子类的区别"}],
        }]
    }
    return [
        {
            "role": "system",
            "content": (
                "你是中国法律知识分类架构师。你的任务只是在一个既定法律领域内建立稳定、"
                "可复用的主题层级，不判断结论对错。分类必须互相区分、名称简短、能覆盖给定问题。"
                "只返回完整JSON对象，不要代码块或解释。"
            ),
        },
        {
            "role": "user",
            "content": (
                f"法律领域：{domain}\n\n现有法律问题样本：\n{sample}\n\n"
                "请建立5至12个主题大类，每个大类包含2至10个细分子类。"
                "不得把具体案件名、法条号或单个问题直接作为分类名。分类总深度固定为两级。\n"
                f"严格按此结构返回：{json.dumps(schema, ensure_ascii=False)}"
            ),
        },
    ]


def _knowledge_assignment_prompt(
    domain: str, taxonomy: list[dict], issues: list[dict]
) -> list[dict]:
    issue_text = "\n".join(f"#{item['id']} {item['title']}" for item in issues)
    schema = {
        "assignments": [{
            "issue_id": 1,
            "category_path": ["主题大类", "细分子类"],
            "confidence": 0.0,
        }],
        "merge_groups": [{
            "issue_ids": [1, 2],
            "recommended_title": "建议保留的规范问题名称",
            "reason": "为什么疑似相同；若只是相关、上下位、一般与例外或正反观点则不要输出",
            "confidence": 0.0,
        }],
    }
    return [
        {
            "role": "system",
            "content": (
                "你是谨慎的中国法律知识整理员。为每个法律问题选择且只选择一个最具体的分类路径。"
                "你还可以提出疑似重复问题组，但必须严格：只有适用对象、法律关系、程序阶段和核心请求"
                "实质相同才可建议；一般规则与例外、正反观点、程序与实体、相邻但不同的问题绝不能合并。"
                "你只提出建议，系统不会自动合并。只返回完整JSON对象。"
            ),
        },
        {
            "role": "user",
            "content": (
                f"法律领域：{domain}\n\n可选分类：\n"
                f"{json.dumps(taxonomy, ensure_ascii=False)}\n\n待整理问题：\n{issue_text}\n\n"
                f"严格按此结构返回：{json.dumps(schema, ensure_ascii=False)}"
            ),
        },
    ]


async def _call_knowledge_json(messages: list[dict], max_tokens: int = 5000) -> tuple[dict, str]:
    answer, _reasoning, actual_model = await _call_ai_answer_with_continuation(
        DEFAULT_AI_MODEL, messages, temperature=0.0, max_tokens=max_tokens,
        continuation_tokens=1200, max_continuations=1,
    )
    try:
        return parse_model_json(answer), actual_model
    except (ValueError, json.JSONDecodeError):
        repair = messages + [
            {"role": "assistant", "content": answer},
            {"role": "user", "content": "上一份JSON不完整。请减少内容并重新返回一个合法闭合的JSON对象，不要解释。"},
        ]
        fixed, _reasoning, actual_model = await _call_ai_answer_with_continuation(
            actual_model, repair, temperature=0.0, max_tokens=max_tokens,
            continuation_tokens=800, max_continuations=0,
        )
        return parse_model_json(fixed), actual_model


async def _run_knowledge_organization_job(job_id: int) -> None:
    warnings: list[str] = []
    actual_model = DEFAULT_AI_MODEL
    try:
        with get_db() as conn:
            job = conn.execute(
                "SELECT * FROM knowledge_organization_jobs WHERE id=?", (job_id,)
            ).fetchone()
            if not job or job["status"] not in {"queued", "running"}:
                return
            domain = job["domain"]
            issues = [dict(row) for row in conn.execute(
                """SELECT id,title FROM knowledge_issues
                   WHERE domain=? AND status='active' ORDER BY title,id""", (domain,)
            ).fetchall()]
            if not issues:
                raise ValueError("当前领域没有可整理的法律问题")
            batches = [issues[index:index + 60] for index in range(0, len(issues), 60)]
            now = datetime.datetime.now().isoformat()
            conn.execute(
                """UPDATE knowledge_organization_jobs SET status='running',started_at=COALESCE(started_at,?),
                   total_issues=?,total_batches=?,error='',updated_at=? WHERE id=?""",
                (now, len(issues), len(batches), now, job_id),
            )
            conn.commit()

        with get_db() as conn:
            existing_categories = knowledge_category_rows(conn, domain)
        if existing_categories:
            majors = [item for item in existing_categories if not item["parent_id"]]
            taxonomy = [{
                "name": major["name"],
                "description": major.get("description") or "",
                "children": [
                    {"name": child["name"], "description": child.get("description") or ""}
                    for child in existing_categories if child["parent_id"] == major["id"]
                ],
            } for major in majors]
            category_paths = {}
            for major in majors:
                category_paths[(major["name"], "")] = int(major["id"])
                for child in existing_categories:
                    if child["parent_id"] == major["id"]:
                        category_paths[(major["name"], child["name"])] = int(child["id"])
        else:
            # Spread the sample across the alphabetically sorted domain instead of only using newest records.
            stride = max(1, len(issues) // 180)
            sample = issues[::stride][:180]
            taxonomy_data, actual_model = await _call_knowledge_json(
                _knowledge_taxonomy_prompt(domain, sample), max_tokens=4500
            )
            taxonomy = taxonomy_data.get("categories") or []
            if not isinstance(taxonomy, list) or not taxonomy:
                raise ValueError("AI未形成可用的分类结构")
            with get_db() as conn:
                category_paths = save_category_taxonomy(conn, domain, taxonomy, "ai")
                conn.commit()
        if not category_paths:
            raise ValueError("分类结构为空")

        assigned_total = 0
        suggested_total = 0
        for batch_index, batch in enumerate(batches, 1):
            data, actual_model = await _call_knowledge_json(
                _knowledge_assignment_prompt(domain, taxonomy, batch), max_tokens=6000
            )
            with get_db() as conn:
                assigned, suggested, batch_warnings = save_issue_organization_batch(
                    conn, domain, data, category_paths,
                    {int(item["id"]) for item in batch}, actual_model,
                )
                assigned_total += assigned
                suggested_total += suggested
                warnings.extend(batch_warnings)
                conn.execute(
                    """UPDATE knowledge_organization_jobs SET processed_batches=?,assigned_issues=?,
                       suggestion_count=?,warnings_json=?,model=?,updated_at=? WHERE id=?""",
                    (
                        batch_index, assigned_total, suggested_total,
                        json.dumps(warnings[-100:], ensure_ascii=False), actual_model,
                        datetime.datetime.now().isoformat(), job_id,
                    ),
                )
                conn.commit()
        with get_db() as conn:
            suggested_total += add_heuristic_issue_suggestions(conn, domain)
            now = datetime.datetime.now().isoformat()
            conn.execute(
                """UPDATE knowledge_organization_jobs SET status='completed',processed_batches=total_batches,
                   assigned_issues=?,suggestion_count=?,warnings_json=?,model=?,completed_at=?,updated_at=?
                   WHERE id=?""",
                (
                    assigned_total, suggested_total, json.dumps(warnings[-100:], ensure_ascii=False),
                    actual_model, now, now, job_id,
                ),
            )
            conn.commit()
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        with get_db() as conn:
            now = datetime.datetime.now().isoformat()
            conn.execute(
                """UPDATE knowledge_organization_jobs SET status='failed',error=?,warnings_json=?,
                   completed_at=?,updated_at=? WHERE id=?""",
                (str(exc)[:1200], json.dumps(warnings[-100:], ensure_ascii=False), now, now, job_id),
            )
            conn.commit()


async def _knowledge_worker_loop() -> None:
    while True:
        await _knowledge_worker_event.wait()
        _knowledge_worker_event.clear()
        while True:
            with get_db() as conn:
                organization_job = conn.execute(
                    "SELECT id FROM knowledge_organization_jobs WHERE status='queued' ORDER BY id LIMIT 1"
                ).fetchone()
                queued_jobs = conn.execute(
                    """SELECT j.id,j.content_hash,a.content,s.ai_authorized_hash
                       FROM knowledge_extraction_jobs j
                       JOIN articles a ON a.id=j.article_id
                       LEFT JOIN article_relation_state s ON s.article_id=j.article_id
                       WHERE j.status='queued' ORDER BY j.id"""
                ).fetchall()
                extraction_job = next(
                    (
                        row for row in queued_jobs
                        if len(knowledge_article_text(row["content"] or "")) < RELATION_LONG_ARTICLE_CHARS
                        or (row["ai_authorized_hash"] or "") == row["content_hash"]
                    ),
                    None,
                )
            if organization_job:
                await _run_knowledge_organization_job(int(organization_job["id"]))
                continue
            if not extraction_job:
                break
            await _run_knowledge_extraction_job(int(extraction_job["id"]))


def _knowledge_now() -> str:
    return datetime.datetime.now().isoformat(timespec="seconds")


def _knowledge_search_tokens(value: str) -> list[str]:
    raw_tokens = re.findall(r"[A-Za-z0-9_]{2,}|[\u4e00-\u9fff]{2,}", value or "")
    tokens: set[str] = set()
    for token in raw_tokens:
        if re.fullmatch(r"[\u4e00-\u9fff]+", token):
            if len(token) <= 8:
                tokens.add(token)
            for width in (2, 3, 4, 5, 6):
                if len(token) >= width:
                    tokens.update(token[index:index + width] for index in range(len(token) - width + 1))
        else:
            tokens.add(token.casefold())
    stop = {"什么", "哪些", "如何", "是否", "可以", "问题", "规定", "关于", "以及", "相关"}
    return [token for token in tokens if token not in stop]


