@app.get("/api/legal-knowledge/extractions")
def list_legal_knowledge_extractions(status: str = "", limit: int = 200, latest_only: bool = False):
    clauses, params = [], []
    if latest_only:
        clauses.append("j.id IN (SELECT MAX(id) FROM knowledge_extraction_jobs GROUP BY article_id)")
    if status:
        clauses.append("j.status=?")
        params.append(status)
    where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
    with get_db() as conn:
        rows = conn.execute(
            f"""SELECT j.*,a.title AS article_title,
                CASE WHEN x.article_id IS NULL THEN 0 ELSE 1 END AS excluded
                FROM knowledge_extraction_jobs j
                JOIN articles a ON a.id=j.article_id
                LEFT JOIN knowledge_extraction_exclusions x ON x.article_id=j.article_id {where}
                ORDER BY j.id DESC LIMIT ?""", (*params, max(1, min(limit, 1000)))
        ).fetchall()
        total = int(conn.execute(
            f"SELECT COUNT(*) FROM knowledge_extraction_jobs j {where}", params
        ).fetchone()[0])
        count_clauses = []
        if latest_only:
            count_clauses.append("j.id IN (SELECT MAX(id) FROM knowledge_extraction_jobs GROUP BY article_id)")
        count_where = f"WHERE {' AND '.join(count_clauses)}" if count_clauses else ""
        counts = {
            row["status"]: int(row["n"])
            for row in conn.execute(
                f"SELECT j.status,COUNT(*) n FROM knowledge_extraction_jobs j {count_where} GROUP BY j.status"
            ).fetchall()
        }
    return {"jobs": [_knowledge_job_dict(row) for row in rows], "total": total, "counts": counts}


_PROVISION_HEADING_RE = re.compile(
    r'(?m)^[ \t\u3000]*第(?:\d{1,5}|[零〇一二两三四五六七八九十百千万]+)条'
    r'(?=[ \t\u3000]|$)'
)


def _extract_provision_from_text(content: str, number: int) -> str:
    """Extract one complete provision, including its list items, from article text."""
    plain = _plain_article_text(content)
    if not plain:
        return ""
    locators = (f'第{number}条', f'第{_int_to_chinese_number(number)}条')
    matches = []
    for locator in locators:
        pattern = re.compile(
            rf'(?m)^[ \t\u3000]*{re.escape(locator)}(?=[ \t\u3000]|$)'
        )
        match = pattern.search(plain)
        if match:
            matches.append(match)
    if not matches:
        return ""
    match = min(matches, key=lambda item: item.start())
    next_heading = _PROVISION_HEADING_RE.search(plain, match.end())
    end = next_heading.start() if next_heading else len(plain)
    return plain[match.start():end].strip()


def _provision_law_hint(question: str) -> str:
    """Extract the law/document title immediately before a provision reference."""
    match = re.search(
        r'第\s*(?:\d{1,5}|[零〇一二两三四五六七八九十百千万]+)\s*条',
        question or '',
    )
    if not match:
        return ""
    prefix = (question or '')[:match.start()].strip()
    quoted = re.findall(r'《([^》]+)》', prefix)
    if quoted:
        return quoted[-1].strip()
    prefix = re.sub(r'^(?:请问|请查询|查询|帮我查(?:一下)?|现行|我国)+', '', prefix).strip()
    prefix = re.split(r'[，。？！、；：\s]', prefix)[-1].strip('“”"\'（）()【】')
    return prefix[-60:]


def _find_exact_provisions(question: str, conn, article_ids: list = None) -> Optional[dict]:
    """Deterministically locate exact statutory text for direct provision-text questions."""
    numbers = _legal_provision_numbers(question)
    if not numbers or not any(marker in question for marker in (
        '原文', '条文', '内容', '是什么', '怎么规定', '如何规定', '具体规定'
    )):
        return None
    # Compound questions still need analysis by the selected model. The exact locator
    # remains part of normal RAG retrieval, but should not short-circuit the answer.
    if any(marker in question for marker in (
        '分析', '解释', '含义', '适用', '影响', '案例', '区别', '比较', '责任', '要点', '为什么'
    )):
        return None
    law_hint = _provision_law_hint(question)
    if not law_hint:
        return None

    conditions, params = [], []
    for number in numbers:
        number_conditions = []
        for locator in (f'第{number}条', f'第{_int_to_chinese_number(number)}条'):
            number_conditions.append("content LIKE ? ESCAPE '\\'")
            params.append(f"%{escape_like_pattern(locator)}%")
        conditions.append('(' + ' OR '.join(number_conditions) + ')')
    where = ' AND '.join(conditions)
    if article_ids:
        where += f" AND id IN ({','.join('?' * len(article_ids))})"
        params.extend(int(article_id) for article_id in article_ids)
    rows = conn.execute(
        f"""SELECT id,title,content,source_url,source_filename
            FROM articles WHERE {where}""",
        params,
    ).fetchall()

    normalized_hint = re.sub(r'[\s《》“”"\'（）()]+', '', law_hint)
    candidates = []
    commentary_markers = ('解读', '评析', '实务', '案例', '答疑', '研究', '批复')
    for row in rows:
        title = row['title'] or ''
        normalized_title = re.sub(r'[\s《》“”"\'（）()]+', '', title)
        if normalized_hint not in normalized_title:
            continue
        provisions = []
        for number in numbers:
            text = _extract_provision_from_text(row['content'] or '', number)
            if not text:
                provisions = []
                break
            provisions.append({'number': number, 'text': text})
        if not provisions:
            continue
        if normalized_title == normalized_hint:
            score = 300
        elif normalized_title.endswith(normalized_hint):
            score = 240
        else:
            score = 100
        if any(marker in title for marker in commentary_markers) and not any(marker in law_hint for marker in commentary_markers):
            score -= 80
        score += len(provisions) * 20
        candidates.append((score, len(title), row, provisions))
    if not candidates:
        return None
    _, _, row, provisions = max(candidates, key=lambda item: (item[0], -item[1], item[2]['id']))

    first_locator = f"第{_int_to_chinese_number(provisions[0]['number'])}条"
    paragraph = conn.execute(
        """SELECT paragraph_index,char_start,char_end,heading FROM article_paragraphs
           WHERE article_id=? AND (text LIKE ? OR heading LIKE ?)
           ORDER BY CASE WHEN text LIKE ? THEN 0 ELSE 1 END, paragraph_index LIMIT 1""",
        (row['id'], f'{first_locator}%', f'{first_locator}%', f'{first_locator}%'),
    ).fetchone()
    paragraph_heading = (paragraph['heading'] or '') if paragraph else ''
    if first_locator not in paragraph_heading:
        paragraph_heading = first_locator
    return {
        'id': row['id'],
        'title': row['title'],
        'source': row['source_url'] or row['source_filename'] or '',
        'provisions': provisions,
        'paragraph_index': paragraph['paragraph_index'] if paragraph else None,
        'char_start': paragraph['char_start'] if paragraph else None,
        'char_end': paragraph['char_end'] if paragraph else None,
        'heading': paragraph_heading,
    }


def _exact_provision_response(match: dict, model: str, source_mode: str) -> dict:
    """Build a model-independent response so exact text cannot be lost or paraphrased."""
    blocks = []
    for provision in match['provisions']:
        blocks.append(f"> {provision['text'].replace(chr(10), chr(10) + '> ')}")
    answer = f"《{match['title']}》相关条文原文如下：\n\n" + '\n\n'.join(blocks)
    quote = '\n\n'.join(item['text'] for item in match['provisions'])
    cited = {
        'id': match['id'], 'article_id': match['id'], 'title': match['title'],
        'paragraph_index': match.get('paragraph_index'), 'heading': match.get('heading') or '',
        'quote': quote, 'excerpt': quote[:240], 'char_start': match.get('char_start'),
        'char_end': match.get('char_end'), 'verified': True, 'source': match.get('source') or '',
    }
    return {
        'answer': answer,
        'reasoning': None,
        'is_reasoning_model': False,
        'sources': [{'id': match['id'], 'title': match['title'], 'source': match.get('source') or ''}],
        'cited_sources': [cited],
        'articles_found': 1,
        'approved_knowledge_used': 0,
        'case_library_used': False,
        'case_library_error': None,
        'national_law_used': False,
        'national_law_error': None,
        'external_sources': [],
        'source_mode': source_mode,
        'model_used': 'workbuddy' if model == 'workbuddy' else model,
        'retrieval_mode': 'exact_provision',
    }

def search_articles_for_qa(question: str, conn, top_k: int = 8, article_ids: list = None):
    """根据问题检索最相关的文章片段。

    策略：
    1. jieba 精确分词 + n-gram 滑窗补全（捕获「取回权」「优先权」等被分词切断的法律词汇）
    2. 精确短语（≥3字）给予更高权重（title×6，summary×4，content×2）
    3. 普通关键词（title×3，summary×2，content×1）
    4. top_k 扩大到 8，确保长尾相关文章不被遗漏
    5. 对每篇文章截取与问题最相关的段落，而不是简单取正文前N字
    6. article_ids：若提供，则只在这些文章 ID 范围内检索（用于标签模式）
    """
    import re

    # 法律常见停用词（只过滤通用虚词，保留法律专业词）
    STOPWORDS = {
        '的', '了', '是', '在', '和', '有', '也', '与', '等', '对', '中', '为', '以',
        '及', '或', '但', '被', '将', '能', '应', '不', '可', '其', '我', '你', '他',
        '她', '它', '这', '那', '些', '什么', '怎么', '如何', '哪些', '哪个', '为什么',
        '帮我', '分析', '介绍', '解释', '请问', '之', '于', '并', '且',
        '而', '则', '若', '当', '因', '由', '自', '向', '从', '至', '到', '后', '前',
        '请', '告诉', '说明',
        # 问句常见词（不是法律词汇，不用于搜索）
        '多少', '几条', '几个', '几种', '哪里', '哪儿', '什么时候', '多久',
    }

    # ── 1. jieba 分词（精确模式）──────────────────────────────
    clean_q = re.sub(r'[\s，。？！、；：""''【】《》\(\)（）\-—…]+', ' ', question).strip()

    try:
        import jieba
        seg_list = list(jieba.cut(clean_q, cut_all=False))
        # jieba 词：长度≥2 且不在停用词中，直接保留
        jieba_words = [w for w in seg_list if len(w) >= 2 and w not in STOPWORDS]
    except Exception:
        jieba_words = [w for w in clean_q.split() if len(w) >= 2]

    # ── 2. 相邻词拼接，补全 jieba 切断的法律合成词 ──────────────
    # 策略：把相邻的 jieba 词（包括单字）两两或三个拼接，生成可能的法律合成词
    # 例："取回" + "权" → "取回权"；"行政" + "诉讼" + "法" → "行政诉讼法"
    # 注意：只拼接相邻的、且拼接结果有意义（至少一端不是纯停用词）的词
    ALL_STOPWORDS_CHARS = {'的', '了', '是', '在', '和', '有', '也', '与', '等', '对',
                           '中', '为', '以', '及', '或', '但', '被', '将', '能', '应',
                           '不', '可', '其', '之', '于', '并', '且', '而', '则', '若',
                           '当', '因', '由', '自', '向', '从', '至', '到', '后', '前',
                           '人', '者', '又', '此', '该', '该', '各', '其'}
    combo_ngrams = set()
    for i in range(len(seg_list) - 1):
        a = seg_list[i]
        b = seg_list[i + 1]
        # 两词都不是停用词字符时才拼接
        if a not in ALL_STOPWORDS_CHARS and b not in ALL_STOPWORDS_CHARS:
            combo = a + b
            if len(combo) >= 3:
                combo_ngrams.add(combo)
        # 三词拼接（捕获"行政诉讼法"等）
        if i + 2 < len(seg_list):
            c = seg_list[i + 2]
            if a not in ALL_STOPWORDS_CHARS and c not in ALL_STOPWORDS_CHARS:
                combo3 = a + b + c
                if len(combo3) >= 4:
                    combo_ngrams.add(combo3)

    # ── 3. 合并关键词 ──────────────────────────────────────────
    # jieba_words 直接全部保留（它们是 jieba 识别的完整词，优先级最高）
    # combo_ngrams 中去掉被 jieba_words 中某词完全包含的词（减少噪音）
    jieba_set_long = {w for w in jieba_words if len(w) >= 2}
    extra_combos = []
    for gram in sorted(combo_ngrams, key=len, reverse=True):
        if any(gram in jw for jw in jieba_set_long):
            continue  # 已被 jieba 词覆盖，跳过
        extra_combos.append(gram)

    # 条号必须放在普通分词前。正文通常写作“第一百条”，而用户更常输入“第100条”；
    # 若不归一化，长法规只会因标题命中而返回文首或随机段落。
    provision_locators = _legal_provision_locators(question)
    final_keywords = list(provision_locators) + list(jieba_words)  # jieba 词全部保留
    seen = set(final_keywords)
    for gram in extra_combos:
        if gram not in seen:
            final_keywords.append(gram)
            seen.add(gram)

    # 限制总数，防止 SQL 过长
    final_keywords = final_keywords[:20]

    if not final_keywords:
        final_keywords = [clean_q[:10]]

    # ── 4. 构建 WHERE 条件（OR 关系，任意命中即入选）──────────
    def _esc(s):
        return s.replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')

    conditions, where_params = [], []
    for kw in final_keywords:
        like = f"%{_esc(kw)}%"
        conditions.append(
            "(title LIKE ? ESCAPE '\\' OR content LIKE ? ESCAPE '\\' OR summary LIKE ? ESCAPE '\\')"
        )
        where_params.extend([like, like, like])

    if not conditions:
        return []

    # ── 5. 构建评分表达式 ────────────────────────────────────
    # 精确短语（≥3字）权重是普通关键词的2倍
    score_cases, score_params = [], []
    for kw in final_keywords:
        like = f"%{_esc(kw)}%"
        w_title   = 6 if len(kw) >= 3 else 3
        w_summary = 4 if len(kw) >= 3 else 2
        w_content = 2 if len(kw) >= 3 else 1
        score_cases.append(
            f"(CASE WHEN title   LIKE ? ESCAPE '\\' THEN {w_title}   ELSE 0 END + "
            f" CASE WHEN summary LIKE ? ESCAPE '\\' THEN {w_summary} ELSE 0 END + "
            f" CASE WHEN content LIKE ? ESCAPE '\\' THEN {w_content} ELSE 0 END)"
        )
        score_params.extend([like, like, like])

    score_expr = " + ".join(score_cases)
    where_clause = " OR ".join(conditions)

    # 若指定了 article_ids，在 WHERE 中增加 id IN (...) 限制
    id_filter = ""
    id_params = []
    if article_ids:
        placeholders = ",".join("?" * len(article_ids))
        id_filter = f" AND id IN ({placeholders})"
        id_params = list(article_ids)

    sql = f"""
        SELECT id, title, summary, content, source_url, source_filename, created_at,
               ({score_expr}) AS relevance_score
        FROM articles
        WHERE ({where_clause}){id_filter}
        ORDER BY relevance_score DESC, created_at DESC
        LIMIT {top_k}
    """
    try:
        all_params = score_params + where_params + id_params
        cursor = conn.execute(sql, all_params)
        rows = cursor.fetchall()
    except Exception as e:
        print(f"[search_articles_for_qa] SQL 执行出错: {e}")
        return []

    # ── 6. 截取正文中与问题最相关的段落 ────────────────────────
    # 对短文：直接返回全文
    # 对长文：找命中最密集的最多两段（每段1500字），拼接返回（总共≤3500字）
    def _extract_relevant_snippet(content: str, keywords: list, max_len: int = 6000) -> str:
        if not content:
            return ""

        # 精确条号问题优先返回目标条文，而不是让通用滑窗被法规名称、年份等高频词带偏。
        exact_parts = []
        for number in _legal_provision_numbers(question):
            part = _extract_provision_from_text(content, number)
            if part and part not in exact_parts:
                exact_parts.append(part)
        if exact_parts:
            exact_text = "\n\n".join(exact_parts)
            return exact_text[:max_len]
        if len(content) <= max_len:
            return content

        SEGMENT = max_len // 3  # 每段最多2000字

        # 收集所有关键词的所有命中位置，按长度加权
        hit_positions = []
        for kw in keywords:
            weight = len(kw)  # 长词权重更高
            start_idx = 0
            while True:
                pos = content.find(kw, start_idx)
                if pos < 0:
                    break
                hit_positions.append((pos, weight))
                start_idx = pos + 1

        if not hit_positions:
            return content[:max_len]

        window = SEGMENT // 2  # 以候选中心为基准，前后各看 window 距离内的命中数

        # ── 找第一段：命中最密集的中心 ──────────────────────────
        best_center1 = hit_positions[0][0]
        best_score1 = 0
        for center_pos, _ in hit_positions:
            score = sum(w for p, w in hit_positions if abs(p - center_pos) <= window)
            if score > best_score1:
                best_score1 = score
                best_center1 = center_pos

        start1 = max(0, best_center1 - SEGMENT // 3)
        end1 = min(len(content), start1 + SEGMENT)
        seg1 = content[start1:end1]

        # ── 找第二段：排除第一段覆盖范围，再找次密集的中心 ────────
        # 只考虑不与第一段重叠的命中点
        remaining_hits = [(p, w) for p, w in hit_positions if p < start1 - 200 or p > end1 + 200]

        seg2 = ""
        if remaining_hits:
            best_center2 = remaining_hits[0][0]
            best_score2 = 0
            for center_pos, _ in remaining_hits:
                score = sum(w for p, w in remaining_hits if abs(p - center_pos) <= window)
                if score > best_score2:
                    best_score2 = score
                    best_center2 = center_pos

            # 只有次段得分达到第一段的15%才有价值
            if best_score2 >= best_score1 * 0.15:
                start2 = max(0, best_center2 - SEGMENT // 3)
                end2 = min(len(content), start2 + SEGMENT)
                seg2 = content[start2:end2]

        if seg2:
            # 按照在文章中的先后顺序拼接
            if start1 <= (max(0, best_center2 - SEGMENT // 3) if seg2 else start1):
                parts = [seg1, seg2]
            else:
                parts = [seg2, seg1]

            # ── 找第三段：排除前两段覆盖范围，再找次密集的中心 ────────
            remaining_hits2 = [(p, w) for p, w in hit_positions
                               if p < min(start1, best_center2 - SEGMENT // 3) - 200
                               or p > max(end1, end2 if seg2 else end1) + 200]
            seg3 = ""
            if remaining_hits2:
                best_center3 = remaining_hits2[0][0]
                best_score3 = 0
                for center_pos, _ in remaining_hits2:
                    score = sum(w for p, w in remaining_hits2 if abs(p - center_pos) <= window)
                    if score > best_score3:
                        best_score3 = score
                        best_center3 = center_pos
                if best_score3 >= best_score1 * 0.10:
                    start3 = max(0, best_center3 - SEGMENT // 3)
                    end3 = min(len(content), start3 + SEGMENT)
                    seg3 = content[start3:end3]
                    if seg3:
                        # 按位置排序插入
                        parts.append(seg3)
                        parts.sort(key=lambda p: content.find(p[:20]) if p[:20] in content else 0)

            return "\n\n…（相关段落分隔）…\n\n".join(parts)
        return seg1

    results = []
    for row in rows:
        raw_content = row["content"] or ""
        plain_content = _plain_article_text(raw_content)
        content_snippet = _extract_relevant_snippet(plain_content, final_keywords, max_len=6000)
        # 对于超长文章（>10000字），额外附加尾部800字，避免条文总数等关键信息被截断
        tail_snippet = ""
        if len(plain_content) > 10000 and not provision_locators:
            tail_raw = plain_content[-800:].strip()
            # 只有尾部内容与关键片段不重叠时才附加
            if tail_raw and tail_raw[-150:] not in content_snippet:
                tail_snippet = tail_raw
        results.append({
            "id": row["id"],
            "title": row["title"] or "（无标题）",
            "summary": row["summary"] or "",
            "content": content_snippet,
            "tail": tail_snippet,   # 超长文章的尾部片段
            "content_len": len(plain_content),  # 纯文本全文字数
            "source": row["source_url"] or row["source_filename"] or "",
        })
    return results


def _question_keywords(question: str) -> list:
    clean_q = re.sub(r'[\s，。？！、；：""''【】《》\(\)（）\-—…]+', ' ', question or '').strip()
    stop = {'的', '了', '是', '在', '和', '有', '与', '对', '中', '为', '以', '及', '或', '但', '请', '如何', '哪些', '什么'}
    try:
        words = [w for w in jieba.cut(clean_q, cut_all=False) if len(w) >= 2 and w not in stop]
    except Exception:
        words = [w for w in clean_q.split() if len(w) >= 2]
    if clean_q and len(clean_q) >= 3:
        words.insert(0, clean_q[:24])
    aliases = {
        '一审': '第一审', '二审': '第二审', '再审': '审判监督程序',
        '终审': '第二审', '诉前保全': '申请保全',
    }
    for short, formal in aliases.items():
        if short in clean_q:
            words.append(formal)
    if '上诉' in clean_q and ('期限' in clean_q or '多久' in clean_q or '多少天' in clean_q):
        words.extend(['不服', '提起上诉', '判决书送达', '裁定书送达'])
    deduped = []
    # 精确条号的中、阿拉伯数字形式拥有最高检索优先级。
    for w in _legal_provision_locators(question) + words:
        if w not in deduped:
            deduped.append(w)
    return deduped[:16]


def search_paragraphs_for_qa(question: str, conn, top_k: int = 10, article_ids: list = None) -> list:
    """Return paragraph-level snippets with stable REF ids for verifiable answers."""
    keywords = _question_keywords(question)
    if not keywords:
        return []

    if article_ids:
        missing = conn.execute(
            f"""
            SELECT a.id, a.content
            FROM articles a
            WHERE a.id IN ({','.join('?' * len(article_ids))})
              AND NOT EXISTS (SELECT 1 FROM article_paragraphs p WHERE p.article_id = a.id)
            """,
            list(article_ids),
        ).fetchall()
    else:
        missing = conn.execute(
            """
            SELECT a.id, a.content
            FROM articles a
            WHERE NOT EXISTS (SELECT 1 FROM article_paragraphs p WHERE p.article_id = a.id)
            ORDER BY a.id DESC LIMIT 25
            """
        ).fetchall()
    for row in missing:
        rebuild_article_paragraphs(conn, row["id"], row["content"] or "")

    conditions, params = [], []
    for kw in keywords:
        like = f"%{escape_like_pattern(kw)}%"
        conditions.append("(a.title LIKE ? ESCAPE '\\' OR a.summary LIKE ? ESCAPE '\\' OR p.heading LIKE ? ESCAPE '\\' OR p.text LIKE ? ESCAPE '\\')")
        params.extend([like, like, like, like])
    id_filter = ""
    if article_ids:
        id_filter = f" AND a.id IN ({','.join('?' * len(article_ids))})"
        params.extend([int(i) for i in article_ids])
    score_parts, score_params = [], []
    provision_locators = set(_legal_provision_locators(question))
    for kw in keywords:
        like = f"%{escape_like_pattern(kw)}%"
        # A direct provision locator is far more selective than a title word such as
        # “公司法”; otherwise every paragraph in a matching statute receives the same
        # title score and can outrank the requested article.
        if kw in provision_locators:
            prefix_like = f"{escape_like_pattern(kw)}%"
            score_parts.append(
                "(CASE WHEN a.title LIKE ? ESCAPE '\\' THEN 150 ELSE 0 END + "
                "CASE WHEN a.summary LIKE ? ESCAPE '\\' THEN 30 ELSE 0 END + "
                "CASE WHEN p.heading LIKE ? ESCAPE '\\' THEN 10 ELSE 0 END + "
                "CASE WHEN p.text LIKE ? ESCAPE '\\' THEN 60 ELSE 0 END + "
                "CASE WHEN p.text LIKE ? ESCAPE '\\' THEN 240 ELSE 0 END)"
            )
            score_params.extend([like, like, like, like, prefix_like])
        else:
            weight = 3 if len(kw) >= 3 else 1
            score_parts.append(
                f"(CASE WHEN a.title LIKE ? ESCAPE '\\' THEN {weight * 5} ELSE 0 END + "
                f"CASE WHEN a.summary LIKE ? ESCAPE '\\' THEN {weight * 3} ELSE 0 END + "
                f"CASE WHEN p.heading LIKE ? ESCAPE '\\' THEN {weight} ELSE 0 END + "
                f"CASE WHEN p.text LIKE ? ESCAPE '\\' THEN {weight * 2} ELSE 0 END)"
            )
            score_params.extend([like, like, like, like])
    sql = f"""
        SELECT p.article_id, p.paragraph_index, p.text, p.char_start, p.char_end, p.heading,
               a.title, a.source_url, a.source_filename, ({' + '.join(score_parts)}) AS score
        FROM article_paragraphs p
        JOIN articles a ON a.id = p.article_id
        WHERE ({' OR '.join(conditions)}){id_filter}
        ORDER BY score DESC, a.created_at DESC
        LIMIT ?
    """
    rows = conn.execute(sql, score_params + params + [top_k]).fetchall()
    result = []
    for r in rows:
        result.append({
            "article_id": r["article_id"],
            "id": r["article_id"],
            "paragraph_index": r["paragraph_index"],
            "title": r["title"],
            "text": r["text"],
            "quote": r["text"],
            "char_start": r["char_start"],
            "char_end": r["char_end"],
            "heading": r["heading"] or "",
            "source": r["source_url"] or r["source_filename"] or "",
        })
    return result


def build_paragraph_context(paragraphs: list, max_chars: int = 24000) -> tuple:
    parts, sources, paragraph_map = [], [], {}
    used_articles = set()
    total = 0
    for p in paragraphs:
        text = p.get("text") or ""
        if not text:
            continue
        line = f"[REF:{p['article_id']}:{p['paragraph_index']}]《{p['title']}》"
        if p.get("heading"):
            line += f"（{p['heading']}）"
        line += f"\n{text}\n"
        if total + len(line) > max_chars:
            break
        total += len(line)
        parts.append(line)
        paragraph_map[(p["article_id"], p["paragraph_index"])] = p
        if p["article_id"] not in used_articles:
            used_articles.add(p["article_id"])
            sources.append({"id": p["article_id"], "title": p["title"], "source": p.get("source", "")})
    return "\n".join(parts), sources, paragraph_map


def load_all_article_paragraphs_for_qa(conn, article_id: int, title: str = "") -> list:
    """Return every indexed paragraph of one article in its source order.

    This is deliberately separate from semantic retrieval: requests such as
    “逐一提炼 31 个小点” require an exhaustive reading of the selected article,
    not the most similar handful of paragraphs.
    """
    rows = conn.execute(
        """SELECT article_id, paragraph_index, text, char_start, char_end, heading
           FROM article_paragraphs WHERE article_id=? ORDER BY paragraph_index""",
        (article_id,),
    ).fetchall()
    if not rows:
        rebuild_article_paragraphs(conn, article_id)
        rows = conn.execute(
            """SELECT article_id, paragraph_index, text, char_start, char_end, heading
               FROM article_paragraphs WHERE article_id=? ORDER BY paragraph_index""",
            (article_id,),
        ).fetchall()
    return [{
        "article_id": row["article_id"],
        "id": row["article_id"],
        "paragraph_index": row["paragraph_index"],
        "title": title,
        "text": row["text"],
        "quote": row["text"],
        "char_start": row["char_start"],
        "char_end": row["char_end"],
        "heading": row["heading"] or "",
        "source": "",
    } for row in rows]


def _get_kb_meta(conn) -> dict:
    """获取知识库元信息（文章总数、分类统计、所有标题列表）"""
    total = conn.execute("SELECT COUNT(*) FROM articles").fetchone()[0]
    rows = conn.execute("SELECT id, title FROM articles ORDER BY id").fetchall()
    titles = [{"id": r[0], "title": r[1]} for r in rows]
    return {"total": total, "titles": titles}


def _is_kb_meta_question(question: str) -> bool:
    """判断是否是询问知识库本身信息的元问题"""
    META_PATTERNS = [
        "知识库", "几篇", "多少篇", "有哪些文章", "有哪些内容", "有哪些法",
        "收录了", "包含哪些", "有什么文章", "文章列表", "有几篇", "包括哪些",
        "有哪些资料", "有哪些法规", "有哪些法律", "有哪些案例", "收集了",
        "入库", "库里", "库中",
    ]
    return any(p in question for p in META_PATTERNS)


def _is_casual_chat(question: str) -> bool:
    """判断是否是日常闲聊（与法律/知识库无关）"""
    CASUAL_PATTERNS = [
        "你好", "您好", "hello", "hi", "早上好", "下午好", "晚上好",
        "谢谢", "感谢", "再见", "拜拜",
        "天气", "吃饭", "心情", "开心", "难过",
        "你是谁", "你叫什么", "你能做什么", "怎么使用", "帮助",
    ]
    q_lower = question.lower()
    return any(p in q_lower for p in CASUAL_PATTERNS)


