def _row_to_project(row, conn=None) -> dict:
    data = dict(row)
    data["article_count"] = 0
    if conn:
        data["article_count"] = conn.execute(
            "SELECT COUNT(*) FROM research_project_articles WHERE project_id=?",
            (row["id"],)
        ).fetchone()[0]
    return data


def _case_client_names(conn, case_id: int) -> str:
    rows = conn.execute(
        """
        SELECT role, name FROM case_manager_parties
        WHERE case_id=? AND party_group='client' AND name<>''
        ORDER BY sort_order, id
        """,
        (case_id,),
    ).fetchall()
    return "、".join([f"{r['role']}：{r['name']}" if r["role"] else r["name"] for r in rows])


def _case_to_research_case(conn, row, include_children: bool = True) -> dict:
    item = dict(row)
    project = conn.execute(
        "SELECT id FROM research_projects WHERE case_id=? ORDER BY updated_at DESC, id DESC LIMIT 1",
        (row["id"],),
    ).fetchone()
    project_id = project["id"] if project else None
    item["project_id"] = project_id
    item["client_names"] = _case_client_names(conn, row["id"])
    item["article_count"] = 0
    item["ledger_count"] = 0
    item["memo_entry_count"] = 0
    if project_id:
        item["article_count"] = conn.execute(
            "SELECT COUNT(*) FROM research_project_articles WHERE project_id=?",
            (project_id,),
        ).fetchone()[0]
        item["ledger_count"] = conn.execute(
            "SELECT COUNT(*) FROM research_case_ledgers WHERE project_id=?",
            (project_id,),
        ).fetchone()[0]
        item["memo_entry_count"] = conn.execute(
            "SELECT COUNT(*) FROM research_case_memo_entries WHERE project_id=?",
            (project_id,),
        ).fetchone()[0]
    item["series_children"] = []
    if include_children and item.get("case_kind") == "series":
        children = conn.execute(
            """SELECT * FROM case_manager_cases
               WHERE parent_series_id=? AND case_kind='series_child'
                 AND COALESCE(source_status,'active')='active'
               ORDER BY series_order,id""",
            (row["id"],),
        ).fetchall()
        item["series_children"] = [_case_to_research_case(conn, child, False) for child in children]
        item["article_count"] += sum(int(child.get("article_count") or 0) for child in item["series_children"])
        item["ledger_count"] += sum(int(child.get("ledger_count") or 0) for child in item["series_children"])
        item["memo_entry_count"] += sum(int(child.get("memo_entry_count") or 0) for child in item["series_children"])
    return item


def _ensure_case_research_project(conn, case_id: int) -> int:
    case = conn.execute("SELECT * FROM case_manager_cases WHERE id=?", (case_id,)).fetchone()
    if not case:
        raise HTTPException(status_code=404, detail="案件不存在")
    project = conn.execute(
        "SELECT id FROM research_projects WHERE case_id=? ORDER BY updated_at DESC, id DESC LIMIT 1",
        (case_id,),
    ).fetchone()
    if project:
        return project["id"]
    now = datetime.datetime.now().isoformat()
    client = _case_client_names(conn, case_id)
    case_info = "\n".join([part for part in [case["case_type"] or "", case["memo"] or ""] if part])
    cur = conn.execute(
        """
        INSERT INTO research_projects (case_id, name, client, case_info, issues, status, notes, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (case_id, case["title"], client, case_info, "", case["source_status"] or "active", "", now, now),
    )
    return cur.lastrowid


def _timeline_public_entry(row):
    item = dict(row)
    # Local filesystem paths belong to the desktop-scoped resource API only.
    item.pop('resources_json', None)
    return item


def _case_research_detail(conn, case_id: int) -> dict:
    project_id = _ensure_case_research_project(conn, case_id)
    case = conn.execute("SELECT * FROM case_manager_cases WHERE id=?", (case_id,)).fetchone()
    detail = _project_detail(conn, project_id)
    detail["case"] = _case_to_research_case(conn, case)
    detail["ledgers"] = [
        _timeline_public_entry(r)
        for r in conn.execute(
            """
            SELECT * FROM research_case_ledgers
            WHERE project_id=?
            ORDER BY COALESCE(NULLIF(happened_at, ''), created_at) DESC, id DESC
            """,
            (project_id,),
        ).fetchall()
    ]
    detail["memo_entries"] = [
        _timeline_public_entry(r)
        for r in conn.execute(
            """
            SELECT * FROM research_case_memo_entries
            WHERE project_id=?
            ORDER BY COALESCE(NULLIF(happened_at, ''), created_at) DESC, id DESC
            """,
            (project_id,),
        ).fetchall()
    ]
    if case["case_kind"] == "series":
        child_projects = conn.execute(
            """SELECT rp.id,c.series_code,c.series_display_name,c.title
               FROM research_projects rp
               JOIN case_manager_cases c ON c.id=rp.case_id
               WHERE c.parent_series_id=? AND c.case_kind='series_child'
                 AND COALESCE(c.source_status,'active')<>'deleted'
               ORDER BY c.series_order,c.id""",
            (case_id,),
        ).fetchall()
        project_labels = {project_id: "系列事项"}
        for row in child_projects:
            project_labels[int(row["id"])] = " · ".join(
                part for part in [row["series_code"] or "", row["series_display_name"] or row["title"] or ""] if part
            )
        project_ids = list(project_labels)
        article_map = {}
        for linked_project_id in project_ids:
            for article in _project_linked_articles_full(conn, linked_project_id):
                existing = article_map.get(int(article["id"]))
                if existing:
                    existing["linked_project_ids"].append(linked_project_id)
                    existing["series_case_labels"].append(project_labels[linked_project_id])
                else:
                    article["linked_project_id"] = linked_project_id
                    article["linked_project_ids"] = [linked_project_id]
                    article["series_case_labels"] = [project_labels[linked_project_id]]
                    article_map[int(article["id"])] = article
        detail["articles"] = sorted(article_map.values(), key=lambda item: item.get("added_at") or "", reverse=True)
        marks = ",".join("?" for _ in project_ids)
        detail["ledgers"] = [
            {**_timeline_public_entry(row), "series_case_label": project_labels.get(int(row["project_id"]), "系列事项")}
            for row in conn.execute(
                f"""SELECT * FROM research_case_ledgers WHERE project_id IN ({marks})
                    ORDER BY COALESCE(NULLIF(happened_at, ''), created_at) DESC,id DESC""",
                project_ids,
            ).fetchall()
        ]
        detail["memo_entries"] = [
            {**_timeline_public_entry(row), "series_case_label": project_labels.get(int(row["project_id"]), "系列事项")}
            for row in conn.execute(
                f"""SELECT * FROM research_case_memo_entries WHERE project_id IN ({marks})
                    ORDER BY COALESCE(NULLIF(happened_at, ''), created_at) DESC,id DESC""",
                project_ids,
            ).fetchall()
        ]
    return detail


def _project_linked_articles_full(conn, project_id: int) -> list:
    rows = conn.execute(
        """
        SELECT a.id, a.title, a.summary, a.content, a.domains, a.tags,
               a.source_type, a.source_url, a.source_filename, a.created_at,
               a.pinned, rpa.added_from, rpa.created_at AS added_at
        FROM research_project_articles rpa
        JOIN articles a ON a.id = rpa.article_id
        WHERE rpa.project_id=?
        ORDER BY rpa.created_at DESC
        """,
        (project_id,),
    ).fetchall()
    articles = []
    for row in rows:
        item = dict(row)
        item["domains"] = json.loads(item.get("domains") or "[]")
        item["tags"] = json.loads(item.get("tags") or "[]")
        item["pinned"] = bool(item.get("pinned", 0))
        articles.append(item)
    return articles


def _case_research_detail_for_offline(conn, case_id: int) -> dict:
    detail = _case_research_detail(conn, case_id)
    project_id = detail.get("project", {}).get("id")
    if project_id:
        if detail.get("case", {}).get("case_kind") != "series":
            detail["articles"] = _project_linked_articles_full(conn, project_id)
        questions = conn.execute(
            "SELECT * FROM research_project_questions WHERE project_id=? ORDER BY created_at ASC",
            (project_id,),
        ).fetchall()
        detail["questions"] = []
        for row in questions:
            item = dict(row)
            item["sources"] = json.loads(item.pop("sources_json") or "[]")
            item["cited_sources"] = json.loads(item.pop("cited_sources_json") or "[]")
            detail["questions"].append(item)
        memos = conn.execute(
            "SELECT * FROM research_memos WHERE project_id=? ORDER BY updated_at DESC",
            (project_id,),
        ).fetchall()
        detail["memos"] = []
        for row in memos:
            item = dict(row)
            item["sources"] = json.loads(item.pop("sources_json") or "[]")
            detail["memos"].append(item)
    return detail


def _require_project(conn, project_id: int):
    row = conn.execute("SELECT * FROM research_projects WHERE id=?", (project_id,)).fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="案件研究不存在")
    return row


def _get_project_article_ids(conn, project_id: int) -> list:
    return [
        r["article_id"]
        for r in conn.execute(
            "SELECT article_id FROM research_project_articles WHERE project_id=?",
            (project_id,)
        ).fetchall()
    ]


def _project_detail(conn, project_id: int) -> dict:
    project = conn.execute("SELECT * FROM research_projects WHERE id=?", (project_id,)).fetchone()
    if not project:
        raise HTTPException(status_code=404, detail="研究项目不存在")
    articles = conn.execute(
        """
        SELECT a.id, a.title, a.summary, a.domains, a.source_type, a.source_url,
               a.source_filename, a.created_at, rpa.added_from, rpa.created_at AS added_at
        FROM research_project_articles rpa
        JOIN articles a ON a.id = rpa.article_id
        WHERE rpa.project_id=?
        ORDER BY rpa.created_at DESC
        """,
        (project_id,)
    ).fetchall()
    notes = conn.execute(
        "SELECT id, content, created_at FROM research_project_notes WHERE project_id=? ORDER BY created_at DESC",
        (project_id,)
    ).fetchall()
    memos = conn.execute(
        "SELECT id, title, question, created_at, updated_at FROM research_memos WHERE project_id=? ORDER BY updated_at DESC",
        (project_id,)
    ).fetchall()
    ledgers = conn.execute(
        "SELECT * FROM research_case_ledgers WHERE project_id=? ORDER BY COALESCE(NULLIF(happened_at, ''), created_at) DESC, id DESC",
        (project_id,)
    ).fetchall()
    memo_entries = conn.execute(
        "SELECT * FROM research_case_memo_entries WHERE project_id=? ORDER BY COALESCE(NULLIF(happened_at, ''), created_at) DESC, id DESC",
        (project_id,)
    ).fetchall()
    return {
        "project": _row_to_project(project, conn),
        "articles": [dict(r) for r in articles],
        "notes": [dict(r) for r in notes],
        "memos": [dict(r) for r in memos],
        "ledgers": [_timeline_public_entry(r) for r in ledgers],
        "memo_entries": [_timeline_public_entry(r) for r in memo_entries],
    }


def _validate_ai_ask_history_key(value: str) -> str:
    key = (value or "").strip()
    if not key.startswith("ask_history_") or len(key) > 500:
        raise HTTPException(status_code=400, detail="问答历史标识无效")
    return key


@app.get("/api/ai-ask/history")
def get_ai_ask_history():
    """统一数据库中的 AI增强历史；浏览器仅保留当前页面的内存缓存。"""
    conn = get_db()
    # 空会话没有可恢复内容，清理旧版本遗留的空记录，避免历史接口持续返回无效条目。
    conn.execute(
        """
        DELETE FROM ai_ask_conversations
        WHERE NOT EXISTS (
            SELECT 1 FROM ai_ask_messages m
            WHERE m.conversation_id = ai_ask_conversations.id
        )
        """
    )
    conn.commit()
    conversations = conn.execute(
        "SELECT * FROM ai_ask_conversations ORDER BY updated_at DESC, id DESC"
    ).fetchall()
    result = []
    for conversation in conversations:
        try:
            context = json.loads(conversation["context_json"] or "null")
        except (TypeError, ValueError):
            context = None
        rows = conn.execute(
            """
            SELECT m.*, c.title AS case_title, rp.id AS linked_project_id
            FROM ai_ask_messages m
            LEFT JOIN case_manager_cases c ON c.id=m.case_id
            LEFT JOIN research_project_questions rq ON rq.id=m.research_question_id
            LEFT JOIN research_projects rp ON rp.id=rq.project_id
            WHERE m.conversation_id=?
            ORDER BY m.created_at_ms, m.id
            """,
            (conversation["id"],),
        ).fetchall()
        records = []
        for row in rows:
            item = {
                "id": row["id"],
                "role": row["role"],
                "content": row["content"],
                "sources": json.loads(row["sources_json"] or "null"),
                "citedSources": json.loads(row["cited_sources_json"] or "null"),
                "reasoning": row["reasoning"] or None,
                "isReasoningModel": bool(row["is_reasoning_model"]),
                "model": row["model"] or "",
                "askContext": context,
                "researchQuestionId": row["research_question_id"],
                "strategyVersionId": row["strategy_version_id"],
                "strategyVersion": row["strategy_version"] or "",
                "strategyDecision": json.loads(row["strategy_decision_json"] or "null"),
                "ts": int(row["created_at_ms"] or 0),
            }
            if row["role"] == "ai":
                from .ai_artifacts import extract_artifacts
                item["artifacts"] = extract_artifacts(row["content"])
            if row["case_id"]:
                item["caseLink"] = {
                    "caseId": int(row["case_id"]),
                    "caseTitle": row["case_title"] or "未命名案件",
                    "projectId": row["linked_project_id"],
                }
            meta = ai_context.one(conn,'SELECT * FROM ai_context_messages WHERE message_id=?',(row['id'],))
            item['contextEligible'] = bool(meta and meta['eligible'])
            item['noMemory'] = bool(meta and meta['no_memory'])
            item['contextUsage'] = json.loads(meta['usage_json']) if meta else None
            records.append(item)
        result.append({
            "history_key": conversation["history_key"],
            "context": context,
            "records": records,
            "updated_at": conversation["updated_at"],
            "version": (conn.execute('SELECT history_version FROM ai_context_conversations WHERE history_key=?',(conversation['history_key'],)).fetchone() or [0])[0],
        })
    conn.close()
    return {"conversations": result}


@app.post("/api/ai-ask/history/save")
def save_ai_ask_history(payload: AIAskHistoryPayload, background_tasks: BackgroundTasks = None):
    key = _validate_ai_ask_history_key(payload.history_key)
    if len(payload.records or []) > 1000:
        raise HTTPException(status_code=400, detail="单个问答会话记录过多")
    now = datetime.datetime.now().isoformat()
    conn = get_db()
    try:
        conn.execute('BEGIN IMMEDIATE')
        context_case_id = ai_context.start_save(conn,key,payload.context,payload.records,payload.version)
        if not payload.records:
            ai_context.delete_conversation(conn,key)
            conn.execute("DELETE FROM ai_ask_conversations WHERE history_key=?", (key,))
            conn.commit()
            return {"success": True, "history_key": key, "deleted": True}
        row = conn.execute(
            "SELECT id FROM ai_ask_conversations WHERE history_key=?", (key,)
        ).fetchone()
        if row:
            conversation_id = int(row["id"])
            conn.execute(
                "UPDATE ai_ask_conversations SET context_json=?, updated_at=? WHERE id=?",
                (json.dumps(payload.context, ensure_ascii=False), now, conversation_id),
            )

        else:
            cur = conn.execute(
                """INSERT INTO ai_ask_conversations
                   (history_key, context_json, created_at, updated_at) VALUES (?, ?, ?, ?)""",
                (key, json.dumps(payload.context, ensure_ascii=False), now, now),
            )
            conversation_id = int(cur.lastrowid)
        retained_message_ids = []
        for raw in payload.records or []:
            record = raw if isinstance(raw, dict) else raw.dict()
            role = str(record.get("role") or "")
            if role not in {"user", "ai"}:
                continue
            message_id = str(record.get("id") or "").strip()[:120]
            if not message_id:
                continue
            existing_message = conn.execute('SELECT conversation_id FROM ai_ask_messages WHERE id=?',(message_id,)).fetchone()
            if existing_message and existing_message[0] != conversation_id:
                raise HTTPException(409,'消息标识已被其他对话使用')
            ai_context.sync_message(conn,key,{**record,'id':message_id},context_case_id,bool(existing_message))
            retained_message_ids.append(message_id)
            case_link = record.get("caseLink") or {}
            case_id = int(case_link.get("caseId") or 0) or None
            research_question_id = int(record.get("researchQuestionId") or 0) or None
            conn.execute(
                """
                INSERT INTO ai_ask_messages
                (id, conversation_id, role, content, sources_json, cited_sources_json,
                 reasoning, is_reasoning_model, model, case_id, research_question_id,
                 strategy_version_id, strategy_version, strategy_decision_json, created_at_ms)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(id) DO UPDATE SET content=excluded.content,sources_json=excluded.sources_json,
                  cited_sources_json=excluded.cited_sources_json,reasoning=excluded.reasoning,
                  is_reasoning_model=excluded.is_reasoning_model,model=excluded.model,case_id=excluded.case_id,
                  research_question_id=excluded.research_question_id,strategy_version_id=excluded.strategy_version_id,
                  strategy_version=excluded.strategy_version,strategy_decision_json=excluded.strategy_decision_json
                """,
                (
                    message_id, conversation_id, role, str(record.get("content") or "")[:2_000_000],
                    json.dumps(record.get("sources"), ensure_ascii=False),
                    json.dumps(record.get("citedSources"), ensure_ascii=False),
                    str(record.get("reasoning") or "")[:2_000_000],
                    int(bool(record.get("isReasoningModel"))), str(record.get("model") or "")[:100],
                    case_id, research_question_id, int(record.get("strategyVersionId") or 0) or None,
                    str(record.get("strategyVersion") or "")[:100],
                    json.dumps(record.get("strategyDecision"), ensure_ascii=False),
                    int(record.get("ts") or 0),
                ),
            )
        for old_id, in conn.execute('SELECT id FROM ai_ask_messages WHERE conversation_id=?',(conversation_id,)).fetchall():
            if old_id not in set(retained_message_ids):
                conn.execute('DELETE FROM ai_ask_messages WHERE id=?',(old_id,))
        version = ai_context.finish_save(conn,key,retained_message_ids)
        conn.commit()
        if background_tasks is not None:
            background_tasks.add_task(ai_context.process_jobs,get_db)
        return {"success": True, "history_key": key, "conversation_id": conversation_id, "version":version}
    finally:
        conn.close()


@app.delete("/api/ai-ask/history")
def delete_ai_ask_history(history_key: str):
    key = _validate_ai_ask_history_key(history_key)
    conn = get_db()
    ai_context.delete_conversation(conn,key)
    conn.execute("DELETE FROM ai_ask_conversations WHERE history_key=?", (key,))
    conn.commit()
    conn.close()
    return {"success": True}


def _load_ai_ask_export(message_id: str) -> dict:
    """读取一条 AI 回答及其对应问题，作为本地导出的唯一数据源。"""
    clean_id = (message_id or "").strip()
    if not clean_id or len(clean_id) > 120:
        raise HTTPException(status_code=400, detail="问答记录标识无效")
    conn = get_db()
    answer = conn.execute(
        """
        SELECT m.*, c.context_json, cc.title AS case_title
        FROM ai_ask_messages m
        JOIN ai_ask_conversations c ON c.id=m.conversation_id
        LEFT JOIN case_manager_cases cc ON cc.id=m.case_id
        WHERE m.id=? AND m.role='ai'
        """,
        (clean_id,),
    ).fetchone()
    if not answer:
        conn.close()
        raise HTTPException(status_code=404, detail="未找到对应的 AI 回答")
    question = conn.execute(
        """
        SELECT content FROM ai_ask_messages
        WHERE conversation_id=? AND role='user' AND created_at_ms<=?
        ORDER BY created_at_ms DESC, id DESC LIMIT 1
        """,
        (answer["conversation_id"], answer["created_at_ms"]),
    ).fetchone()
    conn.close()
    if not (answer["content"] or "").strip():
        raise HTTPException(status_code=409, detail="该记录没有可导出的回答正文，请先重新生成")
    try:
        context = json.loads(answer["context_json"] or "null")
    except (TypeError, ValueError):
        context = None
    try:
        sources = json.loads(answer["sources_json"] or "null") or []
    except (TypeError, ValueError):
        sources = []
    try:
        cited_sources = json.loads(answer["cited_sources_json"] or "null") or []
    except (TypeError, ValueError):
        cited_sources = []
    return {
        "question": (question["content"] if question else "") or "未记录问题",
        "answer": answer["content"] or "",
        "reasoning": answer["reasoning"] or "",
        "model": answer["model"] or "",
        "context": context,
        "sources": cited_sources or sources,
        "case_title": answer["case_title"] or "",
        "created_at_ms": int(answer["created_at_ms"] or 0),
    }


def _ai_ask_context_label(context: Any) -> str:
    if not isinstance(context, dict):
        return "全部知识"
    kind = context.get("type")
    if kind == "article":
        return f"文章 · {context.get('title') or '未命名文章'}"
    if kind == "tag":
        return f"标签 · {context.get('tag') or '未命名标签'}"
    if kind == "category":
        return f"目录 · {context.get('catName') or '未命名目录'}"
    if kind == "domain":
        return f"领域 · {context.get('domain') or '未命名领域'}"
    if kind == "author":
        return f"作者 · {context.get('author') or '未知作者'}"
    if kind == "results":
        return "当前检索结果"
    if kind == "case_research":
        return "案件研究 · 案件资料问答"
    return "全部知识"


def _ai_ask_source_lines(items: list) -> list[str]:
    result = []
    seen = set()
    for item in items or []:
        if not isinstance(item, dict):
            continue
        title = str(item.get("title") or item.get("name") or item.get("source") or "来源").strip()
        url = str(item.get("url") or item.get("source_url") or "").strip()
        excerpt = str(item.get("excerpt") or item.get("quote") or "").strip()
        value = f"{title}：{url}" if url else title
        if excerpt:
            value += f" — {excerpt}"
        if value and value not in seen:
            seen.add(value)
            result.append(value)
    return result


def _build_ai_ask_export_markdown(data: dict) -> str:
    created = ""
    if data.get("created_at_ms"):
        created = datetime.datetime.fromtimestamp(data["created_at_ms"] / 1000).strftime("%Y-%m-%d %H:%M")
    metadata = [
        f"- 知识范围：{_ai_ask_context_label(data.get('context'))}",
        f"- AI 模型：{data.get('model') or '未记录'}",
    ]
    if created:
        metadata.append(f"- 生成时间：{created}")
    if data.get("case_title"):
        metadata.append(f"- 关联案件：{data['case_title']}")
    sections = [
        "# 法律操作系统 AI增强",
        "\n".join(metadata),
        "## 问题\n\n" + data["question"].strip(),
        "## 回答\n\n" + data["answer"].strip(),
    ]
    source_lines = _ai_ask_source_lines(data.get("sources") or [])
    if source_lines:
        sections.append("## 回答来源\n\n" + "\n".join(f"- {line}" for line in source_lines))
    safe_trace = _safe_research_trace_text(data.get("reasoning"))
    if safe_trace:
        sections.append("## 检索与核验记录\n\n" + safe_trace)
    sections.append("---\n\n由法律操作系统导出。AI 生成内容可能存在错误，请核实重要信息。")
    return "\n\n".join(sections).strip() + "\n"


def _safe_research_trace_text(value: Any) -> str:
    """只导出可审计的检索步骤，不导出模型 reasoning_content / 思维链。"""
    lines = []
    for raw_line in str(value or "").splitlines():
        line = raw_line.strip()
        if re.match(r"^（第\s*\d+\s*步）", line):
            lines.append(line)
    return "\n".join(lines)


def _utf8_bom_markdown_bytes(markdown: str) -> bytes:
    """为本地 Markdown 下载显式写入 UTF-8 BOM，避免系统默认编码误判中文。"""
    return ("\ufeff" + str(markdown or "")).encode("utf-8")


def _add_ai_export_inline_markdown(
    paragraph,
    text: str,
    *,
    muted: bool = False,
    font_name: str = "Microsoft YaHei",
) -> None:
    """渲染常用 Markdown 行内强调与链接，保持 Word 内容可编辑。"""
    from docx.shared import RGBColor
    from docx.oxml.ns import qn

    def apply_export_font(run) -> None:
        run.font.name = font_name
        fonts = run._element.get_or_add_rPr().rFonts
        fonts.set(qn("w:ascii"), font_name)
        fonts.set(qn("w:hAnsi"), font_name)
        fonts.set(qn("w:eastAsia"), font_name)

    pattern = re.compile(r'(\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))')
    cursor = 0
    for match in pattern.finditer(text or ""):
        if match.start() > cursor:
            run = paragraph.add_run(text[cursor:match.start()])
            apply_export_font(run)
            if muted:
                run.font.color.rgb = RGBColor(100, 100, 100)
        token = match.group(0)
        if token.startswith("**"):
            run = paragraph.add_run(token[2:-2])
            apply_export_font(run)
            run.bold = True
        else:
            link = re.match(r'\[([^\]]+)\]\(([^)]+)\)', token)
            label, url = link.groups() if link else (token, "")
            run = paragraph.add_run(f"{label}（{url}）" if url else label)
            apply_export_font(run)
            run.font.color.rgb = RGBColor(31, 78, 121)
            run.underline = True
        cursor = match.end()
    if cursor < len(text or ""):
        run = paragraph.add_run(text[cursor:])
        apply_export_font(run)
        if muted:
            run.font.color.rgb = RGBColor(100, 100, 100)


