_WORD_EXPORT_LAYOUTS_PREFERENCE_KEY = "ai_word_export_layouts"
_WORD_EXPORT_BUILTIN_NAMES_PREFERENCE_KEY = "ai_word_export_builtin_names"
_WORD_EXPORT_NUMERIC_RULES = {
    "body_size": (8.0, 36.0), "heading1_size": (8.0, 48.0),
    "heading2_size": (8.0, 42.0), "title_size": (8.0, 54.0),
    "line_spacing": (10.0, 72.0), "body_before": (0.0, 72.0), "body_after": (0.0, 72.0),
    "heading1_before": (0.0, 72.0), "heading1_after": (0.0, 72.0),
    "heading2_before": (0.0, 72.0), "heading2_after": (0.0, 72.0),
    "first_line_chars": (0.0, 10.0),
}


def _load_custom_word_layouts() -> list[dict]:
    conn = get_db()
    row = conn.execute(
        "SELECT value_json FROM app_preferences WHERE preference_key=?",
        (_WORD_EXPORT_LAYOUTS_PREFERENCE_KEY,),
    ).fetchone()
    conn.close()
    if not row:
        return []
    try:
        layouts = json.loads(row["value_json"] or "[]")
    except (TypeError, json.JSONDecodeError):
        return []
    return layouts if isinstance(layouts, list) else []


def _save_custom_word_layouts(layouts: list[dict]) -> None:
    now = datetime.datetime.now().isoformat()
    conn = get_db()
    conn.execute(
        """INSERT INTO app_preferences (preference_key, value_json, updated_at)
           VALUES (?, ?, ?)
           ON CONFLICT(preference_key) DO UPDATE SET
             value_json=excluded.value_json, updated_at=excluded.updated_at""",
        (_WORD_EXPORT_LAYOUTS_PREFERENCE_KEY, json.dumps(layouts, ensure_ascii=False), now),
    )
    conn.commit()
    conn.close()


def _load_builtin_word_layout_names() -> dict[str, str]:
    conn = get_db()
    row = conn.execute(
        "SELECT value_json FROM app_preferences WHERE preference_key=?",
        (_WORD_EXPORT_BUILTIN_NAMES_PREFERENCE_KEY,),
    ).fetchone()
    conn.close()
    if not row:
        return {}
    try:
        names = json.loads(row["value_json"] or "{}")
    except (TypeError, json.JSONDecodeError):
        return {}
    return {
        key: str(value).strip()[:40]
        for key, value in names.items()
        if key in _AI_ASK_WORD_LAYOUTS and str(value).strip()
    } if isinstance(names, dict) else {}


def _save_builtin_word_layout_names(names: dict[str, str]) -> None:
    now = datetime.datetime.now().isoformat()
    conn = get_db()
    conn.execute(
        """INSERT INTO app_preferences (preference_key, value_json, updated_at)
           VALUES (?, ?, ?)
           ON CONFLICT(preference_key) DO UPDATE SET
             value_json=excluded.value_json, updated_at=excluded.updated_at""",
        (_WORD_EXPORT_BUILTIN_NAMES_PREFERENCE_KEY, json.dumps(names, ensure_ascii=False), now),
    )
    conn.commit()
    conn.close()


def _validated_custom_word_layout(value: dict, *, layout_id: str = "") -> dict:
    if not isinstance(value, dict):
        raise HTTPException(status_code=400, detail="Word 格式参数不正确")
    name = str(value.get("name") or "").strip()
    if not name or len(name) > 40:
        raise HTTPException(status_code=400, detail="格式名称应为 1—40 个字符")
    result = {
        "id": layout_id or f"custom_{uuid.uuid4().hex[:12]}",
        "name": name,
        "description": str(value.get("description") or "自定义 Word 排版格式").strip()[:100],
    }
    for key in ("body_font", "heading1_font", "heading2_font", "title_font"):
        font = str(value.get(key) or "").strip()
        if not font or len(font) > 80:
            raise HTTPException(status_code=400, detail=f"{key} 字体名称不正确")
        result[key] = font
    for key, (minimum, maximum) in _WORD_EXPORT_NUMERIC_RULES.items():
        try:
            number = float(value.get(key))
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail=f"{key} 必须是数字")
        if not minimum <= number <= maximum:
            raise HTTPException(status_code=400, detail=f"{key} 超出允许范围")
        result[key] = number
    margins = value.get("margins_cm")
    page_size = value.get("page_size_cm")
    if not isinstance(margins, (list, tuple)) or len(margins) != 4:
        raise HTTPException(status_code=400, detail="页边距必须包含上、下、左、右四项")
    if not isinstance(page_size, (list, tuple)) or len(page_size) != 2:
        raise HTTPException(status_code=400, detail="页面尺寸必须包含宽度和高度")
    try:
        result["margins_cm"] = tuple(max(0.5, min(8.0, float(item))) for item in margins)
        result["page_size_cm"] = tuple(max(10.0, min(50.0, float(item))) for item in page_size)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="页面尺寸或页边距必须是数字")
    result["heading1_bold"] = bool(value.get("heading1_bold", True))
    result["heading2_bold"] = bool(value.get("heading2_bold", True))
    accent = value.get("accent", [0, 0, 0])
    if not isinstance(accent, (list, tuple)) or len(accent) != 3:
        accent = [0, 0, 0]
    result["accent"] = tuple(max(0, min(255, int(item))) for item in accent)
    return result


def _resolve_word_export_layout(layout_id: str) -> dict:
    if layout_id in _AI_ASK_WORD_LAYOUTS:
        return dict(_AI_ASK_WORD_LAYOUTS[layout_id])
    for item in _load_custom_word_layouts():
        if item.get("id") == layout_id:
            return _validated_custom_word_layout(item, layout_id=layout_id)
    raise HTTPException(status_code=400, detail="未找到所选 Word 排版格式")


@app.get("/api/preferences/word-export-layouts")
def get_word_export_layouts():
    return {
        "layouts": _load_custom_word_layouts(),
        "builtin_names": _load_builtin_word_layout_names(),
    }


@app.put("/api/preferences/word-export-layouts/builtin/{layout_id}/name")
async def rename_builtin_word_export_layout(layout_id: str, request: Request):
    if layout_id not in _AI_ASK_WORD_LAYOUTS:
        raise HTTPException(status_code=404, detail="系统预置格式不存在")
    body = await request.json()
    name = str(body.get("name") or "").strip() if isinstance(body, dict) else ""
    if not name or len(name) > 40:
        raise HTTPException(status_code=400, detail="格式名称应为 1—40 个字符")
    names = _load_builtin_word_layout_names()
    names[layout_id] = name
    _save_builtin_word_layout_names(names)
    return {"success": True, "layout_id": layout_id, "name": name}


@app.post("/api/preferences/word-export-layouts")
async def create_word_export_layout(request: Request):
    body = await request.json()
    layouts = _load_custom_word_layouts()
    if len(layouts) >= 50:
        raise HTTPException(status_code=400, detail="最多可保存 50 个自定义格式")
    layout = _validated_custom_word_layout(body)
    layouts.append(layout)
    _save_custom_word_layouts(layouts)
    return {"success": True, "layout": layout}


@app.put("/api/preferences/word-export-layouts/{layout_id}")
async def update_word_export_layout(layout_id: str, request: Request):
    if not layout_id.startswith("custom_"):
        raise HTTPException(status_code=400, detail="系统内置格式不可修改")
    body = await request.json()
    layouts = _load_custom_word_layouts()
    index = next((i for i, item in enumerate(layouts) if item.get("id") == layout_id), -1)
    if index < 0:
        raise HTTPException(status_code=404, detail="自定义格式不存在")
    layout = _validated_custom_word_layout(body, layout_id=layout_id)
    layouts[index] = layout
    _save_custom_word_layouts(layouts)
    return {"success": True, "layout": layout}


@app.delete("/api/preferences/word-export-layouts/{layout_id}")
def delete_word_export_layout(layout_id: str):
    layouts = _load_custom_word_layouts()
    retained = [item for item in layouts if item.get("id") != layout_id]
    if len(retained) == len(layouts):
        raise HTTPException(status_code=404, detail="自定义格式不存在")
    _save_custom_word_layouts(retained)
    return {"success": True}


def _generate_ai_ask_export_docx(data: dict, layout: str = "legal_standard") -> bytes:
    """按用户选择的受控排版预设生成正式、可编辑的法律问答 DOCX。"""
    from io import BytesIO
    from docx import Document
    from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_LINE_SPACING
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn
    from docx.shared import Cm, Pt, RGBColor

    preset = _resolve_word_export_layout(layout)

    doc = Document()
    section = doc.sections[0]
    page_width, page_height = preset.get("page_size_cm", (21.0, 29.7))
    section.page_width, section.page_height = Cm(page_width), Cm(page_height)
    top, bottom, left, right = preset["margins_cm"]
    section.top_margin, section.bottom_margin = Cm(top), Cm(bottom)
    section.left_margin, section.right_margin = Cm(left), Cm(right)
    section.header_distance = section.footer_distance = Cm(1.25)

    def set_font(run, size=11, color=None, bold=None, font_name=None):
        selected_font = font_name or preset["body_font"]
        run.font.name = selected_font
        run._element.get_or_add_rPr().rFonts.set(qn("w:ascii"), selected_font)
        run._element.get_or_add_rPr().rFonts.set(qn("w:hAnsi"), selected_font)
        run._element.get_or_add_rPr().rFonts.set(qn("w:eastAsia"), selected_font)
        run.font.size = Pt(size)
        if color:
            run.font.color.rgb = RGBColor(*color)
        if bold is not None:
            run.bold = bold

    def configure_style(style_name, font_name, size, *, bold=False, before=0, after=0, first_line=0):
        style = doc.styles[style_name]
        style.font.name = font_name
        style._element.get_or_add_rPr().rFonts.set(qn("w:ascii"), font_name)
        style._element.get_or_add_rPr().rFonts.set(qn("w:hAnsi"), font_name)
        style._element.get_or_add_rPr().rFonts.set(qn("w:eastAsia"), font_name)
        style.font.size = Pt(size)
        style.font.bold = bold
        style.font.color.rgb = RGBColor(*preset["accent"])
        style.paragraph_format.space_before = Pt(before)
        style.paragraph_format.space_after = Pt(after)
        style.paragraph_format.line_spacing_rule = WD_LINE_SPACING.EXACTLY
        style.paragraph_format.line_spacing = Pt(preset["line_spacing"])
        style.paragraph_format.first_line_indent = Pt(first_line)
        return style

    body_indent = preset["body_size"] * preset["first_line_chars"]
    configure_style(
        "Normal", preset["body_font"], preset["body_size"],
        before=preset.get("body_before", 0), after=preset["body_after"], first_line=body_indent,
    )
    configure_style(
        "Heading 1", preset["heading1_font"], preset["heading1_size"], bold=preset.get("heading1_bold", True),
        before=preset["heading1_before"], after=preset["heading1_after"],
    ).paragraph_format.keep_with_next = True
    configure_style(
        "Heading 2", preset["heading2_font"], preset["heading2_size"], bold=preset.get("heading2_bold", True),
        before=preset["heading2_before"], after=preset["heading2_after"],
    ).paragraph_format.keep_with_next = True
    configure_style(
        "Heading 3", preset["heading2_font"], preset["heading2_size"], bold=preset.get("heading2_bold", True),
        before=preset["heading2_before"], after=preset["heading2_after"],
    ).paragraph_format.keep_with_next = True
    for list_style in ("List Bullet", "List Number"):
        configure_style(
            list_style, preset["body_font"], preset["body_size"],
            after=preset["body_after"],
        )

    header = section.header.paragraphs[0]
    header.text = data.get("header_title") or "法律操作系统 · AI增强导出"
    header.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    for run in header.runs:
        set_font(run, 9, (110, 110, 110), font_name=preset["body_font"])
    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_font(footer.add_run("第 "), 8.5, (120, 120, 120), font_name=preset["body_font"])
    page_run = footer.add_run()
    field_begin = OxmlElement("w:fldChar"); field_begin.set(qn("w:fldCharType"), "begin")
    field_code = OxmlElement("w:instrText"); field_code.set(qn("xml:space"), "preserve"); field_code.text = " PAGE "
    field_separate = OxmlElement("w:fldChar"); field_separate.set(qn("w:fldCharType"), "separate")
    field_value = OxmlElement("w:t"); field_value.text = "1"
    field_end = OxmlElement("w:fldChar"); field_end.set(qn("w:fldCharType"), "end")
    page_run._r.extend((field_begin, field_code, field_separate, field_value, field_end))
    set_font(page_run, 8.5, (120, 120, 120), font_name=preset["body_font"])
    set_font(footer.add_run(" 页 · AI 生成内容请核实"), 8.5, (120, 120, 120), font_name=preset["body_font"])

    title = doc.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    title.paragraph_format.space_after = Pt(preset["heading1_after"])
    set_font(
        title.add_run(data.get("document_title") or "法律操作系统 AI增强"),
        preset["title_size"], preset["accent"], True, preset["title_font"],
    )
    subtitle = doc.add_paragraph()
    subtitle.alignment = WD_ALIGN_PARAGRAPH.CENTER
    subtitle.paragraph_format.space_after = Pt(preset["heading1_after"])
    context_label = _ai_ask_context_label(data.get("context"))
    meta = f"知识范围：{context_label}    AI 模型：{data.get('model') or '未记录'}"
    if data.get("case_title"):
        meta += f"    关联案件：{data['case_title']}"
    set_font(subtitle.add_run(meta), 9.5, (100, 100, 100), font_name=preset["body_font"])

    def add_markdown_block(markdown: str, *, reasoning: bool = False):
        for raw_line in (markdown or "").splitlines():
            line = raw_line.strip()
            if not line or re.fullmatch(r'-{3,}', line):
                continue
            if line.startswith("### "):
                p = doc.add_paragraph(style="Heading 3")
                _add_ai_export_inline_markdown(p, line[4:], font_name=preset["heading2_font"])
            elif line.startswith("## "):
                p = doc.add_paragraph(style="Heading 2")
                _add_ai_export_inline_markdown(p, line[3:], font_name=preset["heading2_font"])
            elif line.startswith("# "):
                p = doc.add_paragraph(style="Heading 1")
                _add_ai_export_inline_markdown(p, line[2:], font_name=preset["heading1_font"])
            elif re.match(r'^[-*•]\s+', line):
                p = doc.add_paragraph(style="List Bullet")
                p.paragraph_format.left_indent = Pt(preset["body_size"] * 2)
                p.paragraph_format.first_line_indent = Pt(-preset["body_size"])
                _add_ai_export_inline_markdown(p, re.sub(r'^[-*•]\s+', '', line), muted=reasoning, font_name=preset["body_font"])
            elif re.match(r'^\d+[.、]\s*', line):
                p = doc.add_paragraph(style="List Number")
                p.paragraph_format.left_indent = Pt(preset["body_size"] * 2)
                p.paragraph_format.first_line_indent = Pt(-preset["body_size"])
                _add_ai_export_inline_markdown(p, re.sub(r'^\d+[.、]\s*', '', line), muted=reasoning, font_name=preset["body_font"])
            else:
                p = doc.add_paragraph()
                _add_ai_export_inline_markdown(p, line.lstrip('> ').strip(), muted=reasoning, font_name=preset["body_font"])

    if (data.get("question") or "").strip():
        doc.add_heading(data.get("question_heading") or "问题", level=1)
        add_markdown_block(data["question"])
    if data.get("answer_heading", "回答"):
        doc.add_heading(data.get("answer_heading") or "回答", level=1)
    add_markdown_block(data["answer"])
    source_lines = _ai_ask_source_lines(data.get("sources") or [])
    if source_lines:
        doc.add_heading("回答来源", level=1)
        for line in source_lines:
            p = doc.add_paragraph(style="List Bullet")
            p.paragraph_format.left_indent = Pt(preset["body_size"] * 2)
            p.paragraph_format.first_line_indent = Pt(-preset["body_size"])
            _add_ai_export_inline_markdown(p, line, font_name=preset["body_font"])
    safe_trace = _safe_research_trace_text(data.get("reasoning"))
    if safe_trace:
        doc.add_heading("检索与核验记录", level=1)
        add_markdown_block(safe_trace, reasoning=True)

    buffer = BytesIO()
    doc.save(buffer)
    return buffer.getvalue()


@app.get("/api/ai-ask/messages/{message_id}/export")
def export_ai_ask_message(
    message_id: str,
    file_format: str = Query("md", alias="format"),
    layout: str = Query("legal_standard"),
    artifact_index: Optional[int] = Query(None, ge=0, le=7),
):
    """将单条问答直接下载为 Markdown 或 Word 文档。"""
    from fastapi.responses import StreamingResponse
    data = _load_ai_ask_export(message_id)
    fmt = (file_format or "md").strip().lower()
    if isinstance(artifact_index, int):
        from .ai_artifacts import extract_artifacts, FORMATS
        artifacts = extract_artifacts(data["answer"])
        if artifact_index >= len(artifacts):
            raise HTTPException(status_code=404, detail="未找到对应的生成文件，请重新生成")
        artifact = artifacts[artifact_index]
        if fmt != artifact["format"] and not (fmt == "docx" and artifact["format"] in {"md", "txt"}):
            raise HTTPException(status_code=400, detail="文件格式与生成内容不匹配")
        filename = artifact["filename"]
        if fmt == "docx":
            filename = filename.rsplit(".", 1)[0] + ".docx"
            content = _generate_ai_ask_export_docx({**data, "answer": artifact["content"]}, layout=layout)
            media_type = "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
        else:
            content = artifact["content"].encode("utf-8")
            media_type = FORMATS[fmt]
        return Response(content=content, media_type=media_type, headers={
            "Content-Disposition": f"attachment; filename*=UTF-8''{quote(filename)}",
            "X-Content-Type-Options": "nosniff",
        })
    if fmt not in {"md", "docx"}:
        raise HTTPException(status_code=400, detail="仅支持 md 和 docx 格式")
    stem = re.sub(r'[\\/:*?"<>|\r\n]+', "_", data["question"]).strip(" ._")[:48] or "AI法律问答"
    filename = f"{stem}.{fmt}"
    headers = {"Content-Disposition": f"attachment; filename*=UTF-8''{quote(filename)}"}
    if fmt == "md":
        return Response(
            content=_utf8_bom_markdown_bytes(_build_ai_ask_export_markdown(data)),
            media_type="text/markdown",
            headers=headers,
        )
    return StreamingResponse(
        BytesIO(_generate_ai_ask_export_docx(data, layout=layout)),
        media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        headers=headers,
    )


