@app.post("/api/case-research/cases/{case_id}/questions/import")
def import_question_to_case_research(case_id: int, payload: LinkedAskQuestionPayload):
    """把知识库 AI增强关联到案件研究；source_ref 保证重复点击不会产生副本。"""
    question = (payload.question or "").strip()
    answer = (payload.answer or "").strip()
    if not question or not answer:
        raise HTTPException(status_code=400, detail="问题和回答不能为空")
    now = datetime.datetime.now().isoformat()
    created_at = (payload.created_at or "").strip() or now
    source_ref = (payload.source_ref or "").strip()[:160]
    conn = get_db()
    project_id = _ensure_case_research_project(conn, case_id)
    existing = None
    if source_ref:
        existing = conn.execute(
            "SELECT id FROM research_project_questions WHERE project_id=? AND source_ref=?",
            (project_id, source_ref),
        ).fetchone()
    if existing:
        question_id = int(existing["id"])
    else:
        cur = conn.execute(
            """
            INSERT INTO research_project_questions
            (project_id, question, answer, model, sources_json, cited_sources_json,
             reasoning, is_reasoning_model, source_type, source_ref, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'knowledge_ai_ask', ?, ?)
            """,
            (
                project_id,
                question,
                answer,
                (payload.model or "").strip(),
                json.dumps(payload.sources or [], ensure_ascii=False),
                json.dumps(payload.cited_sources or [], ensure_ascii=False),
                payload.reasoning or "",
                int(bool(payload.is_reasoning_model)),
                source_ref,
                created_at,
            ),
        )
        question_id = int(cur.lastrowid)
        conn.execute("UPDATE research_projects SET updated_at=? WHERE id=?", (now, project_id))
    conn.commit()
    conn.close()
    return {
        "success": True,
        "case_id": case_id,
        "project_id": project_id,
        "question_id": question_id,
        "already_linked": bool(existing),
    }


def _save_timeline_entry(table: str, project_id: int, payload: CaseTimelineEntryPayload, entry_id: int = 0, resource_edit=None) -> dict:
    title = (payload.title or "").strip()
    content = (payload.content or "").strip()
    happened_at = (payload.happened_at or "").strip()
    if not content:
        raise HTTPException(status_code=400, detail="内容不能为空")
    if table not in {"research_case_ledgers", "research_case_memo_entries"}:
        raise HTTPException(status_code=400, detail="时间轴类型不正确")
    now = datetime.datetime.now().isoformat()
    from contextlib import closing
    with closing(get_db()) as conn, conn:
        conn.execute("BEGIN IMMEDIATE")
        _require_project(conn, project_id)
        if entry_id:
            row = conn.execute(f"SELECT * FROM {table} WHERE id=?", (entry_id,)).fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="记录不存在")
            if resource_edit is not None and row['updated_at'] != resource_edit[1]:
                raise HTTPException(status_code=409, detail="记录已变化，请重新打开后编辑")
            conn.execute(
                f"UPDATE {table} SET title=?, content=?, happened_at=?, updated_at=? WHERE id=?",
                (title, content, happened_at, now, entry_id),
            )
            result_id = entry_id
            created_at = row["created_at"]
        else:
            cur = conn.execute(
                f"""
                INSERT INTO {table} (project_id, title, content, happened_at, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (project_id, title, content, happened_at, now, now),
            )
            result_id = cur.lastrowid
            created_at = now
        if resource_edit is not None:
            conn.execute(f"UPDATE {table} SET resources_json=? WHERE id=?", (resource_edit[0], result_id))
        conn.execute("UPDATE research_projects SET updated_at=? WHERE id=?", (now, project_id))
    return {
        "success": True,
        "id": result_id,
        "project_id": project_id,
        "title": title,
        "content": content,
        "happened_at": happened_at,
        "created_at": created_at,
        "updated_at": now,
    }


def _delete_timeline_entry(table: str, entry_id: int) -> dict:
    if table not in {"research_case_ledgers", "research_case_memo_entries"}:
        raise HTTPException(status_code=400, detail="时间轴类型不正确")
    conn = get_db()
    conn.execute(f"DELETE FROM {table} WHERE id=?", (entry_id,))
    conn.commit()
    conn.close()
    return {"success": True}


