def _load_research_question_exports(*, project_id: int = 0, question_id: int = 0) -> tuple[dict, list]:
    """读取案件资料问答；AI增强页关联进来的记录与原生记录使用同一张表。"""
    conn = get_db()
    if question_id:
        question_row = conn.execute(
            "SELECT * FROM research_project_questions WHERE id=?", (question_id,)
        ).fetchone()
        if not question_row:
            conn.close()
            raise HTTPException(status_code=404, detail="案件资料问答记录不存在")
        project_id = int(question_row["project_id"])
    project_row = conn.execute(
        """
        SELECT rp.*, cc.title AS case_title
        FROM research_projects rp
        LEFT JOIN case_manager_cases cc ON cc.id=rp.case_id
        WHERE rp.id=?
        """,
        (project_id,),
    ).fetchone()
    if not project_row:
        conn.close()
        raise HTTPException(status_code=404, detail="案件研究不存在")
    if question_id:
        rows = [question_row]
    else:
        rows = conn.execute(
            "SELECT * FROM research_project_questions WHERE project_id=? ORDER BY created_at ASC, id ASC",
            (project_id,),
        ).fetchall()
    conn.close()
    records = []
    for row in rows:
        item = dict(row)
        try:
            sources = json.loads(item.get("cited_sources_json") or "[]") or []
        except (TypeError, ValueError):
            sources = []
        if not sources:
            try:
                sources = json.loads(item.get("sources_json") or "[]") or []
            except (TypeError, ValueError):
                sources = []
        item["sources"] = sources
        records.append(item)
    if not records:
        raise HTTPException(status_code=404, detail="该案件尚无可导出的问答记录")
    return dict(project_row), records


def _build_research_questions_export_markdown(project: dict, records: list) -> str:
    case_title = project.get("case_title") or project.get("name") or "未命名案件"
    lines = [
        "# 案件资料问答",
        "",
        f"- 案件：{case_title}",
        f"- 研究项目：{project.get('name') or '未命名项目'}",
        f"- 导出时间：{datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}",
        f"- 记录数量：{len(records)}",
    ]
    for index, record in enumerate(records, 1):
        lines.extend([
            "", "---", "",
            f"## {index}. {str(record.get('question') or '未命名问题').strip()}",
            "",
            f"- 生成时间：{record.get('created_at') or '未记录'}",
            f"- AI 模型：{record.get('model') or '未记录'}",
            "", "### 回答", "",
            str(record.get("answer") or "暂无回答内容").strip(),
        ])
        source_lines = _ai_ask_source_lines(record.get("sources") or [])
        if source_lines:
            lines.extend(["", "### 回答来源", ""])
            lines.extend(f"- {line}" for line in source_lines)
        safe_trace = _safe_research_trace_text(record.get("reasoning"))
        if safe_trace:
            lines.extend([
                "", "### 检索与核验记录", "",
                safe_trace,
            ])
    lines.extend(["", "---", "", "由法律操作系统导出。AI 生成内容可能存在错误，请核实重要信息。"])
    return "\n".join(lines).strip() + "\n"


def _research_questions_docx(project: dict, records: list, layout: str = "legal_standard") -> bytes:
    markdown = _build_research_questions_export_markdown(project, records)
    # 主标题和元数据由 Word 模板负责，正文从首条问答开始，避免重复标题。
    body = re.sub(r"^# 案件资料问答\s+.*?(?=\n---\n)", "", markdown, count=1, flags=re.DOTALL).strip()
    return _generate_ai_ask_export_docx({
        "document_title": "案件资料问答",
        "header_title": "法律操作系统 · 案件研究",
        "question": "",
        "answer_heading": "",
        "answer": body,
        "reasoning": "",
        "model": f"共 {len(records)} 条记录",
        "context": {"type": "case_research"},
        "case_title": project.get("case_title") or project.get("name") or "",
        "sources": [],
    }, layout=layout)


def _research_question_export_response(project: dict, records: list, file_format: str, layout: str = "legal_standard"):
    from fastapi.responses import StreamingResponse

    fmt = (file_format or "md").strip().lower()
    if fmt not in {"md", "docx"}:
        raise HTTPException(status_code=400, detail="仅支持 md 和 docx 格式")
    case_title = project.get("case_title") or project.get("name") or "案件"
    suffix = "全部案件资料问答" if len(records) > 1 else str(records[0].get("question") or "案件资料问答")[:48]
    filename = f"{_safe_export_filename(case_title, '案件')}-{_safe_export_filename(suffix, '案件资料问答')}.{fmt}"
    headers = {"Content-Disposition": f"attachment; filename*=UTF-8''{quote(filename)}"}
    if fmt == "md":
        return Response(
            content=_utf8_bom_markdown_bytes(_build_research_questions_export_markdown(project, records)),
            media_type="text/markdown",
            headers=headers,
        )
    return StreamingResponse(
        BytesIO(_research_questions_docx(project, records, layout=layout)),
        media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        headers=headers,
    )


