def _fetch_watch_candidates(source_names: list, keywords: list, domains: list) -> list:
    source_pool = DEFAULT_SOURCES
    if source_names:
        source_pool = [s for s in source_pool if s["name"] in source_names or s["id"] in source_names]
    terms = [str(x).strip() for x in (keywords or []) + (domains or []) if str(x).strip()]
    candidates = []
    for src in source_pool[:8]:
        try:
            resp = requests.get(src["url"], headers=HEADERS, timeout=12)
            resp.encoding = resp.apparent_encoding or "utf-8"
            soup = BeautifulSoup(resp.text, "html.parser")
            for a in soup.find_all("a", href=True)[:120]:
                title = re.sub(r'\s+', ' ', a.get_text(" ", strip=True))
                if len(title) < 6:
                    continue
                if terms and not any(t in title for t in terms):
                    continue
                url = urljoin(src["url"], a["href"])
                if not url.startswith("http"):
                    continue
                candidates.append({
                    "title": title[:200],
                    "url": url,
                    "source_name": src["name"],
                    "published_at": "",
                    "summary": title,
                    "domain": next((d for d in domains if d in title), domains[0] if domains else ""),
                    "body_text": "",
                })
        except Exception as e:
            print(f"[authority-watch] source failed {src.get('name')}: {e}")
    seen, unique = set(), []
    for c in candidates:
        key = c["url"].rstrip("/")
        if key not in seen:
            seen.add(key)
            unique.append(c)
    return unique[:50]


