_NATIONAL_LAW_SYSTEM_TAGS = {
    "国家法律法规数据库", "有效", "尚未生效", "已修改", "已废止", "效力未知",
    "宪法", "法律", "行政法规", "监察法规", "司法解释", "地方性法规",
}


def _national_law_tags(existing: Any, detail: dict) -> list:
    try:
        tags = json.loads(existing or "[]") if isinstance(existing, str) else list(existing or [])
    except Exception:
        tags = []
    tags = [str(tag) for tag in tags if str(tag) not in _NATIONAL_LAW_SYSTEM_TAGS]
    for tag in ("国家法律法规数据库", detail.get("category"), detail.get("status_label")):
        if tag and tag not in tags:
            tags.append(tag)
    if not any(tag.startswith("作者:") for tag in tags):
        tags.append("作者:国家法律法规数据库")
    return tags


def _national_law_metadata_dict(row: Optional[sqlite3.Row]) -> dict:
    return dict(row) if row else {}


def _upsert_national_law_metadata(conn, article_id: int, detail: dict, content_hash: str = ""):
    now = datetime.datetime.now().isoformat()
    conn.execute(
        """INSERT INTO national_law_articles
           (article_id,bbbs,official_title,normalized_title,status_code,status_label,category,issuer,
            published_at,effective_at,official_content_hash,last_checked_at,created_at,updated_at)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)
           ON CONFLICT(article_id) DO UPDATE SET
             bbbs=excluded.bbbs, official_title=excluded.official_title,
             normalized_title=excluded.normalized_title, status_code=excluded.status_code,
             status_label=excluded.status_label, category=excluded.category, issuer=excluded.issuer,
             published_at=excluded.published_at, effective_at=excluded.effective_at,
             official_content_hash=CASE WHEN excluded.official_content_hash<>'' THEN excluded.official_content_hash ELSE national_law_articles.official_content_hash END,
             last_checked_at=excluded.last_checked_at, updated_at=excluded.updated_at""",
        (
            article_id, detail.get("bbbs"), detail.get("title") or detail.get("official_title") or "",
            detail.get("normalized_title") or normalize_national_law_title(detail.get("title")),
            detail.get("status_code"), detail.get("status_label") or "", detail.get("category") or "",
            detail.get("issuer") or "", detail.get("published_at") or "", detail.get("effective_at") or "",
            content_hash or "", now, now, now,
        ),
    )


def _snapshot_national_law_article(conn, article_id: int, update_item_id: Optional[int] = None) -> int:
    article = conn.execute("SELECT * FROM articles WHERE id=?", (article_id,)).fetchone()
    if not article:
        raise HTTPException(status_code=404, detail="待更新文章不存在")
    metadata = conn.execute("SELECT * FROM national_law_articles WHERE article_id=?", (article_id,)).fetchone()
    now = datetime.datetime.now().isoformat()
    cur = conn.execute(
        """INSERT INTO national_law_update_snapshots
           (update_item_id,article_id,title,content,summary,domains,tags,source_type,source_url,
            source_filename,source_localpath,source_hash,metadata_json,created_at)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            update_item_id, article_id, article["title"], article["content"], article["summary"],
            article["domains"], article["tags"], article["source_type"], article["source_url"],
            article["source_filename"], article["source_localpath"], article["source_hash"],
            json.dumps(_national_law_metadata_dict(metadata), ensure_ascii=False), now,
        ),
    )
    return cur.lastrowid


async def _load_official_law_document(
    bbbs: str, official_detail: Optional[dict] = None,
) -> tuple[dict, str, str]:
    if official_detail is None:
        detail, raw = await asyncio.gather(
            get_national_law_detail(bbbs),
            download_national_law_docx(bbbs),
        )
    else:
        detail = official_detail
        raw = await download_national_law_docx(bbbs)
    is_legacy_doc = raw.startswith(bytes.fromhex("d0cf11e0a1b11ae1"))
    with tempfile.TemporaryDirectory(prefix="national-law-word-") as temp_dir:
        temp_root = Path(temp_dir)
        source_path = temp_root / ("official.doc" if is_legacy_doc else "official.docx")
        source_path.write_bytes(raw)
        parse_path = source_path

        if is_legacy_doc:
            # 部分较早法规的官方文件仍是 Word 97-2003 .doc。python-docx 只能
            # 读取 .docx，因此先用系统自带转换器转为 OOXML；macOS 优先使用
            # textutil，其他环境可使用已安装的 LibreOffice/soffice。
            converted_path = temp_root / "official.docx"
            commands = (
                ["textutil", "-convert", "docx", "-output", str(converted_path), str(source_path)],
                ["soffice", "--headless", "--convert-to", "docx", "--outdir", str(temp_root), str(source_path)],
            )
            if sys.platform == 'win32':
                # The bootstrap supplies an isolated converter; do not require a
                # second global Office installation or use its shared profile.
                converter = os.environ.get('LEGAL_KB_SOFFICE') or 'soffice'
                commands = ([converter,
                    f"-env:UserInstallation={(temp_root / 'office-profile').resolve().as_uri()}",
                    "--headless", "--convert-to", "docx", "--outdir", str(temp_root), str(source_path)],)
            conversion_errors = []
            for command in commands:
                try:
                    if converted_path.exists():
                        converted_path.unlink()
                    completed = subprocess.run(
                        command, capture_output=True, text=True, timeout=45, check=False,
                    )
                    if completed.returncode == 0 and converted_path.exists() and converted_path.stat().st_size > 100:
                        parse_path = converted_path
                        break
                    conversion_errors.append((completed.stderr or completed.stdout or command[0]).strip())
                except (FileNotFoundError, subprocess.SubprocessError, OSError) as exc:
                    conversion_errors.append(str(exc))
            else:
                detail_text = next((item for item in conversion_errors if item), "没有可用的 Word 转换器")
                raise NationalLawError(f"国家库旧版 Word 文件转换失败：{detail_text[:160]}")

        # 国家法律法规库提供的官方 Word 已有可用段落与排版：
        # 保留源格式为安全 HTML，不再复用通用文章的自动排版规则。
        parsed = parse_docx(str(parse_path), preserve_source_format=True)
    content = str(parsed.get("content") or "").strip()
    if len(content) < 20:
        raise NationalLawError("官方 Word 文件未解析出有效正文")
    return detail, content, compute_hash(content)


async def _write_national_law_article(
    bbbs: str,
    *,
    existing_article_id: Optional[int] = None,
    action: str = "new_version",
    update_item_id: Optional[int] = None,
    official_detail: Optional[dict] = None,
) -> dict:
    detail, content, content_hash = await _load_official_law_document(bbbs, official_detail)
    article_source_hash = compute_hash(content[:2000])
    title = detail.get("title") or "未命名法规"
    processing_text = html_to_processing_text(content)
    summary = extract_summary(processing_text)
    domains = classify_domains(processing_text + " " + title)
    source_url = detail.get("source_url") or national_law_detail_url(bbbs)
    filename = f"{title}_{detail.get('published_at') or '官方文本'}.docx"
    conn = get_db()
    try:
        already = conn.execute("SELECT article_id FROM national_law_articles WHERE bbbs=?", (bbbs,)).fetchone()
        if already and (not existing_article_id or already["article_id"] != existing_article_id):
            return {"success": True, "duplicate": True, "article_id": already["article_id"], "title": title}
        same_hash = conn.execute("SELECT id,title FROM articles WHERE source_hash=?", (article_source_hash,)).fetchone()
        if same_hash and (not existing_article_id or same_hash["id"] != existing_article_id):
            _upsert_national_law_metadata(conn, same_hash["id"], detail, content_hash)
            conn.commit()
            return {"success": True, "duplicate": True, "article_id": same_hash["id"], "title": same_hash["title"]}

        if existing_article_id and action == "replace":
            article = conn.execute("SELECT * FROM articles WHERE id=?", (existing_article_id,)).fetchone()
            if not article:
                raise HTTPException(status_code=404, detail="待更新文章不存在")
            snapshot_id = _snapshot_national_law_article(conn, existing_article_id, update_item_id)
            invalidated_claims = mark_article_claims_needs_review(
                conn, existing_article_id, "国家法律法规数据库版本已更新，需重新核验"
            )
            tags = _national_law_tags(article["tags"], detail)
            conn.execute(
                """UPDATE articles SET title=?,content=?,summary=?,domains=?,source_type='national_law',
                   source_url=?,source_filename=?,source_hash=?,tags=? WHERE id=?""",
                (
                    title, content, summary, json.dumps(domains, ensure_ascii=False), source_url, filename,
                    article_source_hash, json.dumps(tags, ensure_ascii=False), existing_article_id,
                ),
            )
            conn.execute("DELETE FROM national_law_articles WHERE bbbs=? AND article_id<>?", (bbbs, existing_article_id))
            _upsert_national_law_metadata(conn, existing_article_id, detail, content_hash)
            rebuild_article_paragraphs(conn, existing_article_id, content)
            conn.commit()
            knowledge_job_id = None
            if invalidated_claims or is_knowledge_article(
                {"title": title, "summary": summary, "domains": domains, "content": content}
            ):
                knowledge_job_id, _ = _enqueue_knowledge_job(existing_article_id, "national_law_update", force=True)
            return {
                "success": True, "article_id": existing_article_id, "title": title,
                "snapshot_id": snapshot_id, "knowledge_job_id": knowledge_job_id,
                "knowledge_claims_invalidated": invalidated_claims,
            }

        tags = _national_law_tags([], detail)
        article_id = save_article(
            title, content, summary, domains, "national_law", source_url=source_url,
            source_filename=filename, tags=tags, check_duplicate=True,
        )
        conn.close()
        conn = get_db()
        _upsert_national_law_metadata(conn, article_id, detail, content_hash)
        conn.commit()
        if is_meaningful_article_text(processing_text, min_len=80):
            asyncio.create_task(
                _generate_and_store_ai_summary(article_id, title, processing_text, summary)
            )
        return {"success": True, "article_id": article_id, "title": title}
    finally:
        conn.close()


