@app.post("/api/national-laws/import")
async def import_national_law(payload: NationalLawImportPayload):
    action = payload.conflict_action if payload.conflict_action in {"replace", "new_version"} else "confirm"
    try:
        detail = await get_national_law_detail(payload.bbbs)
    except NationalLawError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    conn = get_db()
    try:
        bound = conn.execute("SELECT article_id FROM national_law_articles WHERE bbbs=?", (payload.bbbs,)).fetchone()
        if bound:
            return {"success": True, "duplicate": True, "article_id": bound["article_id"], "title": detail["title"]}
        normalized = detail.get("normalized_title") or normalize_national_law_title(detail.get("title"))
        rows = conn.execute("SELECT id,title FROM articles ORDER BY created_at DESC").fetchall()
        conflicts = [dict(row) for row in rows if normalize_national_law_title(row["title"]) == normalized]
    finally:
        conn.close()
    if action == "confirm" and conflicts:
        return {"success": False, "requires_confirmation": True, "law": detail, "conflicts": conflicts}
    existing_id = payload.article_id if action == "replace" else None
    if action == "replace" and not existing_id:
        raise HTTPException(status_code=400, detail="覆盖更新时必须指定文章")
    try:
        return await _write_national_law_article(
            payload.bbbs, existing_article_id=existing_id, action=action,
            official_detail=detail,
        )
    except NationalLawError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


_NATIONAL_LAW_TITLE_RE = re.compile(
    r"(中华人民共和国|最高人民法院关于|最高人民检察院关于|法典|条例|司法解释|实施细则|实施办法|暂行办法|管理办法|若干规定|的规定|的决定|规则|法律解释)"
)
_national_law_scan_tasks: Dict[int, asyncio.Task] = {}


def _finish_national_law_scan_task(scan_id: int, task: asyncio.Task):
    """Persist unexpected task failures so a refresh never leaves a scan stuck forever."""
    _national_law_scan_tasks.pop(scan_id, None)
    if task.cancelled():
        error = "检测任务已中断"
    else:
        try:
            error = str(task.exception() or "")
        except asyncio.CancelledError:
            error = "检测任务已中断"
    if not error:
        return
    try:
        with get_db() as conn:
            conn.execute(
                """UPDATE national_law_update_scans
                   SET status='failed',error=?,completed_at=?
                   WHERE id=? AND status IN ('queued','running')""",
                (error[:1000], datetime.datetime.now().isoformat(), scan_id),
            )
            conn.commit()
    except Exception:
        pass


def _scan_item_to_dict(row: sqlite3.Row) -> dict:
    item = dict(row)
    for key, default in (("candidates_json", []), ("detail_json", {})):
        public_key = key[:-5] if key.endswith("_json") else key
        try:
            item[public_key] = json.loads(item.pop(key) or json.dumps(default))
        except Exception:
            item[public_key] = default
    item["confirmed"] = bool(item.get("confirmed"))
    return item


def _refresh_scan_counts(conn, scan_id: int):
    counts = {row["status"]: row["n"] for row in conn.execute(
        "SELECT status,COUNT(*) n FROM national_law_update_items WHERE scan_id=? GROUP BY status", (scan_id,)
    ).fetchall()}
    conn.execute(
        """UPDATE national_law_update_scans SET
           pending_matches=?,updates_found=?,current_count=?,failed_count=? WHERE id=?""",
        (
            counts.get("pending_match", 0), counts.get("update_available", 0),
            counts.get("current", 0), counts.get("failed", 0) + counts.get("unmatched", 0), scan_id,
        ),
    )


async def _evaluate_bound_national_law(article: dict, metadata: dict) -> tuple[str, dict]:
    check = await check_national_law_update(
        metadata["bbbs"], metadata.get("official_title") or article["title"],
        known_status=metadata.get("status_code"),
    )
    target = check.get("preferred") if check.get("new_version_available") else check.get("current")
    target_bbbs = (target or {}).get("bbbs") or metadata["bbbs"]
    detail, official_content, official_hash = await _load_official_law_document(target_bbbs)
    local_hash = compute_hash(article.get("content") or "")
    changed = (
        check.get("status_changed") or check.get("new_version_available")
        or official_hash != local_hash
    )
    result = {
        "current": check.get("current"), "preferred": check.get("preferred"),
        "target": detail, "target_bbbs": target_bbbs,
        "status_changed": bool(check.get("status_changed")),
        "new_version_available": bool(check.get("new_version_available")),
        "content_changed": official_hash != local_hash,
        "official_content_hash": official_hash,
    }
    return ("update_available" if changed else "current"), result


async def _run_national_law_scan(scan_id: int):
    with get_db() as conn:
        scan = conn.execute("SELECT * FROM national_law_update_scans WHERE id=?", (scan_id,)).fetchone()
        if not scan:
            return
        mode = scan["mode"]
        conn.execute(
            "UPDATE national_law_update_scans SET status='running',started_at=?,error='' WHERE id=?",
            (datetime.datetime.now().isoformat(), scan_id),
        )
        if mode == "automatic":
            rows = conn.execute(
                """SELECT a.*,n.* FROM national_law_articles n JOIN articles a ON a.id=n.article_id
                   ORDER BY a.id"""
            ).fetchall()
        else:
            rows = conn.execute(
                """SELECT a.*,n.bbbs,n.official_title,n.status_code,n.status_label,n.category,n.issuer,
                          n.published_at,n.effective_at,n.official_content_hash,n.last_checked_at
                   FROM articles a LEFT JOIN national_law_articles n ON n.article_id=a.id
                   ORDER BY a.id"""
            ).fetchall()
            rows = [row for row in rows if row["bbbs"] or _NATIONAL_LAW_TITLE_RE.search(row["title"] or "")]
        conn.execute("UPDATE national_law_update_scans SET total=? WHERE id=?", (len(rows), scan_id))
        conn.commit()

    for row in rows:
        article = dict(row)
        now = datetime.datetime.now().isoformat()
        item_status, candidates, detail_data, error, confirmed, matched_bbbs = "pending_match", [], {}, "", 0, ""
        try:
            if article.get("bbbs"):
                metadata = {key: article.get(key) for key in (
                    "bbbs", "official_title", "status_code", "status_label", "category", "issuer",
                    "published_at", "effective_at", "official_content_hash", "last_checked_at",
                )}
                item_status, detail_data = await _evaluate_bound_national_law(article, metadata)
                confirmed, matched_bbbs = 1, metadata["bbbs"]
                with get_db() as conn:
                    current = detail_data.get("current") or {}
                    _upsert_national_law_metadata(conn, article["id"], current, metadata.get("official_content_hash") or "")
                    conn.commit()
            else:
                found = await search_national_laws(article["title"], search_scope="title", exact=True, limit=8)
                candidates = found.get("results") or []
                item_status = "pending_match" if candidates else "unmatched"
        except Exception as exc:
            item_status, error = "failed", str(exc)[:500]
        with get_db() as conn:
            conn.execute(
                """INSERT OR REPLACE INTO national_law_update_items
                   (id,scan_id,article_id,status,local_title,matched_bbbs,candidates_json,detail_json,error,
                    confirmed,action,created_at,updated_at)
                   VALUES ((SELECT id FROM national_law_update_items WHERE scan_id=? AND article_id=?),?,?,?,?,?,?,?,?,?,?,
                           COALESCE((SELECT created_at FROM national_law_update_items WHERE scan_id=? AND article_id=?),?),?)""",
                (
                    scan_id, article["id"], scan_id, article["id"], item_status, article["title"], matched_bbbs,
                    json.dumps(candidates, ensure_ascii=False), json.dumps(detail_data, ensure_ascii=False), error,
                    confirmed, "replace", scan_id, article["id"], now, now,
                ),
            )
            conn.execute("UPDATE national_law_update_scans SET processed=processed+1 WHERE id=?", (scan_id,))
            _refresh_scan_counts(conn, scan_id)
            conn.commit()
    with get_db() as conn:
        _refresh_scan_counts(conn, scan_id)
        conn.execute(
            "UPDATE national_law_update_scans SET status='completed',completed_at=? WHERE id=?",
            (datetime.datetime.now().isoformat(), scan_id),
        )
        conn.commit()


@app.post("/api/national-laws/update-scans")
async def create_national_law_update_scan():
    with get_db() as conn:
        running = conn.execute(
            "SELECT id FROM national_law_update_scans WHERE status IN ('queued','running') ORDER BY id DESC LIMIT 1"
        ).fetchone()
        if running:
            return {"scan_id": running["id"], "status": "running", "reused": True}
        now = datetime.datetime.now().isoformat()
        cur = conn.execute(
            "INSERT INTO national_law_update_scans(mode,status,created_at) VALUES ('manual','queued',?)", (now,)
        )
        conn.commit()
        scan_id = cur.lastrowid
    task = asyncio.create_task(_run_national_law_scan(scan_id))
    _national_law_scan_tasks[scan_id] = task
    task.add_done_callback(lambda done: _finish_national_law_scan_task(scan_id, done))
    return {"scan_id": scan_id, "status": "queued"}


@app.get("/api/national-laws/update-scans/latest")
def get_latest_national_law_update_scan():
    """Return the newest persisted manual or automatic scan for refresh-safe reminders."""
    with get_db() as conn:
        scan = conn.execute(
            "SELECT * FROM national_law_update_scans ORDER BY id DESC LIMIT 1"
        ).fetchone()
        if not scan:
            return {"scan": None, "items": []}
        items = conn.execute(
            "SELECT * FROM national_law_update_items WHERE scan_id=? ORDER BY id", (scan["id"],)
        ).fetchall()
    return {"scan": dict(scan), "items": [_scan_item_to_dict(row) for row in items]}


