@app.post("/api/national-laws/update-scans/{scan_id}/confirm-matches")
async def confirm_national_law_matches(scan_id: int, payload: NationalLawConfirmPayload):
    results = []
    for choice in payload.items:
        item_id, bbbs = int(choice.get("item_id") or 0), str(choice.get("bbbs") or "").strip()
        if not item_id or not bbbs:
            continue
        with get_db() as conn:
            item = conn.execute(
                "SELECT * FROM national_law_update_items WHERE id=? AND scan_id=?", (item_id, scan_id)
            ).fetchone()
            article = conn.execute("SELECT * FROM articles WHERE id=?", (item["article_id"],)).fetchone() if item else None
        if not item or not article:
            results.append({"item_id": item_id, "success": False, "error": "检测项目不存在"})
            continue
        try:
            detail = await get_national_law_detail(bbbs)
            with get_db() as conn:
                conflict = conn.execute("SELECT article_id FROM national_law_articles WHERE bbbs=?", (bbbs,)).fetchone()
                if conflict and conflict["article_id"] != article["id"]:
                    raise ValueError(f"该官方法规已绑定文章 #{conflict['article_id']}")
                _upsert_national_law_metadata(conn, article["id"], detail, "")
                conn.commit()
            status, detail_data = await _evaluate_bound_national_law(dict(article), {
                **detail, "official_title": detail.get("title"), "official_content_hash": "",
            })
            with get_db() as conn:
                conn.execute(
                    """UPDATE national_law_update_items SET status=?,matched_bbbs=?,detail_json=?,error='',
                       confirmed=1,updated_at=? WHERE id=?""",
                    (status, bbbs, json.dumps(detail_data, ensure_ascii=False), datetime.datetime.now().isoformat(), item_id),
                )
                _refresh_scan_counts(conn, scan_id)
                conn.commit()
            results.append({"item_id": item_id, "success": True, "status": status})
        except Exception as exc:
            results.append({"item_id": item_id, "success": False, "error": str(exc)})
    return {"results": results}


@app.post("/api/national-laws/update-scans/{scan_id}/apply")
async def apply_national_law_updates(scan_id: int, payload: NationalLawApplyPayload):
    results = []
    for choice in payload.items:
        item_id = int(choice.get("item_id") or 0)
        action = "new_version" if choice.get("action") == "new_version" else "replace"
        with get_db() as conn:
            item = conn.execute(
                "SELECT * FROM national_law_update_items WHERE id=? AND scan_id=?", (item_id, scan_id)
            ).fetchone()
        if not item or not item["confirmed"]:
            results.append({"item_id": item_id, "success": False, "error": "请先确认官方对应关系"})
            continue
        try:
            detail_data = json.loads(item["detail_json"] or "{}")
            target_bbbs = detail_data.get("target_bbbs") or item["matched_bbbs"]
            result = await _write_national_law_article(
                target_bbbs, existing_article_id=item["article_id"] if action == "replace" else None,
                action=action, update_item_id=item_id,
            )
            with get_db() as conn:
                conn.execute(
                    """UPDATE national_law_update_items SET status='applied',action=?,applied_article_id=?,
                       updated_at=? WHERE id=?""",
                    (action, result.get("article_id"), datetime.datetime.now().isoformat(), item_id),
                )
                _refresh_scan_counts(conn, scan_id)
                conn.commit()
            results.append({"item_id": item_id, **result})
        except Exception as exc:
            results.append({"item_id": item_id, "success": False, "error": str(exc)})
    return {"results": results}


@app.post("/api/national-laws/updates/{update_id}/rollback")
async def rollback_national_law_update(update_id: int):
    with get_db() as conn:
        snapshot = conn.execute(
            """SELECT * FROM national_law_update_snapshots
               WHERE id=? OR update_item_id=? ORDER BY id DESC LIMIT 1""", (update_id, update_id)
        ).fetchone()
        if not snapshot:
            raise HTTPException(status_code=404, detail="未找到可撤销的法规更新")
        invalidated_claims = mark_article_claims_needs_review(
            conn, snapshot["article_id"], "法规更新已回滚，需按恢复版本重新核验"
        )
        conn.execute(
            """UPDATE articles SET title=?,content=?,summary=?,domains=?,tags=?,source_type=?,source_url=?,
               source_filename=?,source_localpath=?,source_hash=? WHERE id=?""",
            (
                snapshot["title"], snapshot["content"], snapshot["summary"], snapshot["domains"], snapshot["tags"],
                snapshot["source_type"], snapshot["source_url"], snapshot["source_filename"],
                snapshot["source_localpath"], snapshot["source_hash"], snapshot["article_id"],
            ),
        )
        metadata = json.loads(snapshot["metadata_json"] or "{}")
        conn.execute("DELETE FROM national_law_articles WHERE article_id=?", (snapshot["article_id"],))
        if metadata.get("bbbs"):
            _upsert_national_law_metadata(conn, snapshot["article_id"], {
                "bbbs": metadata["bbbs"], "title": metadata.get("official_title"),
                "normalized_title": metadata.get("normalized_title"), "status_code": metadata.get("status_code"),
                "status_label": metadata.get("status_label"), "category": metadata.get("category"),
                "issuer": metadata.get("issuer"), "published_at": metadata.get("published_at"),
                "effective_at": metadata.get("effective_at"),
            }, metadata.get("official_content_hash") or "")
        rebuild_article_paragraphs(conn, snapshot["article_id"], snapshot["content"])
        conn.execute(
            "UPDATE national_law_update_snapshots SET restored_at=? WHERE id=?",
            (datetime.datetime.now().isoformat(), snapshot["id"]),
        )
        conn.commit()
    knowledge_job_id, _ = _enqueue_knowledge_job(snapshot["article_id"], "national_law_rollback", force=True)
    return {
        "success": True, "article_id": snapshot["article_id"], "snapshot_id": snapshot["id"],
        "knowledge_job_id": knowledge_job_id, "knowledge_claims_invalidated": invalidated_claims,
    }


