@app.post("/api/case-library/search")
async def case_library_search(payload: CaseLibrarySearchPayload):
    """在法律操作系统内直接调用法随权威案例检索。"""
    query = str(payload.query or "").strip()
    if not query:
        raise HTTPException(status_code=400, detail="检索问题不能为空")
    try:
        research = await search_cases_structured(
            query, payload.top_k, verify_sources=payload.verify_sources
        )
        result = research["result"]
        now = datetime.datetime.now().isoformat()
        conn = get_db()
        memo_id = None
        try:
            if payload.project_id is not None and not conn.execute(
                "SELECT id FROM research_projects WHERE id=?", (payload.project_id,)
            ).fetchone():
                raise HTTPException(status_code=404, detail="研究项目不存在")
            cur = conn.execute(
                """INSERT INTO case_search_runs
                   (project_id,query,query_plan_json,cases_json,coverage_json,metrics_json,result_markdown,created_at)
                   VALUES (?,?,?,?,?,?,?,?)""",
                (
                    payload.project_id, query,
                    json.dumps(research["query_plan"], ensure_ascii=False),
                    json.dumps(research["cases"], ensure_ascii=False),
                    json.dumps(research["coverage"], ensure_ascii=False),
                    json.dumps(research["metrics"], ensure_ascii=False),
                    result, now,
                ),
            )
            run_id = cur.lastrowid
            if payload.project_id is not None:
                memo_title = f"案例检索：{research['query_plan']['core_issue'][:50]}"
                sources = [
                    {
                        "title": case.get("title", ""),
                        "case_number": case.get("case_number", ""),
                        "url": case.get("source_url", ""),
                        "verification": case.get("verification", {}),
                    }
                    for case in research["cases"]
                ]
                memo_cur = conn.execute(
                    """INSERT INTO research_memos
                       (project_id,title,question,markdown,sources_json,created_at,updated_at)
                       VALUES (?,?,?,?,?,?,?)""",
                    (
                        payload.project_id, memo_title, query, result,
                        json.dumps(sources, ensure_ascii=False), now, now,
                    ),
                )
                memo_id = memo_cur.lastrowid
                conn.execute(
                    "UPDATE research_projects SET updated_at=? WHERE id=?",
                    (now, payload.project_id),
                )
            conn.commit()
        finally:
            conn.close()
        official_fallback_used = GONGBAO_EXACT_HIT_MARKER in result
        return {
            "ok": True,
            "source": (
                "法随·案例库 MCP + 最高人民法院公报官网精确校验"
                if official_fallback_used else "法随·案例库 MCP"
            ),
            "source_url": ALURIS_MCP_URL,
            "official_fallback_used": official_fallback_used,
            "result": result,
            "query_plan": research["query_plan"],
            "cases": research["cases"],
            "coverage": research["coverage"],
            "metrics": research["metrics"],
            "retrieval_runs": research["retrieval_runs"],
            "errors": research["errors"],
            "run_id": run_id,
            "project_id": payload.project_id,
            "memo_id": memo_id,
        }
    except AlurisMCPError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc


@app.get("/api/case-library/search-runs")
def list_case_library_search_runs(limit: int = 50, project_id: Optional[int] = None):
    safe_limit = max(1, min(int(limit or 50), 200))
    conn = get_db()
    if project_id is None:
        rows = conn.execute(
            """SELECT id,project_id,query,coverage_json,metrics_json,created_at
               FROM case_search_runs ORDER BY id DESC LIMIT ?""",
            (safe_limit,),
        ).fetchall()
    else:
        rows = conn.execute(
            """SELECT id,project_id,query,coverage_json,metrics_json,created_at
               FROM case_search_runs WHERE project_id=? ORDER BY id DESC LIMIT ?""",
            (project_id, safe_limit),
        ).fetchall()
    conn.close()
    runs = []
    for row in rows:
        item = dict(row)
        item["coverage"] = json.loads(item.pop("coverage_json") or "{}")
        item["metrics"] = json.loads(item.pop("metrics_json") or "{}")
        runs.append(item)
    return {"runs": runs}


