def _normalise_ask_conversation_context(raw_context: Optional[str]) -> List[Dict[str, str]]:
    """校验并压缩前端传来的同一会话上下文，避免将历史直接当作提示词。"""
    managed_history = ai_context.current_history()
    if managed_history is not None:
        return managed_history
    if not raw_context:
        return []
    try:
        items = json.loads(raw_context)
    except (TypeError, ValueError, json.JSONDecodeError):
        return []
    if not isinstance(items, list):
        return []
    result: List[Dict[str, str]] = []
    remaining = 12000
    for item in items[-8:]:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip()
        content = str(item.get("content") or "").strip()
        if role not in {"user", "ai"} or not content or remaining <= 0:
            continue
        content = content[:min(4000, remaining)]
        remaining -= len(content)
        result.append({"role": role, "content": content})
    return result


def _looks_like_contextual_follow_up(question: str) -> bool:
    """仅对明显依赖上文的短句启用补全，避免改写本来独立的检索请求。"""
    text = str(question or "").strip()
    if not text or len(text) > 80:
        return False
    # 已经带有可识别企业全称或统一社会信用代码时，直接按原问题检索更可靠。
    if qcc_extract_company_name(text) != text or re.search(r"\b[0-9A-Z]{18}\b", text):
        return False
    return bool(re.search(
        r"^(?:那|这|该|其|它|上述|前述|这个|那个|此|继续|再)|"
        r"(?:什么时候|何时|为什么|为何|怎么|如何|哪里|哪年|多少|哪些|是否|能否|有没有|有无).{0,60}$",
        text,
    ))


_CONTEXT_ENTERPRISE_NAME_PATTERN = re.compile(
    r"(?:企业名称|公司名称|主体名称)[^：:\n]{0,20}[：:]\s*\*{0,2}\s*"
    r"([^\n*]{2,160}?(?:股份有限公司|有限责任公司|有限公司|合伙企业|个人独资企业|"
    r"个体工商户|便利店|超市|商店|店|集体经济组织|经济合作社|村民委员会|居民委员会))"
)


def _latest_enterprise_name_from_context(context: List[Dict[str, str]]) -> str:
    """优先读取上一轮已核验结果中的“企业名称”字段，避免续问再次猜主体。"""
    for item in reversed(context):
        if item.get("role") != "ai":
            continue
        matches = _CONTEXT_ENTERPRISE_NAME_PATTERN.findall(item.get("content") or "")
        if matches:
            return re.sub(r"\s+", "", matches[-1]).strip("：:；;，,。.")[:120]
    return ""


async def _resolve_follow_up_question(question: str, context: List[Dict[str, str]]) -> str:
    """把依赖上文的续问补为可独立检索的原意问题；失败时保留用户原话。"""
    if not context or not _looks_like_contextual_follow_up(question):
        return question
    # 企业名称字段是上一轮 MCP 已实际核验出的结果。对于名称变更这类高频续问，
    # 直接复用该字段，比让模型在一大段回答中猜测实体更快也更可审计。
    if re.search(r"什么时候改|何时改|改名|更名|曾用名|变更记录", question):
        company_name = _latest_enterprise_name_from_context(context)
        if company_name:
            return f"{company_name}{question}"
    transcript = "\n".join(
        f"{'用户' if item['role'] == 'user' else '助手'}：{item['content']}"
        for item in context
    )
    messages = [
        {
            "role": "system",
            "content": (
                "你是法律操作系统的续问解析器。根据同一对话上文，把用户当前的指代性短句补全为"
                "一条可独立检索的问题。只能使用上文已经出现的名称、案号、日期和事实；不得猜测、"
                "不得把不确定的相近主体当成同一主体，不得回答问题。若上文不足以唯一确定对象，原样返回当前问题。"
                "只输出一行补全后的问题，不要解释、引号或前缀。"
            ),
        },
        {"role": "user", "content": f"对话上文：\n{transcript}\n\n当前问题：{question}"},
    ]
    try:
        raw_result, _ = await asyncio.wait_for(
            _call_ai_with_fallback(DEFAULT_AI_MODEL, messages, temperature=0.0, max_tokens=220),
            timeout=10.0,
        )
        answer, _reasoning, _finish_reason = _extract_ai_choice(raw_result)
        resolved = str(answer or "").strip().strip('“”\"')
        if resolved and len(resolved) <= 300 and "\n" not in resolved:
            return resolved
    except Exception:
        pass
    return question


async def _plan_enterprise_mcp_query(question: str) -> Dict[str, str]:
    """将口语化企业查询压缩为 MCP 可执行的实体与意图，不参与最终法律回答。"""
    # 企业全称已在问题中出现时，正则提取比调用一次模型规划更快、更稳定。
    # 这类请求随后还要逐个调用企业/风险 MCP；把可确定的信息留在本地处理，
    # 可避免网关抖动拖慢整个问答链路数十秒。
    direct_company = qcc_extract_company_name(question)
    # 现有通用提取器会保留“我是”这类口语前缀；MCP 规划阶段应传企业全称，
    # 不能把第一人称陈述当成工商主体的一部分。
    direct_company = re.sub(
        r"^(?:我是|我司|本公司|请(?:查询|检索|查找|分析)?|查询|检索|查找|分析|关于)+",
        "",
        direct_company,
    ).strip()
    has_direct_company = bool(re.search(
        r"(?:股份有限公司|有限责任公司|有限公司|合伙企业|个人独资企业|个体工商户|便利店|超市|商店|店|集体经济组织|经济合作社|村民委员会|居民委员会)$",
        direct_company,
    ))
    if has_direct_company:
        direct_intent = (
            "related_companies" if qcc_asks_for_related_companies(question)
            else "company_risk" if any(marker in question for marker in _AUTO_ENTERPRISE_RISK_MARKERS)
            else "company_profile"
        )
        return {
            "company_name": direct_company[:120],
            "person_name": qcc_extract_person_name(question)[:12],
            "intent": direct_intent,
        }

    schema = {
        "company_name": "", "person_name": "", "intent": "company_profile",
    }
    messages = [
        {
            "role": "system",
            "content": (
                "你是企业数据检索前的轻量查询规划器。只提取用户明确说出的企业名称和人员姓名，"
                "不得猜测或补全。intent 仅可为 company_profile、related_companies、company_risk。"
                "当用户询问某负责人/法定代表人/经营者还经营、任职、关联、控制哪些企业时，"
                "intent 必须为 related_companies。只输出合法 JSON，不要解释。"
            ),
        },
        {
            "role": "user",
            "content": (
                f"用户原话：{question}\n"
                f"请按此结构返回：{json.dumps(schema, ensure_ascii=False)}"
            ),
        },
    ]
    try:
        # 规划结果很短，不能走面向长篇答案的“完整性续写”封装：该封装会把
        # 合法但不足 180 字的 JSON 误判为不完整。
        raw_result, _ = await asyncio.wait_for(
            _call_ai_with_fallback(
                DEFAULT_AI_MODEL, messages, temperature=0.0, max_tokens=240
            ),
            timeout=10.0,
        )
        raw_answer, _reasoning, _finish_reason = _extract_ai_choice(raw_result)
        plan = parse_model_json(raw_answer)
    except Exception:
        return {"company_name": "", "person_name": "", "intent": ""}
    if not isinstance(plan, dict):
        return {"company_name": "", "person_name": "", "intent": ""}
    company_name = str(plan.get("company_name") or "").strip()[:120]
    person_name = str(plan.get("person_name") or "").strip()[:12]
    intent = str(plan.get("intent") or "").strip()
    if intent not in {"company_profile", "related_companies", "company_risk"}:
        intent = ""
    return {"company_name": company_name, "person_name": person_name, "intent": intent}


