def _storage_is_review_artifact(path: Path, kb_dir: Path) -> bool:
    try:
        rel = path.relative_to(kb_dir)
        return (rel.parts[:2] == ("data", "dossier-ui-review") and len(rel.parts) == 3
                and path.name in _STORAGE_REVIEW_IMAGE_NAMES
                and not any((kb_dir.joinpath(*rel.parts[:index])).is_symlink()
                            for index in range(1, len(rel.parts) + 1)))
    except ValueError:
        return False


def _storage_classify_path(path: Path, kb_dir: Path) -> str:
    """将单个文件归入储存管理分类，返回 categories 的 raw key。

    分类规则是 get_storage_info 的统计口径：每个文件只归入一个分类；
    新增目录/文件类型时在此登记，避免落入「其它项目文件」。
    """
    try:
        rel = path.relative_to(kb_dir)
    except ValueError:
        return "project_files"
    parts = rel.parts
    first = parts[0] if parts else path.name
    rel_posix = rel.as_posix()

    if path.name.endswith((".db-wal", ".db-shm", ".db-journal", ".bak-wal", ".bak-shm", ".bak-journal")):
        return "database_sidecars"
    if parts[:2] == ("data", "cc2api-runtime"):
        return "ai_runtime"
    if parts[:2] == ("data", "download-center"):
        return "download_records"
    if parts[:2] == ("data", "invoice_auto_collections"):
        return "invoice_collections"
    if _storage_is_review_artifact(path, kb_dir):
        return "review_artifacts"
    if (first == "data" and path.name.startswith(("mail_", "invoice_"))) or parts[:2] == ("data", "mail-team-labels"):
        return "mail_invoice_data"
    if first == "docs":
        return "project_docs"
    if first in {"deploy", ".github", "third_party"} or rel_posix in {"LICENSE", ".dockerignore"}:
        return "deployment_files"
    if first == ".swift-module-cache":
        return "swift_cache"
    if any(part in _STORAGE_CACHE_NAMES for part in parts) or path.name == ".DS_Store" or path.suffix in {".pyc", ".pyo"}:
        return "safe_cache"
    if first == "uploads":
        return "uploads"
    if first == "article_images":
        return "article_images"
    if rel_posix == "legal_kb.db":
        return "legal_kb.db"
    if rel_posix == "backend/legal_kb.db":
        return "legacy_databases"
    if _storage_is_history_backup_file(path, kb_dir):
        return "history_backups"
    if _storage_is_browser_runtime_cache(path, kb_dir):
        return "browser_runtime_cache"
    if first == "frontend":
        return "frontend"
    if first == "backend":
        return "backend"
    if first == "fada-wang":
        return "fada-wang"
    if first == "logos":
        return "logos"
    if first == "mcp-server":
        return "mcp-server"
    if len(parts) > 2 and parts[0] == "node_modules" and any(part in _STORAGE_NODE_AUX_DIRS for part in parts[1:-1]):
        return "node_aux"
    if first == "node_modules":
        return "node_modules"
    if first == "dist":
        return "dist"
    if len(parts) == 1 and path.name in {"pending_tasks.db", "pending_tags.db"}:
        return "pending_tasks.db"
    if path.name.startswith("feishu_") or path.name in {"README_Feishu.md", "README_Feishu_AutoFetch.md"}:
        return "feishu"
    if _storage_is_runtime_log_file(path):
        return "runtime_logs"
    if first == ".tmp":
        return "temp_files"
    if first == "tests":
        return "test_code"
    if first == "native-shell":
        return "native_shell"
    if first == "outputs":
        return "outputs"
    if first == ".swift-bin":
        return "swift_bin"
    if first == "scripts" or path.name in _STORAGE_PROJECT_SCRIPT_NAMES:
        return "project_scripts"
    if (
        path.name in _STORAGE_PROJECT_CONFIG_NAMES
        or (first == path.name and path.name.startswith("local_") and path.name.endswith(".json"))
    ):
        return "project_config"
    if path.name in _STORAGE_PACKAGE_FILE_NAMES:
        return "package_files"
    if first == path.name and path.name == "scripts.zip":
        return "project_archives"
    if first == path.name and (path.name in _STORAGE_LEGACY_DB_NAMES or path.name.endswith(".sqlite") or path.name.endswith(".sqlite3")):
        return "legacy_databases"
    if first == path.name and path.suffix.lower() in {".md", ".markdown"}:
        return "project_docs"
    return "app_runtime_data" if first == "data" else "project_files"


@app.get("/api/storage-info")
def get_storage_info():
    """返回项目各类文件的存储占用情况。

    统计口径：每个文件只归入一个分类，列表项之和应等于总占用。
    """
    import os

    def format_size(b):
        if b < 1024:
            return f"{b} B"
        elif b < 1024 ** 2:
            return f"{b / 1024:.1f} KB"
        elif b < 1024 ** 3:
            return f"{b / 1024 ** 2:.1f} MB"
        else:
            return f"{b / 1024 ** 3:.2f} GB"

    kb_dir = BASE_DIR.resolve()
    categories = {
        "uploads": {"name": "上传文件", "desc": "文章关联的原始文件", "kind": "cleanable", "size": 0, "count": 0},
        "article_images": {"name": "文章配图", "desc": "文章插图与 PDF 逐页渲染图片（含可选中文字层），阅读页平铺展示直接引用", "kind": "system", "size": 0, "count": 0},
        "temp_files": {"name": "临时文件", "desc": "开发打包副本、更新工具及验收产物；请查看逐项用途与清理建议", "kind": "optional", "size": 0, "count": 0},
        "test_code": {"name": "测试代码", "desc": "后端功能自动化测试脚本", "kind": "system", "size": 0, "count": 0},
        "native_shell": {"name": "桌面应用壳", "desc": "macOS 原生应用壳与图标资源", "kind": "system", "size": 0, "count": 0},
        "outputs": {"name": "导出文件", "desc": "公开版打包、发布副本、验收截图及业务导出；可查看完整列表并手动选择清理", "kind": "optional", "size": 0, "count": 0},
        "swift_bin": {"name": "本地桥接程序", "desc": "日历/通讯录桥接编译产物", "kind": "system", "size": 0, "count": 0},
        "legal_kb.db": {"name": "主数据库", "desc": "当前运行中的 SQLite 数据库：文章正文、标签、笔记、索引和问答记录", "kind": "system", "size": 0, "count": 0},
        "backend_db": {"name": "后端数据库", "desc": "后端数据库副本", "kind": "system", "size": 0, "count": 0},
        "frontend": {"name": "前端界面", "desc": "知识库页面、工具页、样式、图标和离线静态资源", "kind": "system", "size": 0, "count": 0},
        "backend": {"name": "后端代码", "desc": "服务器端程序代码（不含法院在线浏览器数据和缓存）", "kind": "system", "size": 0, "count": 0},
        "browser_runtime_cache": {"name": "浏览器运行缓存", "desc": "法院在线服务下载的 Chromium 页面、组件与模型缓存；清理前会关闭后台浏览器，清理后会自动重新生成，不会退出登录", "kind": "cleanable", "size": 0, "count": 0},
        "fada-wang": {"name": "法答网数据", "desc": "法答网问答缓存数据", "kind": "system", "size": 0, "count": 0},
        "logos": {"name": "Logo 图片", "desc": "网站 Logo 图标文件", "kind": "system", "size": 0, "count": 0},
        "mcp-server": {"name": "MCP 服务", "desc": "WorkBuddy 知识库连接服务", "kind": "system", "size": 0, "count": 0},
        "node_modules": {"name": "Node 依赖", "desc": "MCP/本地工具运行依赖", "kind": "system", "size": 0, "count": 0},
        "node_aux": {"name": "Node 文档/示例/测试", "desc": "node_modules 中不参与运行的测试、示例和文档目录", "kind": "optional", "size": 0, "count": 0},
        "dist": {"name": "打包文件", "desc": "前端构建产物（可重新生成）", "kind": "cleanable", "size": 0, "count": 0},
        "safe_cache": {"name": "无用缓存", "desc": "Python 缓存、临时缓存、系统索引文件", "kind": "cleanable", "size": 0, "count": 0},
        "swift_cache": {"name": "Swift 编译缓存", "desc": "calendar_bridge.swift 编译产生的模块缓存，可自动重建", "kind": "cleanable", "size": 0, "count": 0},
        "runtime_logs": {"name": "运行日志", "desc": "服务日志和运行记录，可清空日志内容", "kind": "optional", "size": 0, "count": 0},
        "pending_tasks.db": {"name": "任务缓存库", "desc": "后台任务记录缓存", "kind": "cleanable", "size": 0, "count": 0},
        "history_backups": {"name": "历史备份文件", "desc": "更新、迁移或维护前创建的历史回滚快照；清理不影响当前运行", "kind": "optional", "size": 0, "count": 0},
        "feishu": {"name": "飞书集成", "desc": "飞书 Bot、监听和配置文件", "kind": "system", "size": 0, "count": 0},
        "project_docs": {"name": "说明文档", "desc": "安装、部署、修复和使用说明文档", "kind": "system", "size": 0, "count": 0},
        "project_scripts": {"name": "维护脚本", "desc": "启动、重启、部署、修复和数据维护脚本", "kind": "system", "size": 0, "count": 0},
        "project_config": {"name": "本地配置", "desc": "访问密钥、AI 配置、启动项和打包配置", "kind": "system", "size": 0, "count": 0},
        "package_files": {"name": "包管理文件", "desc": "Python/Node 依赖清单和锁定文件", "kind": "system", "size": 0, "count": 0},
        "project_archives": {"name": "部署压缩包", "desc": "部署或迁移时生成的脚本归档，不参与运行", "kind": "optional", "size": 0, "count": 0},
        "legacy_databases": {"name": "旧数据库占位", "desc": "非当前运行库的旧数据库或空占位文件", "kind": "optional", "size": 0, "count": 0},
        "project_files": {"name": "其它项目文件", "desc": "未归入上述类别的项目辅助文件", "kind": "system", "size": 0, "count": 0},
    }

    for raw, (name, desc, kind) in _STORAGE_DETAIL_CATEGORIES.items():
        categories[raw] = {"name": name, "desc": desc, "kind": kind, "size": 0, "count": 0}
    details = {raw: [] for raw in _STORAGE_DETAIL_CATEGORIES}
    temporary_files = []
    total = 0
    for path in _storage_inventory_files(kb_dir):
        try:
            size = path.stat().st_size
        except OSError:
            continue

        total += size
        key = _storage_category_for_path(path, kb_dir)
        if key not in categories:
            key = "project_files"
        categories[key]["size"] += size
        categories[key]["count"] += 1
        if key == "temp_files":
            temporary_files.append({"name": path.relative_to(kb_dir).as_posix(), "size": size})
        if key in details:
            details[key].append({"name": path.relative_to(kb_dir).as_posix() if _storage_is_within(path, kb_dir) else str(path),
                                 "size": size, "size_fmt": format_size(size),
                                 "cleanable": key == "review_artifacts"})

    # ── uploads 子文件统计 ──
    file_types = {}
    uploads_dir = UPLOAD_DIR
    if uploads_dir.exists():
        for f in uploads_dir.rglob('*'):
            if _storage_is_upload_file(f):
                ext = f.suffix.lower()
                file_types[ext] = file_types.get(ext, 0) + 1

    from backend.storage_temporary import inventory as temporary_inventory
    temporary_rows = temporary_inventory(kb_dir, temporary_files)
    for row in temporary_rows:
        row["size_fmt"] = format_size(row["size"])
        row["disk_size_fmt"] = format_size(row["disk_size"])
    items = []
    for raw, item in categories.items():
        if item["size"] <= 0 and raw not in {"uploads", "safe_cache"}:
            continue
        item_type = "dir" if raw in {"uploads", "article_images", "temp_files", "test_code", "native_shell", "outputs", "swift_bin", "frontend", "backend", "browser_runtime_cache", "fada-wang", "logos", "mcp-server", "node_modules", "node_aux", "dist", "safe_cache", "swift_cache"} else "file"
        configured_item_paths = {
            "legal_kb.db": DB_PATH,
            "uploads": UPLOAD_DIR,
            "article_images": ARTICLE_IMAGE_DIR,
        }
        path = configured_item_paths.get(raw) or (
            kb_dir / raw if raw not in {"backend_db", "node_aux", "safe_cache", "swift_cache", "runtime_logs", "history_backups", "browser_runtime_cache", "feishu", "project_docs", "project_scripts", "project_config", "package_files", "project_archives", "legacy_databases", "project_files", "article_images", "temp_files", "test_code", "native_shell", "outputs", "swift_bin"} else kb_dir
        )
        items.append({
            "name": item["name"],
            "raw": raw,
            "path": str(path),
            "size": item["size"],
            "size_fmt": format_size(item["size"]),
            "type": item_type,
            "kind": item["kind"],
            "desc": item["desc"],
            "count": item["count"],
            **({"temporary_items": temporary_rows} if raw == "temp_files" else {}),
            **({"files": sorted(details[raw], key=lambda f: (-f["size"], f["name"]))}
               if raw in details else {}),
        })
    items.sort(key=lambda x: x['size'], reverse=True)
    listed_total = sum(i["size"] for i in items)
    return {
        "total": total,
        "total_fmt": format_size(total),
        "listed_total": listed_total,
        "listed_total_fmt": format_size(listed_total),
        "unclassified": max(total - listed_total, 0),
        "unclassified_fmt": format_size(max(total - listed_total, 0)),
        "items": items,
        "file_types": file_types,
        "generated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }


# ─────────────────────────────────────────────
# 储存管理 - 获取上传文件列表（用于选择删除）
# ─────────────────────────────────────────────
@app.get("/api/storage/uploads")
def get_upload_files():
    """返回上传目录中的所有文件列表"""
    import os

    def format_size(b):
        if b < 1024:
            return f"{b} B"
        elif b < 1024 ** 2:
            return f"{b / 1024:.1f} KB"
        elif b < 1024 ** 3:
            return f"{b / 1024 ** 2:.1f} MB"
        else:
            return f"{b / 1024 ** 3:.2f} GB"

    uploads_dir = UPLOAD_DIR
    files = []
    upload_paths = sorted(
        (f for f in uploads_dir.rglob('*') if _storage_is_upload_file(f))
        if uploads_dir.exists() else [],
        key=lambda path: path.as_posix().lower(),
    )
    conn = get_db()
    try:
        associations = _storage_upload_associations(upload_paths, uploads_dir, BASE_DIR, conn)
        for f in upload_paths:
            try:
                rel_name = f.relative_to(uploads_dir).as_posix()
                size = f.stat().st_size
            except (OSError, ValueError):
                continue
            association = associations.get(f.resolve(), {"ids": set(), "titles": [], "ambiguous": False})
            files.append({
                "name": rel_name,
                "path": str(f.resolve()),
                "size": size,
                "size_fmt": format_size(size),
                "article_count": len(association["ids"]),
                "article_titles": association["titles"],
                "association_ambiguous": bool(association["ambiguous"]),
            })
    finally:
        conn.close()
    # 按文件大小排序
    files.sort(key=lambda x: x['size'], reverse=True)
    return {"files": files, "total": len(files)}


