@app.get("/api/storage/logs")
def get_runtime_log_files():
    """返回可说明、可选择清空的运行日志明细。"""
    import os

    def format_size(b):
        if b < 1024:
            return f"{b} B"
        elif b < 1024 ** 2:
            return f"{b / 1024:.1f} KB"
        elif b < 1024 ** 3:
            return f"{b / 1024 ** 2:.1f} MB"
        else:
            return f"{b / 1024 ** 3:.2f} GB"

    log_notes = {
        "server.log": {
            "title": "法律操作系统服务日志",
            "purpose": "记录后端启动、接口报错、文件入库、AI增强和存储管理等运行信息。",
            "cleanup_note": "可清空。只会失去历史排障记录，不影响文章、数据库、上传文件和页面功能；服务会继续写入新的日志。",
        },
        "bridge.log": {
            "title": "WorkBuddy 桥接日志",
            "purpose": "记录桌面端/本地工具与法律操作系统之间的连接、调用和通信信息。",
            "cleanup_note": "可清空。适合在日志体积很大、近期不需要排查连接问题时清理；不影响知识库数据。",
        },
        "server.pid": {
            "title": "服务进程标记",
            "purpose": "记录当前法律操作系统服务的进程编号，重启脚本会用它识别正在运行的服务。",
            "cleanup_note": "不建议清理。文件很小，保留可让一键重启更可靠。",
        },
    }

    files = []
    for f in _storage_runtime_log_candidates(BASE_DIR):
        try:
            size = f.stat().st_size
        except Exception:
            continue
        note = log_notes.get(f.name, {
            "title": "运行日志",
            "purpose": "记录某个本地组件的运行过程和错误信息，主要用于排查问题。",
            "cleanup_note": "可清空。只会删除历史日志内容，不影响知识库正文和数据库。",
        })
        cleanable = bool(re.fullmatch(r".+\.log(?:\.\d+)?", f.name)) and size > 0
        display_name = f.relative_to(BASE_DIR).as_posix()
        files.append({
            "name": display_name,
            "path": str(f),
            "size": size,
            "size_fmt": format_size(size),
            "title": note["title"],
            "purpose": note["purpose"],
            "cleanup_note": note["cleanup_note"],
            "cleanable": cleanable,
            "action": "清空内容" if cleanable else ("已清空" if ".log" in f.name else "建议保留"),
        })

    files.sort(key=lambda x: x["size"], reverse=True)
    return {
        "files": files,
        "total": len(files),
        "cleanable_total": sum(1 for f in files if f["cleanable"]),
        "cleanable_size": sum(f["size"] for f in files if f["cleanable"]),
        "cleanable_size_fmt": format_size(sum(f["size"] for f in files if f["cleanable"])),
        "generated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }


def _storage_format_size(b):
    if b < 1024:
        return f"{b} B"
    elif b < 1024 ** 2:
        return f"{b / 1024:.1f} KB"
    elif b < 1024 ** 3:
        return f"{b / 1024 ** 2:.1f} MB"
    return f"{b / 1024 ** 3:.2f} GB"


def _storage_describe_history_backup(path: Path) -> tuple[str, str]:
    """Return a short, user-facing source label and explanation for a snapshot."""
    name = path.name
    prefix = "legal_kb.db.before-"
    if name.startswith(prefix) and name.endswith(".bak"):
        operation = name[len(prefix):-len(".bak")]
        operation_label = {
            "court-dedup": "法院数据去重",
            "repair": "数据修复",
            "migration": "数据迁移",
        }.get(operation.rsplit("-", 2)[0], operation)
        return (
            "操作前自动备份",
            f"执行“{operation_label}”前自动创建，用于在异常时恢复到操作前状态。",
        )
    repair_prefix = "legal_kb.before-"
    if name.startswith(repair_prefix) and name.endswith(".db"):
        operation = name[len(repair_prefix):-len(".db")].rsplit("-", 1)[0]
        operation_label = {
            "note-markup-repair": "阅读笔记格式修复",
            "repair": "数据修复",
            "migration": "数据迁移",
        }.get(operation, operation)
        return (
            "操作前自动备份",
            f"执行“{operation_label}”前自动创建，用于在异常时恢复到操作前状态。",
        )
    if name.startswith("legal_kb.db.backup-"):
        return "手动/维护备份", "维护操作创建的历史数据库快照，用于必要时回滚。"
    return "历史数据库备份", "历史数据库快照，用于必要时回滚。"


@app.get("/api/storage/history-backups")
@app.get("/api/storage/db-backups", include_in_schema=False)
def get_history_backup_files():
    """Return selectable historical rollback files, excluding the live DB.

    这些文件不是当前运行库；当前运行库固定为 BASE_DIR/legal_kb.db。
    """
    files = []
    for f in _storage_history_backup_candidates(BASE_DIR):
        article_count = None
        integrity = "未检查"
        try:
            conn = sqlite3.connect(f"file:{f}?mode=ro", uri=True)
            try:
                integrity = conn.execute("PRAGMA integrity_check").fetchone()[0]
                article_count = conn.execute("SELECT COUNT(*) FROM articles").fetchone()[0]
            finally:
                conn.close()
        except Exception as e:
            integrity = f"无法读取：{e}"

        stat = f.stat()
        files.append({
            "name": f.name,
            "path": str(f),
            "size": stat.st_size,
            "size_fmt": _storage_format_size(stat.st_size),
            "modified_at": datetime.datetime.fromtimestamp(stat.st_mtime).strftime("%Y-%m-%d %H:%M:%S"),
            "article_count": article_count,
            "integrity": integrity,
            "backup_kind": _storage_describe_history_backup(f)[0],
            "backup_reason": _storage_describe_history_backup(f)[1],
            "cleanup_note": "可删除。删除后不影响当前知识库检索、问答、文章正文和上传文件，但会少一个手动回滚快照。",
        })
    return {
        "files": files,
        "total": len(files),
        "total_size": sum(f["size"] for f in files),
        "total_size_fmt": _storage_format_size(sum(f["size"] for f in files)),
        "generated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }


def _storage_db_table_group(name: str):
    if name.startswith("knowledge_"):
        return {
            "id": "legal_knowledge",
            "title": "法律知识层",
            "purpose": "法律问题、待审核/已审核结论、段落依据、关系、提取任务和审核日志。",
        }
    if name in {"articles", "article_paragraphs"} or name.startswith("articles_fts"):
        return {
            "id": "knowledge",
            "title": "知识库文章与全文检索",
            "purpose": "文章正文、摘要、段落和全文检索索引，是主数据库体积的主要来源。",
        }
    if name in {"notes", "article_list_pins", "article_tag_pins"} or name.startswith("tag_"):
        return {
            "id": "article_meta",
            "title": "文章笔记与标签",
            "purpose": "阅读笔记、置顶状态、标签目录和分组信息。",
        }
    if name.startswith("case_manager_"):
        return {
            "id": "case_manager",
            "title": "案件管理数据",
            "purpose": "案件、当事人、开庭、保全、上诉期限和日历同步记录。",
        }
    if name.startswith("research_"):
        return {
            "id": "research",
            "title": "案件研究数据",
            "purpose": "案件研究项目、备忘录、问题、关联文章和台账。",
        }
    if name.startswith("authority_watch") or name.startswith("expand_") or name in {"radar_digests", "recommendation_feedback"}:
        return {
            "id": "expand",
            "title": "扩展搜索/雷达/推荐",
            "purpose": "知识扩展检索历史、权威来源监控、雷达摘要和推荐反馈。",
        }
    if name.startswith("suohan_") or name.startswith("power_attorney_") or name == "document_history":
        return {
            "id": "tools",
            "title": "文书工具数据",
            "purpose": "所函、授权委托书、客户/法院/律师等工具配置与历史记录。",
        }
    if name.startswith("sqlite_"):
        return {
            "id": "sqlite_internal",
            "title": "SQLite 内部结构",
            "purpose": "SQLite 自动维护的表结构、序列和内部索引。",
        }
    return {
        "id": "other",
        "title": "其它业务数据",
        "purpose": "其它体积较小的业务表或索引。",
    }


def _storage_quote_identifier(name: str) -> str:
    return '"' + name.replace('"', '""') + '"'


@app.get("/api/storage/db-main")
def get_main_database_details():
    """返回主数据库内部表和索引占用明细。只读分析，不执行清理。"""
    db_path = DB_PATH
    if not db_path.exists():
        return {
            "exists": False,
            "file": str(db_path),
            "message": "主数据库不存在",
            "generated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }

    file_size = db_path.stat().st_size
    conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    conn.row_factory = sqlite3.Row
    try:
        page_size = conn.execute("PRAGMA page_size").fetchone()[0]
        page_count = conn.execute("PRAGMA page_count").fetchone()[0]
        freelist_count = conn.execute("PRAGMA freelist_count").fetchone()[0]

        objects = {
            row["name"]: {"type": row["type"], "tbl_name": row["tbl_name"]}
            for row in conn.execute(
                "SELECT type, name, tbl_name FROM sqlite_master WHERE type IN ('table', 'index')"
            )
        }

        object_sizes = {}
        dbstat_available = True
        try:
            for row in conn.execute("SELECT name, SUM(pgsize) AS size FROM dbstat GROUP BY name"):
                object_sizes[row["name"]] = int(row["size"] or 0)
        except Exception:
            dbstat_available = False

        tables = [name for name, meta in objects.items() if meta["type"] == "table"]
        table_buckets = {}
        for name in tables:
            table_buckets[name] = {
                "name": name,
                "row_count": None,
                "table_size": object_sizes.get(name, 0),
                "index_size": 0,
                "size": object_sizes.get(name, 0),
            }

        for object_name, size in object_sizes.items():
            meta = objects.get(object_name)
            if not meta:
                continue
            owner = meta["tbl_name"] or object_name
            if owner not in table_buckets:
                continue
            if meta["type"] == "index":
                table_buckets[owner]["index_size"] += size
                table_buckets[owner]["size"] += size

        for table in table_buckets.values():
            name = table["name"]
            try:
                table["row_count"] = conn.execute(f"SELECT COUNT(*) FROM {_storage_quote_identifier(name)}").fetchone()[0]
            except Exception:
                table["row_count"] = None

        group_map = {}
        table_rows = []
        for table in table_buckets.values():
            if table["size"] <= 0 and table["row_count"] in {0, None}:
                continue
            group = _storage_db_table_group(table["name"])
            group_item = group_map.setdefault(group["id"], {
                "id": group["id"],
                "title": group["title"],
                "purpose": group["purpose"],
                "size": 0,
                "size_fmt": "0 B",
                "table_count": 0,
                "row_count": 0,
            })
            group_item["size"] += table["size"]
            group_item["table_count"] += 1
            if isinstance(table["row_count"], int):
                group_item["row_count"] += table["row_count"]
            table_rows.append({
                "name": table["name"],
                "group_id": group["id"],
                "group_title": group["title"],
                "purpose": group["purpose"],
                "row_count": table["row_count"],
                "size": table["size"],
                "size_fmt": _storage_format_size(table["size"]),
                "table_size": table["table_size"],
                "table_size_fmt": _storage_format_size(table["table_size"]),
                "index_size": table["index_size"],
                "index_size_fmt": _storage_format_size(table["index_size"]),
            })

        free_bytes = freelist_count * page_size
        if free_bytes > 0:
            group_map["free_pages"] = {
                "id": "free_pages",
                "title": "SQLite 空闲页",
                "purpose": "删除或更新数据后留在数据库文件内的可复用空间；后续写入会优先复用，只有压缩数据库才会释放给磁盘。",
                "size": free_bytes,
                "size_fmt": _storage_format_size(free_bytes),
                "table_count": 0,
                "row_count": None,
            }

        groups = sorted(group_map.values(), key=lambda x: x["size"], reverse=True)
        for item in groups:
            item["size_fmt"] = _storage_format_size(item["size"])

        table_rows.sort(key=lambda x: x["size"], reverse=True)
        active_bytes = max(file_size - free_bytes, 0)
        return {
            "exists": True,
            "file": str(db_path),
            "file_name": db_path.name,
            "file_size": file_size,
            "file_size_fmt": _storage_format_size(file_size),
            "active_size": active_bytes,
            "active_size_fmt": _storage_format_size(active_bytes),
            "freelist_count": freelist_count,
            "freelist_size": free_bytes,
            "freelist_size_fmt": _storage_format_size(free_bytes),
            "page_size": page_size,
            "page_count": page_count,
            "dbstat_available": dbstat_available,
            "groups": groups,
            "tables": table_rows,
            "generated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "cleanup_note": "这是当前运行库，不提供删除；明细用于判断空间来源。空闲页会被 SQLite 后续复用。",
        }
    finally:
        conn.close()


def _bridge_log_category_meta():
    return {
        "startup": {
            "title": "启动/监听记录",
            "purpose": "记录桥接服务何时启动、监听哪个本地地址。",
            "cleanup_note": "可清理旧记录。清理后只少了历史启动痕迹，不影响当前连接。",
        },
        "node_missing": {
            "title": "Node 启动失败记录",
            "purpose": "记录桥接服务尝试启动 MCP 工具时找不到 node 命令、路径异常等问题。",
            "cleanup_note": "可选择清理。若近期仍在排查 WorkBuddy 连接问题，建议先保留最新一次错误。",
        },
        "errors": {
            "title": "其它错误/堆栈记录",
            "purpose": "记录桥接进程抛出的异常、错误堆栈和中断信息。",
            "cleanup_note": "可清理旧错误。清理后不影响知识库数据，但会减少排障线索。",
        },
        "calls": {
            "title": "连接/调用记录",
            "purpose": "记录桌面端、本地工具或 MCP 服务之间的连接、请求和调用过程。",
            "cleanup_note": "可清理历史调用流水。不会影响文章、数据库或上传文件。",
        },
        "general": {
            "title": "普通运行记录",
            "purpose": "记录无法归入上述类别的桥接运行信息。",
            "cleanup_note": "可清理旧记录。仅删除历史日志文本。",
        },
    }


def _is_new_bridge_log_block(text, has_current):
    if not has_current:
        return True
    stripped = text.strip()
    if not stripped:
        return False
    if stripped.startswith("[MCP Bridge]") or stripped.startswith("node:"):
        return True
    if re.match(r"^\[?\d{4}-\d{2}-\d{2}[ T]", stripped):
        return True
    if re.match(r"^(INFO|WARN|WARNING|ERROR|DEBUG)[:\s]", stripped):
        return True
    return False


def _classify_bridge_log_block(text):
    lowered = text.lower()
    if "spawn node enoent" in lowered or ("code: 'enoent'" in lowered and "mcp-server/server.js" in lowered):
        return "node_missing"
    if "unhandled 'error' event" in lowered or "traceback" in lowered or "exception" in lowered or "error:" in lowered:
        return "errors"
    if "[mcp bridge]" in lowered and ("已启动" in text or "监听" in text or "started" in lowered or "listening" in lowered):
        return "startup"
    if any(token in lowered for token in ["request", "response", "connect", "post ", "get ", "tool", "mcp"]) or any(token in text for token in ["连接", "调用", "请求", "响应"]):
        return "calls"
    return "general"


def _iter_bridge_log_blocks(path):
    current = []
    with path.open("rb") as fh:
        for raw in fh:
            text = raw.decode("utf-8", errors="replace")
            if _is_new_bridge_log_block(text, bool(current)):
                if current:
                    block_text = b"".join(current).decode("utf-8", errors="replace")
                    yield _classify_bridge_log_block(block_text), current, block_text
                current = [raw]
            else:
                current.append(raw)
    if current:
        block_text = b"".join(current).decode("utf-8", errors="replace")
        yield _classify_bridge_log_block(block_text), current, block_text


@app.get("/api/storage/logs/bridge")
def get_bridge_log_sections(path: Optional[str] = None):
    """按用途统计 bridge.log，可用于选择性清理其中某几类记录。"""
    bridge_log = BASE_DIR / "bridge.log"
    if path:
        requested = Path(path).resolve()
        try:
            requested.relative_to(BASE_DIR.resolve())
            if requested.name == "bridge.log" and requested.is_file():
                bridge_log = requested
        except ValueError:
            pass
    meta = _bridge_log_category_meta()
    sections = {
        key: {
            "id": key,
            "title": value["title"],
            "purpose": value["purpose"],
            "cleanup_note": value["cleanup_note"],
            "count": 0,
            "size": 0,
            "size_fmt": "0 B",
            "sample": "",
            "cleanable": True,
        }
        for key, value in meta.items()
    }

    if bridge_log.exists():
        for category, raw_lines, block_text in _iter_bridge_log_blocks(bridge_log):
            item = sections.get(category) or sections["general"]
            item["count"] += 1
            item["size"] += sum(len(line) for line in raw_lines)
            if not item["sample"]:
                item["sample"] = " ".join(line.strip() for line in block_text.splitlines()[:3])[:220]

    for item in sections.values():
        item["size_fmt"] = _storage_format_size(item["size"])

    ordered = sorted(sections.values(), key=lambda x: x["size"], reverse=True)
    return {
        "file": "bridge.log",
        "path": str(bridge_log),
        "exists": bridge_log.exists(),
        "sections": ordered,
        "total_size": sum(item["size"] for item in ordered),
        "total_size_fmt": _storage_format_size(sum(item["size"] for item in ordered)),
        "generated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    }


