@app.get("/api/storage/exports")
def storage_export_files(request: Request):
    require_remote_management_enabled(request)
    from backend.storage_exports import export_inventory
    files = [item for item in export_inventory(BASE_DIR / "outputs")
             if _storage_category_for_path(BASE_DIR / "outputs" / item["name"], BASE_DIR) == "outputs"]
    for item in files:
        item["size_fmt"] = _storage_format_size(item["size"])
    return {"files": files, "count": len(files), "size": sum(f["size"] for f in files)}


@app.get("/api/storage/exports/download")
def storage_export_download(request: Request, name: str):
    require_remote_management_enabled(request)
    from backend.storage_exports import export_path
    try:
        path = export_path(BASE_DIR / "outputs", name)
    except (ValueError, OSError) as exc:
        raise HTTPException(status_code=404, detail=str(exc))
    return FileResponse(path, filename=path.name, media_type="application/octet-stream",
                        headers={"X-Content-Type-Options": "nosniff", "Cache-Control": "no-store"})


@app.post("/api/storage/cleanup")
async def cleanup_storage(request: Request):
    """
    清理存储空间
    - type: "dist" | "uploads" | "files" | "safe_cache" | "swift_cache" | "browser_runtime_cache" | "node_aux" | "project_archives" | "legacy_databases" | "pending_tasks.db" | "runtime_logs" | "log_files" | "history_backup_files" | "bridge_log_sections" | "temp_files"
    - paths: ["path1", "path2", ...]  # 当 type="files" 或 "log_files" 时使用
    - categories: ["node_missing", ...]  # 当 type="bridge_log_sections" 时使用
    """
    require_remote_management_enabled(request)
    import shutil
    from fastapi import HTTPException

    body = await request.json()
    if not isinstance(body, dict):
        return {"ok": False, "message": "清理请求格式不正确"}
    cleanup_type = body.get("type")
    file_paths = body.get("paths", [])
    categories = body.get("categories", [])

    if not isinstance(file_paths, list) or not isinstance(categories, list):
        return {"ok": False, "message": "清理请求中的文件或日志类别格式不正确"}

    kb_dir = BASE_DIR.resolve()

    if cleanup_type == "export_files":
        from backend.storage_exports import delete_exports
        try:
            freed, errors = delete_exports(kb_dir / "outputs", body.get("files"))
        except (ValueError, OSError) as exc:
            return {"ok": False, "message": str(exc)}
        return {"ok": not errors, "bytes": freed, "bytes_fmt": _storage_format_size(freed),
                "message": f"已清理所选导出文件，释放 {_storage_format_size(freed)}" +
                           ("；部分文件未删除，请刷新后核对" if errors else "")}

    if cleanup_type == "review_artifact_files":
        if not file_paths or len(file_paths) > 200 or any(not isinstance(value, str) for value in file_paths):
            return {"ok": False, "message": "请选择要清理的验收截图"}
        selected = []
        for value in set(file_paths):
            path = kb_dir / value
            if (not _storage_is_review_artifact(path, kb_dir) or not path.is_file()
                    or path.resolve() != path.absolute()):
                return {"ok": False, "message": "包含不可清理的文件，请刷新明细后重试"}
            selected.append(path)
        freed = 0
        errors = []
        for path in selected:
            try:
                size = path.stat().st_size
                path.unlink()
                freed += size
            except OSError:
                errors.append(path.name)
        return {"ok": not errors, "bytes": freed, "bytes_fmt": _storage_format_size(freed),
                "message": f"已清理验收截图，释放 {_storage_format_size(freed)}" +
                           ("；部分文件失败，请刷新后重试" if errors else "")}

    if cleanup_type == "dist":
        # 清理打包文件（dist 目录）
        dist_dir = kb_dir / 'dist'
        if dist_dir.exists():
            try:
                size = sum(f.stat().st_size for f in dist_dir.rglob("*") if f.is_file() and not f.is_symlink())
                shutil.rmtree(dist_dir)
                return {"ok": True, "message": f"打包文件已清理，释放 {_storage_format_size(size)}", "freed": "dist", "bytes": size, "bytes_fmt": _storage_format_size(size)}
            except Exception as exc:
                return {"ok": False, "message": f"打包文件清理失败：{exc}"}
        return {"ok": False, "message": "打包文件目录不存在"}

    elif cleanup_type == "browser_runtime_cache":
        # The court integration owns the persistent Chrome/CDP session. Stop
        # it first so Chrome cannot recreate the directories while this
        # endpoint is removing them. The hook keeps storage management decoupled
        # from the browser scheduler and preserves profile login data.
        prepare_browser_cleanup = getattr(
            app.state, "prepare_court_browser_runtime_cache_cleanup", None
        )
        if prepare_browser_cleanup:
            try:
                await prepare_browser_cleanup()
            except Exception as exc:
                return {
                    "ok": False,
                    "message": f"浏览器运行缓存清理已取消：无法先关闭受控法院浏览器（{exc}）",
                }
        deleted_dirs = 0
        freed_bytes = 0
        errors = []
        for directory in _storage_browser_runtime_cache_dirs(kb_dir):
            try:
                if not directory.exists() or not directory.is_dir() or not _storage_is_browser_runtime_cache(directory, kb_dir):
                    continue
                freed_bytes += sum(
                    item.stat().st_size for item in directory.rglob("*")
                    if item.is_file() and not item.is_symlink()
                )
                shutil.rmtree(directory)
                deleted_dirs += 1
            except Exception as exc:
                errors.append(f"{directory.name}: {exc}")
        return {
            "ok": not errors,
            "message": (
                f"已清理 {deleted_dirs} 个浏览器运行缓存目录，约释放 {_storage_format_size(freed_bytes)}；登录状态和下载文件未改动"
                if not errors else
                f"已清理 {deleted_dirs} 个目录，约释放 {_storage_format_size(freed_bytes)}；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "browser_runtime_cache",
            "count": deleted_dirs,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
        }

    elif cleanup_type == "safe_cache":
        cache_dirs = []
        for root, dirs, files in os.walk(kb_dir):
            root_path = Path(root)
            dirs[:] = [name for name in dirs if name not in _STORAGE_IGNORED_PROJECT_DIRS]
            for d in list(dirs):
                if d in {"__pycache__", ".pycache_tmp", ".pytest_cache", ".cache"}:
                    cache_dirs.append(root_path / d)
        deleted_dirs = 0
        deleted_files = 0
        freed_bytes = 0
        errors = []
        for d in cache_dirs:
            try:
                freed_bytes += sum(
                    f.stat().st_size for f in d.rglob("*")
                    if f.is_file() and not f.is_symlink()
                )
                shutil.rmtree(d)
                deleted_dirs += 1
            except Exception as exc:
                errors.append(f"{d}: {exc}")
        for root, dirs, files in os.walk(kb_dir, topdown=True, followlinks=False):
            dirs[:] = [name for name in dirs if name not in _STORAGE_IGNORED_PROJECT_DIRS]
            for filename in files:
                if filename != ".DS_Store":
                    continue
                ds = Path(root) / filename
                try:
                    if ds.is_symlink():
                        continue
                    freed_bytes += ds.stat().st_size
                    ds.unlink()
                    deleted_files += 1
                except Exception as exc:
                    errors.append(f"{ds}: {exc}")
        return {
            "ok": not errors,
            "message": (
                f"已清理 {deleted_dirs} 个缓存目录、{deleted_files} 个系统缓存文件"
                if not errors else
                f"已清理 {deleted_dirs} 个缓存目录、{deleted_files} 个系统缓存文件；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "safe_cache",
            "count": deleted_dirs + deleted_files,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
            "errors": errors,
        }

    elif cleanup_type == "swift_cache":
        swift_cache = kb_dir / ".swift-module-cache"
        if swift_cache.exists() and swift_cache.is_dir():
            try:
                size = sum(
                    f.stat().st_size for f in swift_cache.rglob("*")
                    if f.is_file() and not f.is_symlink()
                )
                shutil.rmtree(swift_cache)
                return {
                    "ok": True,
                    "message": f"Swift 编译缓存已清理，约释放 {_storage_format_size(size)}；需要时会自动重新生成",
                    "freed": "swift_cache",
                    "count": 1,
                    "bytes": size,
                    "bytes_fmt": _storage_format_size(size),
                }
            except Exception as exc:
                return {"ok": False, "message": f"Swift 编译缓存清理失败：{exc}"}
        return {"ok": False, "message": "Swift 编译缓存目录不存在"}

    elif cleanup_type == "temp_files":
        from backend.storage_temporary import inventory, delete_selected
        # Legacy requests without an explicit selection must never empty .tmp.
        counted_files = []
        tmp_dir = kb_dir / ".tmp"
        if tmp_dir.is_dir() and not tmp_dir.is_symlink():
            for path in _storage_inventory_files(kb_dir):
                if _storage_is_within(path, tmp_dir) and _storage_category_for_path(path, kb_dir) == "temp_files":
                    counted_files.append({"name": path.relative_to(kb_dir).as_posix(), "size": path.stat().st_size})
        try:
            freed, errors = delete_selected(kb_dir, body.get("items"), inventory(kb_dir, counted_files))
        except (ValueError, OSError) as exc:
            return {"ok": False, "message": str(exc)}
        return {"ok": not errors, "bytes": freed, "bytes_fmt": _storage_format_size(freed),
                "message": f"已清理所选临时产物，约释放 {_storage_format_size(freed)}" +
                           ("；部分文件失败，请刷新核对" if errors else ""), "errors": errors}

    elif cleanup_type == "node_aux":
        node_root = kb_dir / "node_modules"
        if not node_root.exists():
            return {"ok": False, "message": "Node 依赖目录不存在"}
        if node_root.is_symlink() or not _storage_is_within(node_root, kb_dir):
            return {"ok": False, "message": "Node 依赖目录不在应用目录内，已停止清理以保护其它文件"}
        node_root = node_root.resolve()
        aux_names = {"test", "tests", "__tests__", "example", "examples", "doc", "docs"}
        deleted_dirs = 0
        freed_bytes = 0
        errors = []
        candidates = []
        for root, dirs, _files in os.walk(node_root):
            root_path = Path(root)
            for dirname in list(dirs):
                if dirname in aux_names:
                    candidates.append(root_path / dirname)
            dirs[:] = [d for d in dirs if d not in aux_names]
        candidates.sort(key=lambda p: len(p.parts), reverse=True)
        for directory in candidates:
            try:
                resolved = directory.resolve()
                resolved.relative_to(node_root)
                size = sum(f.stat().st_size for f in resolved.rglob("*") if f.is_file() and not f.is_symlink())
                shutil.rmtree(resolved)
                deleted_dirs += 1
                freed_bytes += size
            except Exception as exc:
                errors.append(f"{directory}: {exc}")
        return {
            "ok": not errors,
            "message": (
                f"已清理 {deleted_dirs} 个 Node 测试/示例/文档目录，约释放 {_storage_format_size(freed_bytes)}"
                if not errors else
                f"已清理 {deleted_dirs} 个目录，约释放 {_storage_format_size(freed_bytes)}；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "node_aux",
            "count": deleted_dirs,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
            "errors": errors,
        }

    elif cleanup_type == "legacy_databases":
        deleted = 0
        freed_bytes = 0
        errors = []
        allowed = {kb_dir / "legal_knowledge.db", kb_dir / "backend" / "legal_kb.db"}
        for f in kb_dir.iterdir():
            if f.is_file() and f.suffix in {".sqlite", ".sqlite3"}:
                allowed.add(f)
        for f in allowed:
            try:
                p = f.resolve()
                p.relative_to(kb_dir.resolve())
                if p == DB_PATH.resolve() or _storage_is_db_backup_file(p, kb_dir):
                    continue
                if p.exists() and p.is_file():
                    size = p.stat().st_size
                    p.unlink()
                    deleted += 1
                    freed_bytes += size
            except Exception as exc:
                errors.append(f"{f}: {exc}")
        return {
            "ok": not errors,
            "message": (
                f"已清理 {deleted} 个旧数据库占位文件，约释放 {_storage_format_size(freed_bytes)}"
                if not errors else
                f"已清理 {deleted} 个旧数据库占位文件，约释放 {_storage_format_size(freed_bytes)}；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "legacy_databases",
            "count": deleted,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
            "errors": errors,
        }

    elif cleanup_type == "project_archives":
        archive = kb_dir / "scripts.zip"
        if archive.exists() and archive.is_file():
            try:
                size = archive.stat().st_size
                archive.unlink()
                return {
                    "ok": True,
                    "message": f"部署压缩包已清理，约释放 {_storage_format_size(size)}",
                    "freed": "project_archives",
                    "count": 1,
                    "bytes": size,
                    "bytes_fmt": _storage_format_size(size),
                }
            except Exception as exc:
                return {"ok": False, "message": f"部署压缩包清理失败：{exc}"}
        return {"ok": False, "message": "部署压缩包不存在"}

    elif cleanup_type == "pending_tasks.db":
        deleted = 0
        freed_bytes = 0
        errors = []
        for pending in (kb_dir / "pending_tasks.db", kb_dir / "pending_tags.db"):
            if not pending.exists() or not pending.is_file() or pending.is_symlink():
                continue
            try:
                size = pending.stat().st_size
                pending.unlink()
                deleted += 1
                freed_bytes += size
            except Exception as exc:
                errors.append(f"{pending.name}: {exc}")
        return {
            "ok": not errors,
            "message": (
                f"已清理 {deleted} 个任务缓存文件，释放 {_storage_format_size(freed_bytes)}"
                if not errors else
                f"已清理 {deleted} 个任务缓存文件；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "pending_tasks.db",
            "count": deleted,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
            "errors": errors,
        }

    elif cleanup_type == "runtime_logs":
        cleared = 0
        freed_bytes = 0
        errors = []
        for log_file in _storage_runtime_log_candidates(kb_dir):
            if not re.fullmatch(r".+\.log(?:\.\d+)?", log_file.name):
                continue
            try:
                freed_bytes += log_file.stat().st_size
                with log_file.open("wb"):
                    pass
                cleared += 1
            except Exception as exc:
                errors.append(f"{log_file.name}: {exc}")
        return {
            "ok": cleared > 0 and not errors,
            "message": (
                f"已清空 {cleared} 个日志文件，约释放 {_storage_format_size(freed_bytes)}"
                if not errors else
                f"已清空 {cleared} 个日志文件；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "runtime_logs",
            "count": cleared,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
        }

    elif cleanup_type == "log_files":
        if not file_paths:
            return {"ok": False, "message": "未指定要清空的日志"}
        cleared = 0
        freed_bytes = 0
        errors = []
        kb_root = kb_dir.resolve()
        for path in file_paths:
            p = Path(path).resolve()
            try:
                rel = p.relative_to(kb_root)
            except ValueError:
                continue
            if not (
                len(rel.parts) in {1, 2}
                and (len(rel.parts) == 1 or rel.parts[0] == "logs")
                and re.fullmatch(r".+\.log(?:\.\d+)?", p.name)
            ):
                continue
            if p.exists() and p.is_file():
                try:
                    freed_bytes += p.stat().st_size
                    # 原地截断以保留 inode。launchd 可能仍持有 bridge.log 的
                    # 文件描述符；替换文件会让后续日志继续写进不可见的旧 inode。
                    with p.open("wb"):
                        pass
                    cleared += 1
                except Exception as exc:
                    errors.append(f"{p.name}: {exc}")
        return {
            "ok": cleared > 0 and not errors,
            "message": (
                f"已清空 {cleared} 个日志文件，约释放 {_storage_format_size(freed_bytes)}"
                if not errors else
                f"已清空 {cleared} 个日志文件；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "log_files",
            "count": cleared,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
        }

    elif cleanup_type in {"history_backup_files", "db_backup_files"}:
        if not file_paths:
            return {"ok": False, "message": "未指定要删除的历史备份"}
        deleted = 0
        freed_bytes = 0
        errors = []
        kb_root = kb_dir.resolve()
        for path in file_paths:
            p = Path(path).resolve()
            try:
                rel = p.relative_to(kb_root)
            except ValueError:
                continue
            if not _storage_is_history_backup_file(p, kb_root):
                continue
            if p.exists() and p.is_file():
                try:
                    size = p.stat().st_size
                    p.unlink()
                    deleted += 1
                    freed_bytes += size
                except Exception as exc:
                    errors.append(f"{p.name}: {exc}")
        if deleted == 0:
            return {"ok": False, "message": f"没有成功删除历史备份；请刷新页面后重试{('；' + '；'.join(errors)) if errors else ''}", "errors": errors}
        return {
            "ok": not errors,
            "message": (
                f"已删除 {deleted} 个历史备份文件，约释放 {_storage_format_size(freed_bytes)}"
                if not errors else
                f"已删除 {deleted} 个历史备份文件，约释放 {_storage_format_size(freed_bytes)}；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "history_backup_files",
            "count": deleted,
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
            "errors": errors,
        }

    elif cleanup_type == "bridge_log_sections":
        allowed = set(_bridge_log_category_meta().keys())
        selected = {c for c in categories if c in allowed}
        if not selected:
            return {"ok": False, "message": "未指定要清理的桥接日志类别"}

        bridge_log = kb_dir / "bridge.log"
        requested_bridge_path = body.get("path")
        if requested_bridge_path:
            requested = Path(str(requested_bridge_path)).resolve()
            try:
                requested.relative_to(kb_dir.resolve())
                if requested.name == "bridge.log":
                    bridge_log = requested
            except ValueError:
                return {"ok": False, "message": "桥接日志路径不在应用目录内"}
        if not bridge_log.exists():
            return {"ok": False, "message": "bridge.log 不存在"}

        tmp_path = bridge_log.with_name(f".{bridge_log.name}.storage.tmp")
        removed_blocks = 0
        removed_bytes = 0
        try:
            with tmp_path.open("wb") as out:
                for category, raw_lines, _block_text in _iter_bridge_log_blocks(bridge_log):
                    block_size = sum(len(line) for line in raw_lines)
                    if category in selected:
                        removed_blocks += 1
                        removed_bytes += block_size
                        continue
                    out.writelines(raw_lines)
            # 保留 bridge.log 的 inode：launchd 会长期持有该日志的文件描述符。
            # 复制失败时不报告成功，并在 finally 中移除临时文件，避免留下脏文件。
            with tmp_path.open("rb") as source, bridge_log.open("wb") as target:
                shutil.copyfileobj(source, target, length=1024 * 1024)
        except Exception as exc:
            return {"ok": False, "message": f"桥接日志清理失败：{exc}"}
        finally:
            tmp_path.unlink(missing_ok=True)
        return {
            "ok": True,
            "message": f"已清理 {removed_blocks} 段桥接日志，约释放 {_storage_format_size(removed_bytes)}",
            "freed": "bridge_log_sections",
            "count": removed_blocks,
            "bytes": removed_bytes,
            "bytes_fmt": _storage_format_size(removed_bytes),
        }

    elif cleanup_type == "uploads":
        # 清理全部上传文件（含子目录）
        uploads_dir = UPLOAD_DIR
        if uploads_dir.exists():
            all_files = [f for f in uploads_dir.rglob('*') if _storage_is_upload_file(f)]
            conn = get_db()
            try:
                associations = _storage_upload_associations(all_files, uploads_dir, BASE_DIR, conn)
            finally:
                conn.close()

            deleted_files = []
            errors = []
            for f in all_files:
                try:
                    size = f.stat().st_size
                    f.unlink()
                    deleted_files.append((f.resolve(), size))
                except Exception as exc:
                    errors.append(f"{f.name}: {exc}")

            deleted_paths = {path for path, _size in deleted_files}
            deleted_article_ids = set()
            for path in deleted_paths:
                deleted_article_ids.update(associations.get(path, {}).get("ids", set()))
            db_error = None
            if deleted_article_ids:
                try:
                    conn = get_db()
                    try:
                        conn.executemany(
                            "UPDATE articles SET source_localpath = NULL, source_filename = NULL WHERE id = ?",
                            [(article_id,) for article_id in sorted(deleted_article_ids)],
                        )
                        conn.commit()
                    finally:
                        conn.close()
                except Exception as exc:
                    db_error = str(exc)
                    errors.append(f"数据库关联更新失败：{exc}")

            freed_bytes = sum(size for _path, size in deleted_files)
            return {
                "ok": not errors,
                "message": (
                    f"已清理 {len(deleted_files)} 个上传文件，释放 {_storage_format_size(freed_bytes)}"
                    if not errors else
                    f"已清理 {len(deleted_files)} 个上传文件，释放 {_storage_format_size(freed_bytes)}；{len(errors)} 个失败：{'；'.join(errors)}"
                ),
                "freed": "uploads",
                "count": len(deleted_files),
                "bytes": freed_bytes,
                "bytes_fmt": _storage_format_size(freed_bytes),
                "article_count": len(deleted_article_ids),
                "errors": errors,
                "database_error": db_error,
            }
        return {"ok": False, "message": "上传文件目录不存在"}

    elif cleanup_type == "files":
        # 删除指定的文件
        if not file_paths:
            return {"ok": False, "message": "未指定要删除的文件"}
        uploads_root = UPLOAD_DIR.resolve()
        requested_files = []
        errors = []
        for path in file_paths:
            p = Path(path).resolve()
            if p == uploads_root or not _storage_is_within(p, uploads_root):
                errors.append(f"{path}: 文件路径不在上传目录内")
                continue
            if p.exists() and _storage_is_upload_file(p):
                requested_files.append(p)
            else:
                errors.append(f"{path}: 文件不存在或不是可清理的上传文件")

        conn = get_db()
        try:
            associations = _storage_upload_associations(requested_files, UPLOAD_DIR, BASE_DIR, conn)
        finally:
            conn.close()

        deleted_files = []
        for p in requested_files:
            try:
                size = p.stat().st_size
                p.unlink()
                deleted_files.append((p, size))
            except Exception as exc:
                errors.append(f"{p.name}: {exc}")

        deleted_paths = {path for path, _size in deleted_files}
        deleted_article_ids = set()
        for path in deleted_paths:
            deleted_article_ids.update(associations.get(path, {}).get("ids", set()))
        if deleted_article_ids:
            try:
                conn = get_db()
                try:
                    conn.executemany(
                        "UPDATE articles SET source_localpath = NULL, source_filename = NULL WHERE id = ?",
                        [(article_id,) for article_id in sorted(deleted_article_ids)],
                    )
                    conn.commit()
                finally:
                    conn.close()
            except Exception as exc:
                errors.append(f"数据库关联更新失败：{exc}")

        freed_bytes = sum(size for _path, size in deleted_files)
        return {
            "ok": bool(deleted_files) and not errors,
            "message": (
                f"已删除 {len(deleted_files)} 个文件，释放 {_storage_format_size(freed_bytes)}"
                if not errors else
                f"已删除 {len(deleted_files)} 个文件，释放 {_storage_format_size(freed_bytes)}；{len(errors)} 个失败：{'；'.join(errors)}"
            ),
            "freed": "files",
            "count": len(deleted_files),
            "bytes": freed_bytes,
            "bytes_fmt": _storage_format_size(freed_bytes),
            "article_count": len(deleted_article_ids),
            "errors": errors,
        }

    else:
        raise HTTPException(status_code=400, detail="无效的清理类型")


