@app.get("/api/server-status")
def server_status():
    """检查服务器并确认运行进程已加载当前磁盘源码。"""
    asset_versions = {}
    try:
        html = (FRONTEND_DIR / "index.html").read_text(encoding="utf-8")
        for name, version in re.findall(r'/static/([^"?]+)\?v=([^"\']+)', html):
            asset_versions[name] = version
    except Exception:
        pass
    data = {
        "status": "running",
        "pid": os.getpid(),
        "port": DEFAULT_PORT,
        "app_version": APP_VERSION,
        "runtime_started_at": RUNTIME_STARTED_AT,
        "frontend_versions": asset_versions,
        "private_mode": is_private_mode(),
    }
    data.update(runtime_source_status(BASE_DIR, RUNTIME_SOURCE_VERSION))
    if not is_private_mode():
        data["base_dir"] = str(BASE_DIR)
    return data


@app.post("/api/restart-server")
def restart_server_api(request: Request):
    """仅允许本机页面调用现有 restart.py，在响应返回后重启服务。"""
    client_host = request.client.host if request.client else ""
    if client_host not in {"127.0.0.1", "::1", "localhost"}:
        raise HTTPException(status_code=403, detail="重启功能仅允许在本机使用")
    if request.headers.get("x-legal-kb-restart") != "confirmed":
        raise HTTPException(status_code=403, detail="缺少重启确认标记")

    restart_script = BASE_DIR / "restart.py"
    if not restart_script.exists():
        raise HTTPException(status_code=500, detail="未找到重启脚本")

    log_path = BASE_DIR / "server.log"
    try:
        with log_path.open("a", encoding="utf-8") as log_file:
            helper = subprocess.Popen(
                [_sys.executable, str(restart_script), "--delay", "1.2"],
                cwd=str(BASE_DIR),
                stdout=log_file,
                stderr=log_file,
                start_new_session=True,
            )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"无法启动重启程序：{exc}") from exc

    return {
        "ok": True,
        "message": "已安排重启",
        "current_pid": os.getpid(),
        "helper_pid": helper.pid,
    }


@app.post("/api/start-server")
def start_server_api(request: Request):
    """
    后端用 subprocess 在后台启动 uvicorn（自启动）。
    适用于服务器重启后前端一键唤起服务的场景。
    注意：此接口只有服务器本身已在运行时才能被调用；
    若完全宕机则由系统级 launchd/开机脚本负责，此接口用于同一进程崩溃重启。
    """
    require_remote_management_enabled(request)
    import socket
    import subprocess, sys, os
    project_dir = str(_RESOURCE_DIR.parent)  # legal-kb 目录
    port = int(os.environ.get("PORT", "8000"))
    host = os.environ.get("LEGAL_KB_HOST", "127.0.0.1")
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.3)
        if sock.connect_ex((host, port)) == 0:
            return {
                "ok": False,
                "error": f"端口 {port} 已被占用。请先退出旧的法律操作系统后端进程，再重新启动。",
                "port": port,
            }
    cmd = [
        sys.executable, "-m", "uvicorn",
        "backend.main:app",
        "--host", host,
        "--port", str(port),
    ]
    log_path = os.path.join(project_dir, "server.log")
    pid_path  = os.path.join(project_dir, "server.pid")
    try:
        with open(log_path, "a") as log_f:
            proc = subprocess.Popen(
                cmd,
                cwd=project_dir,
                stdout=log_f,
                stderr=log_f,
                start_new_session=True,
            )
        with open(pid_path, "w") as pf:
            pf.write(str(proc.pid))
        return {"ok": True, "pid": proc.pid}
    except Exception as e:
        return {"ok": False, "error": str(e)}


