# 案件本地文件工作区复用现有解析器和模型，但解析结果只进入案件文件专用索引。
def _parse_case_local_file(path: Path, allow_cloud_ocr: bool = False) -> Dict[str, Any]:
    suffix = path.suffix.lower()
    if suffix in {".png", ".jpg", ".jpeg"}:
        if not allow_cloud_ocr:
            return {"needs_ocr": True, "content": ""}
        from PIL import Image
        image = Image.open(path)
        buffer = BytesIO()
        image.convert("RGB").save(buffer, format="PNG")
        content = _ocr_page_image(buffer.getvalue(), filename=path.with_suffix(".png").name)
        return {"title": path.stem, "content": content, "ocr_used": True}
    if suffix == ".pdf":
        import PyPDF2
        with path.open("rb") as handle:
            reader = PyPDF2.PdfReader(handle)
            page_text = [(page.extract_text() or "") for page in reader.pages]
        average = sum(len(text.strip()) for text in page_text) / max(len(page_text), 1)
        if average < 50:
            if not allow_cloud_ocr:
                return {"needs_ocr": True, "content": "", "page_count": len(page_text)}
            import fitz
            document = fitz.open(path)
            ocr_results: Dict[int, str] = {}
            workers = max(1, min(int(os.environ.get("CASE_FILE_OCR_WORKERS", "4") or 4), 6))
            try:
                with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="case-file-ocr") as executor:
                    pending = {}

                    def collect(done):
                        for future in done:
                            page_number = pending.pop(future)
                            try:
                                ocr_results[page_number] = future.result()
                            except Exception:
                                ocr_results[page_number] = ""

                    for page_index, page in enumerate(document):
                        pixmap = page.get_pixmap(matrix=fitz.Matrix(2, 2), colorspace=fitz.csGRAY)
                        image_bytes = pixmap.tobytes("png")
                        future = executor.submit(
                            _ocr_page_image,
                            image_bytes,
                            filename=f"{path.stem}_{page_index + 1}.png",
                        )
                        pending[future] = page_index
                        # Bound queued page images so large scanned files do not consume excessive memory.
                        if len(pending) >= workers * 2:
                            done, _ = wait(set(pending), return_when=FIRST_COMPLETED)
                            collect(done)
                    while pending:
                        done, _ = wait(set(pending), return_when=FIRST_COMPLETED)
                        collect(done)
            finally:
                document.close()
            ocr_pages = [
                f"【第 {page_index + 1} 页】\n{ocr_results.get(page_index, '')}"
                for page_index in range(len(page_text))
            ]
            return {"title": path.stem, "content": "\n\n".join(ocr_pages), "ocr_used": True, "page_count": len(ocr_pages)}
        content = "\n\n".join(f"【第 {index + 1} 页】\n{text}" for index, text in enumerate(page_text))
        return {"title": path.stem, "content": content, "ocr_used": False, "page_count": len(page_text)}
    if suffix == ".doc":
        if shutil.which("textutil") is None:
            raise HTTPException(status_code=400, detail="当前系统无法解析旧版 .doc 文件，请先另存为 .docx")
        converted = subprocess.run(
            ["textutil", "-convert", "txt", "-stdout", str(path)], capture_output=True, timeout=60
        )
        if converted.returncode != 0:
            raise HTTPException(status_code=400, detail=f"无法解析旧版 Word 文件：{path.name}")
        return {"title": path.stem, "content": converted.stdout.decode("utf-8", errors="replace")}
    if suffix == ".docx":
        return parse_docx(str(path))
    if suffix == ".xls":
        try:
            import xlrd
        except ImportError as exc:
            raise HTTPException(status_code=500, detail="缺少旧版 Excel 解析组件 xlrd") from exc
        workbook = xlrd.open_workbook(str(path), on_demand=True)
        blocks = []
        try:
            for sheet_name in workbook.sheet_names():
                sheet = workbook.sheet_by_name(sheet_name)
                rows = []
                for row_index in range(sheet.nrows):
                    values = [str(sheet.cell_value(row_index, column)).strip() for column in range(sheet.ncols)]
                    values = [value for value in values if value]
                    if values:
                        rows.append("\t".join(values))
                if rows:
                    blocks.append(f"【{sheet_name}】\n" + "\n".join(rows))
        finally:
            workbook.release_resources()
        return {"title": path.stem, "content": "\n\n".join(blocks)}
    if suffix == ".xlsx":
        return parse_xlsx(str(path))
    return parse_txt(str(path))


async def _case_file_call_ai(model: str, messages: List[Dict[str, str]]):
    requested = model if model in ALLOWED_MODELS else DEFAULT_AI_MODEL
    actual_request = _effective_fallback_model() if requested == "workbuddy" else requested
    answer, reasoning, actual = await _call_ai_answer_with_continuation(
        actual_request, messages, temperature=0.2, max_tokens=5000, continuation_tokens=3000
    )
    return answer, reasoning, ("workbuddy" if requested == "workbuddy" else actual)


async def _automated_filing_call_ai(model: str, messages: List[Dict[str, str]]):
    """Use the model selected for automated filing in AI API 管理."""
    requested = ai_config_module.effective_purpose_model("automated_filing")
    if requested not in ALLOWED_MODELS:
        raise RuntimeError("自动化立案未配置可用的 AI API 或模型")
    result, actual = await _call_ai_with_fallback(
        requested, messages, temperature=0.0, max_tokens=1800
    )
    answer, _, _ = _extract_ai_choice(result)
    return answer, "", actual or requested


async def _case_file_authoritative_answer(question: str, model: str):
    return await ask_question(
        question=question,
        model=model if model in ALLOWED_MODELS else DEFAULT_AI_MODEL,
        source_mode="mcp:aluris,national_law,yuandian_case,yuandian_law",
        case_search=False,
        memory_enabled=False,
    )


async def _context_model_call(model, messages):
    async with background_ai():
        data, actual = await _call_ai_with_fallback(model,messages,temperature=0.0,max_tokens=2500)
    return _extract_ai_choice(data)[0]

ai_context.CALL_AI = _context_model_call

