def _home_reminder_date(value: str) -> datetime.date | None:
    """Parse the date portion stored by case-management reminder records."""
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except ValueError:
        try:
            return datetime.datetime.strptime(text[:10], "%Y-%m-%d").date()
        except ValueError:
            return None


def _home_reminder_item(row: sqlite3.Row, item_type: str, due_field: str, label: str, detail_field: str = "") -> Dict[str, Any]:
    due_at = str(row[due_field] or "")
    return {
        "id": int(row["id"]),
        "type": item_type,
        "label": label,
        "title": str(row["title"] or "未命名案件"),
        "summary": str(row["reminder_type"] or row[detail_field] or label) if detail_field else str(row["reminder_type"] or label),
        "due_at": due_at,
        "target": {"kind": "case", "view": item_type, "item_id": int(row["id"])},
    }


async def _build_home_reminder_center():
    """Homepage aggregate for time-sensitive case work and unread incoming messages."""
    today = datetime.date.today()
    end_date = today + datetime.timedelta(days=14)
    start_text, end_text = today.isoformat(), end_date.isoformat()
    items: List[Dict[str, Any]] = []
    counts = {key: 0 for key in ("todos", "hearings", "preservations", "appeals", "judicial_messages", "mails")}

    with get_db() as conn:
        reminder_queries = (
            ("todos", "待办", "remind_at", "notes", """
                SELECT t.id,t.title,t.todo_title AS reminder_type,t.remind_at,t.notes
                FROM case_manager_todos t JOIN case_manager_cases c ON c.id=t.case_id
                WHERE COALESCE(t.status,'pending')<>'completed' AND COALESCE(c.source_status,'active')='active'
                  AND date(t.remind_at) BETWEEN date(?) AND date(?)
            """),
            ("hearings", "开庭", "hearing_at", "location", """
                SELECT h.id,h.title,h.reminder_type,h.hearing_at,h.location
                FROM case_manager_hearings h JOIN case_manager_cases c ON c.id=h.case_id
                WHERE COALESCE(c.source_status,'active')='active'
                  AND date(h.hearing_at) BETWEEN date(?) AND date(?)
            """),
            ("preservations", "保全到期", "deadline_at", "asset_content", """
                SELECT p.id,p.title,p.preservation_type AS reminder_type,p.deadline_at,p.asset_content
                FROM case_manager_preservations p JOIN case_manager_cases c ON c.id=p.case_id
                WHERE COALESCE(c.source_status,'active')='active'
                  AND date(p.deadline_at) BETWEEN date(?) AND date(?)
            """),
            ("appeals", "上诉到期", "deadline_at", "case_no", """
                SELECT a.id,a.title,a.appeal_type AS reminder_type,a.deadline_at,a.case_no
                FROM case_manager_appeals a JOIN case_manager_cases c ON c.id=a.case_id
                WHERE COALESCE(c.source_status,'active')='active'
                  AND date(a.deadline_at) BETWEEN date(?) AND date(?)
            """),
        )
        for item_type, label, due_field, detail_field, query in reminder_queries:
            rows = conn.execute(query, (start_text, end_text)).fetchall()
            counts[item_type] = len(rows)
            items.extend(_home_reminder_item(row, item_type, due_field, label, detail_field) for row in rows)

        # `is_new` is the explicit unread marker maintained by the judicial-SMS inbox.
        try:
            sms_rows = conn.execute("""
                SELECT id,institution,category,received_at,raw_body
                FROM case_manager_judicial_messages
                WHERE COALESCE(is_deleted,0)=0 AND COALESCE(is_new,0)=1
                ORDER BY datetime(received_at) DESC,id DESC LIMIT 20
            """).fetchall()
        except sqlite3.OperationalError:
            sms_rows = []
        counts["judicial_messages"] = len(sms_rows)
        for row in sms_rows:
            items.append({
                "id": int(row["id"]), "type": "judicialMessages", "label": "司法短信",
                "title": str(row["institution"] or row["category"] or "新收司法短信"),
                "summary": str(row["category"] or row["raw_body"] or "待查看"),
                "due_at": str(row["received_at"] or ""),
                "target": {"kind": "case", "view": "judicialMessages", "item_id": int(row["id"])},
            })

    # Mail is queried outside SQLite and failure of one account must not hide case deadlines.
    mail_errors: List[str] = []
    chinese_text = re.compile(r"[\u3400-\u9fff]")
    for account in ("qq_mail", "qq_exmail", "netease_exmail"):
        try:
            mails = await run_in_threadpool(
                functools.partial(qq_mail_mcp.list_mails, limit=50, unread_only=True, account=account, folder="inbox")
            )
        except qq_mail_mcp.QQMailMCPError as exc:
            mail_errors.append(str(exc))
            continue
        for mail in mails:
            # The subject is available without downloading the body, so this deliberately
            # excludes messages whose subject is entirely English from the dashboard.
            subject = str(mail.get("subject") or "（无主题）")
            if not chinese_text.search(subject):
                continue
            counts["mails"] += 1
            items.append({
                "id": str(mail.get("uid") or ""), "type": "mail", "label": "未读邮件",
                "title": subject,
                "summary": str(mail.get("from") or {
                    "qq_mail": "QQ邮箱",
                    "qq_exmail": "腾讯企业邮箱",
                    "netease_exmail": "网易企业邮箱",
                }.get(account, "邮箱")),
                "due_at": str(mail.get("date") or ""),
                "target": {"kind": "mail", "account": account, "uid": str(mail.get("uid") or "")},
            })

    def sort_key(item: Dict[str, Any]):
        date = _home_reminder_date(item.get("due_at") or "")
        # Deadline items lead by date; newly received messages then follow newest-first.
        if item.get("target", {}).get("kind") == "case" and item.get("type") != "judicialMessages":
            return (0, date or end_date, 0)
        return (1, datetime.date.max, -int(item.get("id") or 0) if str(item.get("id") or "").isdigit() else 0)

    return {
        "window": {"from": start_text, "to": end_text},
        "counts": counts,
        "items": sorted(items, key=sort_key),
        "mail_errors": mail_errors,
        "updated_at": datetime.datetime.now().isoformat(timespec="seconds"),
    }


_HOME_REMINDER_CACHE: Dict[str, Any] = {}
_HOME_REMINDER_MAIL_CHECK_INTERVAL = datetime.timedelta(minutes=3)


def _home_reminder_local_signature() -> str:
    """Cheaply detect changes in local reminders without rebuilding the dashboard."""
    today = datetime.date.today()
    end_date = today + datetime.timedelta(days=14)
    start_text, end_text = today.isoformat(), end_date.isoformat()
    snapshots: List[tuple] = []
    queries = (
        """SELECT COUNT(*),COALESCE(MAX(t.updated_at),'') FROM case_manager_todos t
             JOIN case_manager_cases c ON c.id=t.case_id
             WHERE COALESCE(t.status,'pending')<>'completed' AND COALESCE(c.source_status,'active')='active'
               AND date(t.remind_at) BETWEEN date(?) AND date(?)""",
        """SELECT COUNT(*),COALESCE(MAX(h.updated_at),'') FROM case_manager_hearings h
             JOIN case_manager_cases c ON c.id=h.case_id
             WHERE COALESCE(c.source_status,'active')='active'
               AND date(h.hearing_at) BETWEEN date(?) AND date(?)""",
        """SELECT COUNT(*),COALESCE(MAX(p.updated_at),'') FROM case_manager_preservations p
             JOIN case_manager_cases c ON c.id=p.case_id
             WHERE COALESCE(c.source_status,'active')='active'
               AND date(p.deadline_at) BETWEEN date(?) AND date(?)""",
        """SELECT COUNT(*),COALESCE(MAX(a.updated_at),'') FROM case_manager_appeals a
             JOIN case_manager_cases c ON c.id=a.case_id
             WHERE COALESCE(c.source_status,'active')='active'
               AND date(a.deadline_at) BETWEEN date(?) AND date(?)""",
    )
    with get_db() as conn:
        for query in queries:
            row = conn.execute(query, (start_text, end_text)).fetchone()
            snapshots.append((int(row[0] or 0), str(row[1] or "")))
        try:
            row = conn.execute("""
                SELECT COUNT(*),COALESCE(MAX(updated_at),'') FROM case_manager_judicial_messages
                WHERE COALESCE(is_deleted,0)=0 AND COALESCE(is_new,0)=1
            """).fetchone()
            snapshots.append((int(row[0] or 0), str(row[1] or "")))
        except sqlite3.OperationalError:
            snapshots.append((0, ""))
    return hashlib.sha1(json.dumps(snapshots, ensure_ascii=False).encode("utf-8")).hexdigest()


@app.get("/api/home/reminder-center")
async def home_reminder_center():
    """Return a cached reminder payload unless local state or scheduled mail checks changed it."""
    now = datetime.datetime.now()
    local_signature = _home_reminder_local_signature()
    cached = _HOME_REMINDER_CACHE
    mail_check_due = not cached or now >= cached.get("mail_check_after", now)
    if cached and cached.get("local_signature") == local_signature and not mail_check_due:
        return {**cached["payload"], "version": cached["version"], "changed": False}

    payload = await _build_home_reminder_center()
    version_source = {"counts": payload["counts"], "items": payload["items"]}
    version = hashlib.sha1(
        json.dumps(version_source, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    changed = version != cached.get("version")
    _HOME_REMINDER_CACHE.clear()
    _HOME_REMINDER_CACHE.update({
        "payload": payload,
        "version": version,
        "local_signature": local_signature,
        "mail_check_after": now + _HOME_REMINDER_MAIL_CHECK_INTERVAL,
    })
    return {**payload, "version": version, "changed": changed}


