class InterestParameterRecognitionRequest(BaseModel):
    text: str


@app.post("/api/interest-calculator/recognize")
async def recognize_interest_parameters(payload: InterestParameterRecognitionRequest):
    """Use the model selected in AI API settings to extract calculator parameters."""
    description = payload.text.strip()
    if not description:
        raise HTTPException(status_code=400, detail="请先输入需要识别的利息描述")
    if len(description) > MAX_DESCRIPTION_LENGTH:
        raise HTTPException(status_code=400, detail=f"识别文字不能超过 {MAX_DESCRIPTION_LENGTH} 个字符")

    configured_model = ai_config_module.effective_purpose_model("interest_parameters")
    request_model = _effective_fallback_model() if configured_model == "workbuddy" else configured_model
    try:
        result, actual_model = await ai_client_module.call_ai_with_fallback(
            request_model,
            extraction_messages(description),
            temperature=0.0,
            max_tokens=2400,
        )
        content = result.get("choices", [{}])[0].get("message", {}).get("content", "")
        recognized = parse_extraction_content(content)
    except ValueError as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc
    except RuntimeError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc

    recognized.update({
        "model": configured_model if configured_model == "workbuddy" else actual_model,
        "modelLabel": ai_config_module.ask_model_label(
            configured_model if configured_model == "workbuddy" else actual_model
        ),
    })
    return recognized


