# ============================================================================
# 业务审批表生成器 API
# ============================================================================

class BusinessApprovalRequest(BaseModel):
    lawyer: str = ""      # 代理律师（承办律师）
    clientName: str       # 委托人
    otherParties: str = ""  # 其他当事人
    caseType: str = ""    # 案由（用于委托事项，留空则保持 XX 纠纷占位）


def _generate_business_approval_docx(data: BusinessApprovalRequest) -> bytes:
    """生成业务审批表 Word 文档 - 严格按照纸质审批表版式"""
    from docx import Document
    from docx.shared import Pt, Cm
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT, WD_ROW_HEIGHT_RULE
    from docx.enum.section import WD_ORIENT
    from docx.oxml.ns import qn
    from docx.oxml import OxmlElement

    def set_run_font(run, size=14, font='宋体', bold=False, underline=False):
        run.font.size = Pt(size)
        run.font.name = font
        run._element.rPr.rFonts.set(qn('w:eastAsia'), font)
        run.bold = bold
        if underline:
            run.underline = True
        return run

    def add_cell_paragraph(cell, text, size=14, font='宋体', bold=False, underline=False,
                           align=WD_ALIGN_PARAGRAPH.CENTER, first_line_indent=None, is_first=True):
        p = cell.paragraphs[0] if is_first and not cell.paragraphs[0].runs else cell.add_paragraph()
        p.alignment = align
        if first_line_indent is not None:
            p.paragraph_format.first_line_indent = first_line_indent
        if text:
            set_run_font(p.add_run(text), size=size, font=font, bold=bold, underline=underline)
        return p

    def set_cell_borders(doc_table):
        tbl = doc_table._tbl
        tbl_pr = tbl.tblPr
        borders = OxmlElement('w:tblBorders')
        for edge in ('top', 'left', 'bottom', 'right', 'insideH', 'insideV'):
            element = OxmlElement(f'w:{edge}')
            element.set(qn('w:val'), 'single')
            element.set(qn('w:sz'), '6')
            element.set(qn('w:space'), '0')
            element.set(qn('w:color'), '000000')
            borders.append(element)
        tbl_pr.append(borders)

    profile = get_appearance(get_db)
    doc = Document()

    # 页面尺寸（A4）与边距
    section = doc.sections[0]
    section.orientation = WD_ORIENT.PORTRAIT
    section.page_width = Cm(21)
    section.page_height = Cm(29.7)
    section.top_margin = Cm(2.2)
    section.bottom_margin = Cm(2.2)
    section.left_margin = Cm(3.0)
    section.right_margin = Cm(3.0)

    # 表头：律所名称
    firm_para = doc.add_paragraph()
    firm_para.alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_run_font(firm_para.add_run(profile['firm_name']), size=16, font='宋体')
    firm_para.paragraph_format.space_before = Pt(0)
    firm_para.paragraph_format.space_after = Pt(6)

    # 表头：标题
    title_para = doc.add_paragraph()
    title_para.alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_run_font(title_para.add_run('业务审批表'), size=26, font='黑体', bold=True)
    title_para.paragraph_format.space_before = Pt(6)
    title_para.paragraph_format.space_after = Pt(10)

    # 编号行
    no_para = doc.add_paragraph()
    no_para.alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_run_font(no_para.add_run('（20　　）'+profile['firm_code']+'律　　字第　　　　　号'), size=12, font='宋体')
    no_para.paragraph_format.space_before = Pt(0)
    no_para.paragraph_format.space_after = Pt(6)

    # 审批表主体：9 行 4 列
    table = doc.add_table(rows=9, cols=4)
    table.autofit = False
    set_cell_borders(table)

    col_widths = [Cm(2.7), Cm(4.9), Cm(3.4), Cm(4.0)]
    for row in table.rows:
        for idx, cell in enumerate(row.cells):
            cell.width = col_widths[idx]
            cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER

    row_heights = [1.2, 1.4, 2.2, 1.4, 1.4, 3.6, 2.0, 2.0, 1.9]
    for idx, height in enumerate(row_heights):
        table.rows[idx].height = Cm(height)
        table.rows[idx].height_rule = WD_ROW_HEIGHT_RULE.AT_LEAST

    # 第 1 行：完整编号 | 空 | 承办律师 | 律师库/代理律师
    add_cell_paragraph(table.cell(0, 0), '完整编号', bold=True)
    add_cell_paragraph(table.cell(0, 1), '')
    add_cell_paragraph(table.cell(0, 2), '承办律师', bold=True)
    add_cell_paragraph(table.cell(0, 3), data.lawyer.strip() or '律师库', size=14)

    # 其余行合并右侧三列
    for r in range(1, 9):
        merged = table.cell(r, 1).merge(table.cell(r, 2)).merge(table.cell(r, 3))

    # 第 2 行：委托人
    add_cell_paragraph(table.cell(1, 0), '委托人', bold=True)
    add_cell_paragraph(table.cell(1, 1), data.clientName.strip(), size=15, bold=bool(data.clientName.strip()))

    # 第 3 行：涉及当事人
    add_cell_paragraph(table.cell(2, 0), '涉　　及', bold=True)
    add_cell_paragraph(table.cell(2, 0), '当　事　人', bold=True, is_first=False)
    add_cell_paragraph(table.cell(2, 1), data.otherParties.strip(), size=15,
                       bold=bool(data.otherParties.strip()), underline=bool(data.otherParties.strip()))

    # 第 4 行：委托事项
    add_cell_paragraph(table.cell(3, 0), '委托事项', bold=True)
    case_type_clean = data.caseType.strip()
    if case_type_clean.endswith('纠纷'):
        case_type_clean = case_type_clean[:-2]
    matter_text = f"{case_type_clean}纠纷" if case_type_clean else 'XX 纠纷'
    add_cell_paragraph(table.cell(3, 1), matter_text)

    # 第 5 行：收费
    add_cell_paragraph(table.cell(4, 0), '收费', bold=True)
    add_cell_paragraph(table.cell(4, 1), '/')

    # 第 6 行：承办律师意见（固定承诺文本）
    add_cell_paragraph(table.cell(5, 0), '承办律师', bold=True)
    add_cell_paragraph(table.cell(5, 0), '意　　见', bold=True, is_first=False)
    add_cell_paragraph(table.cell(5, 1), '本人保证委托事宜真实合法，并自愿承担因合同产生的一切法律责任。',
                       size=12.5, font='楷体', align=WD_ALIGN_PARAGRAPH.LEFT,
                       first_line_indent=Pt(25))
    add_cell_paragraph(table.cell(5, 1), '本人承诺，本人申请用章的全部纸质版文件与本人上传于律所 OA 系统的电子文件内容一致，如有不一致，本人自愿承担因此所产生的一切法律责任。',
                       size=12.5, font='楷体', align=WD_ALIGN_PARAGRAPH.LEFT,
                       first_line_indent=Pt(25), is_first=False)
    sign_para = add_cell_paragraph(table.cell(5, 1), '承办律师：', size=12.5, font='楷体',
                                   align=WD_ALIGN_PARAGRAPH.RIGHT, is_first=False)
    sign_para.paragraph_format.right_indent = Pt(10)

    # 第 7 行：合规性利益冲突审查确认
    add_cell_paragraph(table.cell(6, 0), '合规性利益冲', bold=True)
    add_cell_paragraph(table.cell(6, 0), '突审查确认', bold=True, is_first=False)
    add_cell_paragraph(table.cell(6, 1), '已预检确认无利冲')

    # 第 8 行：审批人意见
    add_cell_paragraph(table.cell(7, 0), '审　批　人', bold=True)
    add_cell_paragraph(table.cell(7, 0), '意　　见', bold=True, is_first=False)

    # 第 9 行：备注
    add_cell_paragraph(table.cell(8, 0), '备　　注', bold=True)

    # 制表时间
    date_para = doc.add_paragraph()
    date_para.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    set_run_font(date_para.add_run('制表时间：　　　年　　月　　日'), size=14, font='宋体')
    date_para.paragraph_format.space_before = Pt(10)

    from io import BytesIO
    output = BytesIO()
    doc.save(output)
    output.seek(0)
    return output.getvalue()


