# ============================================================================
# 文书合集生成器 API（一次输入，同时生成授权委托书 + 法定代表人身份证明书）
# ============================================================================

class DocumentBundleRequest(BaseModel):
    clientType: str = "legal"  # legal 或 natural
    clientName: str
    creditCode: str = ""
    address: str = ""
    legalRepresentative: str = ""
    repTitle: str = ""  # 法定代表人职务（用于法定代表人身份证明书）
    idCard: str = ""
    court: str = ""  # 受理法院（用于所函）
    stages: List[str] = []  # 代理阶段（用于所函）
    lawyers: List[dict] = []
    parties: List[str] = []
    caseType: str = ""
    caseNumber: str = ""
    entrustType: str
    authorityContent: Optional[List[str]] = None
    date: str


def _format_chinese_date(date_str: str) -> str:
    """把 YYYY-MM-DD 转为 中文日期；解析失败时原样返回。"""
    try:
        date_obj = datetime.datetime.strptime(date_str, '%Y-%m-%d')
        return f"{date_obj.year}年{date_obj.month}月{date_obj.day}日"
    except (TypeError, ValueError):
        return date_str or ""


@app.post("/api/document-bundle/generate")
async def generate_document_bundle(request: DocumentBundleRequest):
    """一次输入同时生成《所函》《授权委托书》《法定代表人身份证明书》《业务审批表》，打包为 zip 下载。"""
    try:
        if not request.clientName.strip():
            raise HTTPException(status_code=400, detail="请填写委托人名称")
        if not [l for l in request.lawyers if l.get('name')]:
            raise HTTPException(status_code=400, detail="请至少添加一名受委托人")
        if not request.court.strip():
            raise HTTPException(status_code=400, detail="请填写受理法院")
        if not [s for s in request.stages if s.strip()]:
            raise HTTPException(status_code=400, detail="请至少填写一个代理阶段")
        is_legal = request.clientType == 'legal'
        include_cert = is_legal
        if is_legal and (not request.legalRepresentative.strip() or not request.repTitle.strip()):
            raise HTTPException(status_code=400, detail="法人委托人需填写法定代表人及职务才能生成法定代表人身份证明书")

        named_lawyers = [l for l in request.lawyers if l.get('name')]
        suohan_request = SuohanRequest(
            court=request.court,
            clients=[request.clientName],
            lawyers=[l['name'] for l in named_lawyers],
            parties=request.parties,
            caseType=request.caseType,
            caseNo=request.caseNumber,
            stages=[s for s in request.stages if s.strip()],
            date=_format_chinese_date(request.date),
            lawyerContacts=named_lawyers,
            format="word",
        )
        suohan_content = _generate_suohan_docx(suohan_request)
        _save_document_history('suohan', {
            "clients": [request.clientName],
            "court": request.court,
            "lawyers": [l['name'] for l in named_lawyers],
            "parties": request.parties,
            "caseType": request.caseType,
            "date": _format_chinese_date(request.date),
            "lawyerContacts": named_lawyers
        })

        power_request = PowerAttorneyRequest(
            clientType=request.clientType,
            clientName=request.clientName,
            creditCode=request.creditCode,
            address=request.address,
            legalRepresentative=request.legalRepresentative,
            idCard=request.idCard,
            lawyers=request.lawyers,
            parties=request.parties,
            caseType=request.caseType,
            caseNumber=request.caseNumber,
            entrustType=request.entrustType,
            authorityContent=request.authorityContent,
            stages=[s for s in request.stages if s.strip()],
            date=request.date,
        )
        power_content = _generate_power_attorney_docx(power_request)
        _save_document_history('power_attorney', {
            "clients": [request.clientName],
            "lawyers": [l['name'] for l in named_lawyers],
            "parties": request.parties,
            "caseType": request.caseType,
            "caseNumber": request.caseNumber,
            "date": request.date,
            "lawyerContacts": named_lawyers
        })

        # 业务审批表：承办律师取第一名受委托人，其他当事人取对方当事人。
        approval_request = BusinessApprovalRequest(
            lawyer=named_lawyers[0]['name'],
            clientName=request.clientName,
            otherParties="、".join(p for p in request.parties if p.strip()),
            caseType=request.caseType,
        )
        approval_content = _generate_business_approval_docx(approval_request)

        timestamp = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
        suohan_filename = f"所函_{request.court}_{timestamp}.docx"
        power_filename = f"授权委托书_{request.clientName}_{timestamp}.docx"
        approval_filename = f"业务审批表_{request.clientName}_{timestamp}.docx"
        from .document_bundle_artifacts import store_document_bundle_artifact
        artifact = store_document_bundle_artifact(
            get_db,
            suohan_content,
            suohan_filename,
            request.model_dump(),
        )

        zip_buf = BytesIO()
        folder = f"文书合集_{request.clientName}_{timestamp}"
        with zipfile.ZipFile(zip_buf, "w", zipfile.ZIP_DEFLATED) as zf:
            zf.writestr(f"{folder}/{suohan_filename}", suohan_content)
            zf.writestr(f"{folder}/{power_filename}", power_content)
            zf.writestr(f"{folder}/{approval_filename}", approval_content)
            if include_cert:
                cert_request = RepIdentityCertRequest(
                    clientName=request.clientName,
                    repName=request.legalRepresentative,
                    repTitle=request.repTitle,
                    date=request.date,
                )
                cert_content = _generate_rep_identity_cert_docx(cert_request)
                _save_document_history('rep_identity_cert', {
                    "clients": [request.clientName],
                    "repName": request.legalRepresentative,
                    "repTitle": request.repTitle,
                    "date": request.date
                })
                cert_filename = f"法定代表人身份证明书_{request.clientName}_{timestamp}.docx"
                zf.writestr(f"{folder}/{cert_filename}", cert_content)
        zip_buf.seek(0)
        from fastapi.responses import StreamingResponse
        from urllib.parse import quote
        zip_name = f"文书合集_{request.clientName}_{timestamp}.zip"
        return StreamingResponse(
            zip_buf,
            media_type="application/zip",
            headers={
                "Content-Disposition": f"attachment; filename*=UTF-8''{quote(zip_name)}",
                "X-APEX-Document-Artifact-Id": artifact["artifact_id"],
                "X-APEX-Document-Artifact-Sha256": artifact["sha256"],
            },
        )
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"生成文书合集失败: {str(e)}")


