@app.post("/api/case-manager/cases/{case_id}/authorization-materials/document-bundle")
async def save_document_bundle_to_case(case_id: int, request: DocumentBundleRequest):
    """将文书合集（所函 + 授权委托书 + 法定代表人身份证明书 + 业务审批表）归档到案件文件夹。"""
    from .case_automation import store_case_file
    if not [l for l in request.lawyers if l.get('name')]:
        raise HTTPException(status_code=400, detail="请至少添加一名受委托人")
    if not request.court.strip():
        raise HTTPException(status_code=400, detail="请填写受理法院")
    if not [s for s in request.stages if s.strip()]:
        raise HTTPException(status_code=400, detail="请至少填写一个代理阶段")
    timestamp = datetime.datetime.now().strftime('%Y%m%d')
    named_lawyers = [l for l in request.lawyers if l.get('name')]
    results = []
    suohan_request = SuohanRequest(
        court=request.court,
        clients=[request.clientName],
        lawyers=[l['name'] for l in named_lawyers],
        parties=request.parties,
        caseType=request.caseType,
        caseNo=request.caseNumber,
        stages=[s for s in request.stages if s.strip()],
        date=_format_chinese_date(request.date),
        lawyerContacts=named_lawyers,
        format="word",
    )
    suohan_content = _generate_suohan_docx(suohan_request)
    results.append(store_case_file(
        get_db, case_id, "authorization",
        f"所函_{request.court}_{timestamp}.docx", suohan_content,
        mime_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        source_type="document_bundle_generator", metadata={"client": request.clientName, "court": request.court},
    ))
    power_request = PowerAttorneyRequest(
        clientType=request.clientType,
        clientName=request.clientName,
        creditCode=request.creditCode,
        address=request.address,
        legalRepresentative=request.legalRepresentative,
        idCard=request.idCard,
        lawyers=request.lawyers,
        parties=request.parties,
        caseType=request.caseType,
        caseNumber=request.caseNumber,
        entrustType=request.entrustType,
        authorityContent=request.authorityContent,
        stages=[s for s in request.stages if s.strip()],
        date=request.date,
    )
    power_content = _generate_power_attorney_docx(power_request)
    results.append(store_case_file(
        get_db, case_id, "authorization",
        f"授权委托书_{request.clientName}_{timestamp}.docx", power_content,
        mime_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        source_type="document_bundle_generator", metadata={"client": request.clientName},
    ))
    approval_request = BusinessApprovalRequest(
        lawyer=named_lawyers[0]['name'],
        clientName=request.clientName,
        otherParties="、".join(p for p in request.parties if p.strip()),
        caseType=request.caseType,
    )
    approval_content = _generate_business_approval_docx(approval_request)
    results.append(store_case_file(
        get_db, case_id, "authorization",
        f"业务审批表_{request.clientName}_{timestamp}.docx", approval_content,
        mime_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        source_type="document_bundle_generator", metadata={"client": request.clientName},
    ))
    if request.clientType == 'legal':
        if not request.legalRepresentative.strip() or not request.repTitle.strip():
            raise HTTPException(status_code=400, detail="法人委托人需填写法定代表人及职务")
        cert_request = RepIdentityCertRequest(
            clientName=request.clientName,
            repName=request.legalRepresentative,
            repTitle=request.repTitle,
            date=request.date,
        )
        cert_content = _generate_rep_identity_cert_docx(cert_request)
        results.append(store_case_file(
            get_db, case_id, "authorization",
            f"法定代表人身份证明书_{request.clientName}_{timestamp}.docx", cert_content,
            mime_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            source_type="document_bundle_generator", metadata={"client": request.clientName},
        ))
    return {"ok": True, "files": results}


