@app.get("/api/knowledge-expand/enterprise-options")
def knowledge_expand_enterprise_options(q: str = ""):
    """Search legal entities from both client and opponent information libraries."""
    keyword = str(q or "").strip()[:120]
    with get_db() as conn:
        existing_tables = {
            row[0]
            for row in conn.execute(
                """SELECT name FROM sqlite_master
                   WHERE type='table' AND name IN ('case_manager_clients','case_manager_opponents')"""
            ).fetchall()
        }
        if not existing_tables:
            return {"companies": [], "total": 0, "query": keyword}

        candidates = []
        if "case_manager_clients" in existing_tables:
            candidates.append(
                """SELECT id,name,identity_code,industry,region,updated_at,
                          '客户信息库' AS library,0 AS library_priority
                   FROM case_manager_clients
                   WHERE trim(COALESCE(name,''))<>'' AND COALESCE(client_type,'')<>'个人'"""
            )
        if "case_manager_opponents" in existing_tables:
            candidates.append(
                """SELECT id,name,identity_code,industry,region,updated_at,
                          '对方信息库' AS library,1 AS library_priority
                   FROM case_manager_opponents
                   WHERE trim(COALESCE(name,''))<>'' AND COALESCE(opponent_type,'')<>'个人'"""
            )

        candidate_sql = " UNION ALL ".join(candidates)
        params = []
        filter_sql = ""
        if keyword:
            escaped = keyword.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
            pattern = f"%{escaped}%"
            filter_sql = "WHERE name LIKE ? ESCAPE '\\'"
            params.append(pattern)

        cte = f"""WITH candidates AS ({candidate_sql}),
            filtered AS (SELECT * FROM candidates {filter_sql}),
            ranked AS (
                SELECT *,ROW_NUMBER() OVER (
                    PARTITION BY name ORDER BY library_priority ASC,updated_at DESC,id DESC
                ) AS name_rank
                FROM filtered
            ),
            sources AS (
                SELECT name,GROUP_CONCAT(library,'、') AS libraries
                FROM (SELECT DISTINCT name,library,library_priority FROM filtered ORDER BY library_priority)
                GROUP BY name
            )"""
        total = conn.execute(
            f"{cte} SELECT COUNT(DISTINCT name) FROM filtered",
            params,
        ).fetchone()[0]
        order_params = list(params)
        if keyword:
            order_sql = "CASE WHEN r.name=? THEN 0 WHEN r.name LIKE ? ESCAPE '\\' THEN 1 ELSE 2 END,"
            order_params.extend([keyword, f"{escaped}%"])
        else:
            order_sql = ""
        limit = 50 if keyword else 20
        rows = conn.execute(
            f"""{cte}
                SELECT r.id,r.name,r.identity_code,r.industry,r.region,s.libraries AS library
                FROM ranked r JOIN sources s ON s.name=r.name
                WHERE r.name_rank=1
                ORDER BY {order_sql} r.updated_at DESC,r.name ASC LIMIT {limit}""",
            order_params,
        ).fetchall()
    return {"companies": [dict(row) for row in rows], "total": int(total or 0), "query": keyword}


