@app.post("/api/knowledge-expand/search")
async def knowledge_expand_search(request: Request):
    """
    检索指定时间范围内权威来源发布的指定领域相关文章。
    返回最多100条结果，并返回各来源的抓取诊断。
    支持参数：
    - domains: 专业领域列表
    - sources: 来源名称列表（空则使用所有来源）
    - days: 近N天（如 3, 7, 30）
    - date_from: 自定义起始日期（YYYY-MM-DD）
    - date_to: 自定义结束日期（YYYY-MM-DD）
    """
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="请求格式错误")

    domains = body.get("domains", [])
    if not domains:
        raise HTTPException(status_code=400, detail="请至少选择一个专业领域")

    # 获取时间范围参数
    sources_filter = body.get("sources", [])  # 空列表表示所有来源
    days = body.get("days")
    date_from = body.get("date_from")
    date_to = body.get("date_to")

    # 计算日期范围
    now = datetime.datetime.now()

    if date_from and date_to:
        # 自定义日期范围
        try:
            start_date = datetime.datetime.strptime(date_from, "%Y-%m-%d")
            end_date = datetime.datetime.strptime(date_to, "%Y-%m-%d")
            # 设置结束日期为当天结束
            end_date = end_date.replace(hour=23, minute=59, second=59)
            date_range_label = f"检索范围：{date_from} ~ {date_to}"
        except ValueError:
            raise HTTPException(status_code=400, detail="日期格式错误，请使用 YYYY-MM-DD 格式")
    elif days:
        # 近N天
        days = int(days)
        # 页面按“自然日”展示日期范围，起始日必须从 00:00 开始。
        # 旧逻辑保留了当前时分秒，会误删起始日早些时候发布的文章。
        start_date = (now - datetime.timedelta(days=days)).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        end_date = now
        day_names = {3: "三天", 7: "七天", 30: "一个月"}
        date_range_label = f"检索近{day_names.get(days, str(days) + '天')}：{start_date.strftime('%Y-%m-%d')} ~ {end_date.strftime('%Y-%m-%d')}"
    else:
        # 默认近三天
        days = 3
        start_date = (now - datetime.timedelta(days=3)).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        end_date = now
        date_range_label = f"检索范围：{start_date.strftime('%Y-%m-%d')} ~ {end_date.strftime('%Y-%m-%d')}"

    # ── 从数据库加载领域关键词 ──────────────────────────────────────
    # 用户在后台配置的领域关键词优先于内置关键词
    db_keywords = {}  # {domain: [keyword1, keyword2, ...]}
    try:
        persist_history = body.get("_persist_history", True)
    except Exception:
        persist_history = True

    try:
        with get_db() as conn:
            for domain in domains:
                rows = conn.execute(
                    "SELECT keyword FROM expand_domain_keywords WHERE domain = ?",
                    (domain,)
                ).fetchall()
                kws = [r[0] for r in rows if r[0]]
                if kws:
                    db_keywords[domain] = kws
    except Exception:
        pass  # 数据库查不到不影响运行

    # 优先用请求体中的 keywords，否则用数据库关键词，最后用内置关键词
    req_keywords = body.get("keywords", {})
    # 构建最终 keywords_map：请求体 > 数据库 > 内置
    keywords_map = dict(req_keywords)
    for domain, kws in db_keywords.items():
        if domain not in keywords_map:
            keywords_map[domain] = kws

