def _radar_digest_with_results(conn, row) -> dict:
    data = dict(row)
    try:
        result_ids = [int(x) for x in json.loads(data.get("result_ids_json") or "[]") if str(x).isdigit()]
    except Exception:
        result_ids = []
    if not result_ids:
        data["results"] = []
        return data
    placeholders = ",".join("?" for _ in result_ids)
    rows = [dict(r) for r in conn.execute(
        f"""SELECT id,title,url,source_name,published_at,summary,domain,body_text,
                  verification_level,is_read,is_imported,is_ignored,created_at
             FROM authority_watch_results
             WHERE id IN ({placeholders})""",
        result_ids,
    ).fetchall()]
    by_id = {int(r["id"]): r for r in rows}
    data["results"] = [by_id[i] for i in result_ids if i in by_id]
    return data


