async def _maybe_run_daily_national_law_scan():
    if os.environ.get("NATIONAL_LAW_SCHEDULER_DISABLED") == "1":
        return
    now = datetime.datetime.now()
    cutoff = (now - datetime.timedelta(hours=24)).isoformat()
    with get_db() as conn:
        bound_count = conn.execute("SELECT COUNT(*) FROM national_law_articles").fetchone()[0]
        recent = conn.execute(
            """SELECT id FROM national_law_update_scans
               WHERE mode='automatic' AND created_at>=? ORDER BY id DESC LIMIT 1""", (cutoff,)
        ).fetchone()
        active = conn.execute(
            "SELECT id FROM national_law_update_scans WHERE status IN ('queued','running') LIMIT 1"
        ).fetchone()
        if not bound_count or recent or active:
            return
        cur = conn.execute(
            "INSERT INTO national_law_update_scans(mode,status,created_at) VALUES ('automatic','queued',?)",
            (now.isoformat(),),
        )
        conn.commit()
        scan_id = cur.lastrowid
    try:
        await _run_national_law_scan(scan_id)
    except Exception as exc:
        with get_db() as conn:
            conn.execute(
                """UPDATE national_law_update_scans
                   SET status='failed',error=?,completed_at=? WHERE id=?""",
                (str(exc)[:1000], datetime.datetime.now().isoformat(), scan_id),
            )
            conn.commit()
        raise


async def _radar_scheduler_loop():
    await asyncio.sleep(3)
    while True:
        try:
            now = _radar_now().isoformat()
            with get_db() as conn:
                due = [r[0] for r in conn.execute("SELECT id FROM authority_watch_tasks WHERE enabled=1 AND (next_run_at IS NULL OR next_run_at<=?)", (now,)).fetchall()]
            for task_id in due:
                try: await _run_radar_task(task_id)
                except Exception as exc: print(f"[radar] task {task_id} failed: {exc}")
            await _generate_daily_radar_digest(False)
            try:
                await _maybe_run_daily_national_law_scan()
            except Exception as exc:
                print(f"[national-law] daily scan failed: {exc}")
        except Exception as exc: print(f"[radar] scheduler failed: {exc}")
        await asyncio.sleep(600)


