@app.get("/api/knowledge-expand/sources")
async def get_sources():
    """获取所有检索来源（默认 + 自定义），应用来源覆盖"""
    with get_db() as conn:
        # 获取自定义来源
        cursor = conn.execute("SELECT id, name, url, created_at FROM expand_custom_sources ORDER BY id ASC")
        rows = cursor.fetchall()
        custom_sources = [
            {"id": f"custom_{r[0]}", "name": r[1], "url": r[2], "is_default": False, "created_at": r[3]}
            for r in rows
        ]
        # 获取来源覆盖（用户对名称/URL的修改）
        overrides = {}
        ov_cursor = conn.execute("SELECT source_id, name, url FROM expand_source_overrides")
        for row in ov_cursor.fetchall():
            overrides[row[0]] = {"name": row[1], "url": row[2]}

    # 合并默认来源 + 覆盖
    result_sources = []
    for s in DEFAULT_SOURCES:
        ov = overrides.get(s["id"])
        result_sources.append({
            "id": s["id"],
            "name": ov["name"] if ov else s["name"],
            "url": ov["url"] if ov else s["url"],
            "is_default": True,
            "original_name": s["name"],  # 方便前端显示"恢复默认"
            "original_url": s["url"],
        })
    # 合并自定义来源 + 覆盖
    for s in custom_sources:
        ov = overrides.get(s["id"])
        result_sources.append({
            "id": s["id"],
            "name": ov["name"] if ov else s["name"],
            "url": ov["url"] if ov else s["url"],
            "is_default": False,
            "original_name": s["name"],
            "original_url": s["url"],
        })
    return {"sources": result_sources}


@app.get("/api/knowledge-expand/history")
async def get_expand_search_history(limit: int = 80):
    """获取探索检索历史列表。"""
    limit = max(1, min(int(limit or 80), 200))
    with get_db() as conn:
        rows = conn.execute(
            """
            SELECT id, searched_at, domains, sources, date_range, result_count
            FROM expand_search_history
            ORDER BY searched_at DESC, id DESC
            LIMIT ?
            """,
            (limit,)
        ).fetchall()

    history = []
    for r in rows:
        try:
            domains_value = json.loads(r["domains"] or "[]")
        except Exception:
            domains_value = []
        try:
            sources_value = json.loads(r["sources"] or "[]")
        except Exception:
            sources_value = []
        history.append({
            "id": r["id"],
            "searched_at": r["searched_at"],
            "domains": domains_value,
            "sources": sources_value,
            "date_range": r["date_range"] or "",
            "result_count": r["result_count"] or 0,
        })
    return {"history": history}


@app.get("/api/knowledge-expand/history/{history_id}")
async def get_expand_search_history_detail(history_id: int):
    """获取某次探索检索的完整结果。"""
    with get_db() as conn:
        row = conn.execute(
            """
            SELECT id, searched_at, domains, sources, keywords, date_range,
                   days, date_from, date_to, result_count, results_json
            FROM expand_search_history
            WHERE id = ?
            """,
            (history_id,)
        ).fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="检索历史不存在")

    def _loads(value, fallback):
        try:
            return json.loads(value or "")
        except Exception:
            return fallback

    return {
        "id": row["id"],
        "searched_at": row["searched_at"],
        "domains": _loads(row["domains"], []),
        "sources": _loads(row["sources"], []),
        "keywords": _loads(row["keywords"], {}),
        "date_range": row["date_range"] or "",
        "days": row["days"],
        "date_from": row["date_from"] or "",
        "date_to": row["date_to"] or "",
        "result_count": row["result_count"] or 0,
        "results": _loads(row["results_json"], []),
    }


@app.post("/api/knowledge-expand/sources")
async def add_source(request: Request):
    """添加自定义来源"""
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="请求格式错误")

    name = body.get("name", "").strip()
    url = body.get("url", "").strip()

    if not name:
        raise HTTPException(status_code=400, detail="请输入来源名称")
    if not url:
        raise HTTPException(status_code=400, detail="请输入来源网址")
    if not url.startswith(("http://", "https://")):
        raise HTTPException(status_code=400, detail="网址必须以 http:// 或 https:// 开头")

    with get_db() as conn:
        # 检查是否已存在
        existing = conn.execute(
            "SELECT id FROM expand_custom_sources WHERE name = ? OR url = ?",
            (name, url)
        ).fetchone()
        if existing:
            raise HTTPException(status_code=400, detail="该来源名称或网址已存在")

        cursor = conn.execute(
            "INSERT INTO expand_custom_sources (name, url) VALUES (?, ?)",
            (name, url)
        )
        new_id = cursor.lastrowid

    return {"id": f"custom_{new_id}", "name": name, "url": url, "is_default": False}


@app.delete("/api/knowledge-expand/sources/{source_id}")
async def delete_source(source_id: str):
    """删除自定义来源（默认来源不可删除）"""
    if not source_id.startswith("custom_"):
        raise HTTPException(status_code=400, detail="默认来源不可删除")

    try:
        db_id = int(source_id.replace("custom_", ""))
    except ValueError:
        raise HTTPException(status_code=400, detail="无效的来源ID")

    with get_db() as conn:
        cursor = conn.execute("DELETE FROM expand_custom_sources WHERE id = ?", (db_id,))
        if cursor.rowcount == 0:
            raise HTTPException(status_code=404, detail="来源不存在")
        # 同时清除该来源的覆盖记录
        conn.execute("DELETE FROM expand_source_overrides WHERE source_id = ?", (source_id,))

    return {"ok": True}


@app.put("/api/knowledge-expand/sources/{source_id}")
async def update_source(source_id: str, request: Request):
    """编辑来源名称和URL（默认来源和自定义来源均支持）"""
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="请求格式错误")

    name = (body.get("name") or "").strip()
    url = (body.get("url") or "").strip()

    if not name:
        raise HTTPException(status_code=400, detail="来源名称不能为空")
    if not url:
        raise HTTPException(status_code=400, detail="网址不能为空")
    if not url.startswith(("http://", "https://")):
        raise HTTPException(status_code=400, detail="网址必须以 http:// 或 https:// 开头")

    # 判断是默认来源还是自定义来源
    default_ids = {s["id"] for s in DEFAULT_SOURCES}
    is_default = source_id in default_ids
    is_custom = source_id.startswith("custom_")

    if not is_default and not is_custom:
        raise HTTPException(status_code=400, detail="无效的来源ID")

    with get_db() as conn:
        if is_custom:
            # 自定义来源：同时更新主表和覆盖表
            try:
                db_id = int(source_id.replace("custom_", ""))
            except ValueError:
                raise HTTPException(status_code=400, detail="无效的来源ID")
            result = conn.execute(
                "UPDATE expand_custom_sources SET name = ?, url = ? WHERE id = ?",
                (name, url, db_id)
            )
            if result.rowcount == 0:
                raise HTTPException(status_code=404, detail="来源不存在")
        # 统一写入覆盖表（默认来源用覆盖表，自定义来源也写入方便统一读取）
        conn.execute(
            """INSERT INTO expand_source_overrides (source_id, name, url, updated_at)
               VALUES (?, ?, ?, CURRENT_TIMESTAMP)
               ON CONFLICT(source_id) DO UPDATE SET name=excluded.name, url=excluded.url, updated_at=CURRENT_TIMESTAMP""",
            (source_id, name, url)
        )

    return {"ok": True, "id": source_id, "name": name, "url": url}


@app.put("/api/knowledge-expand/sources/{source_id}/reset")
async def reset_source(source_id: str):
    """将来源恢复为默认值（仅默认来源支持）"""
    default_ids = {s["id"] for s in DEFAULT_SOURCES}
