@app.get("/api/knowledge-expand/keywords")
async def get_domain_keywords():
    """获取所有领域的关键词（按领域分组）"""
    with get_db() as conn:
        cursor = conn.execute(
            "SELECT domain, keyword, source FROM expand_domain_keywords ORDER BY domain, keyword"
        )
        rows = cursor.fetchall()
    
    # 按领域分组
    result = {}
    for row in rows:
        domain, keyword, source = row
        if domain not in result:
            result[domain] = []
        result[domain].append({"keyword": keyword, "source": source})
    
    return {"keywords": result}


@app.post("/api/knowledge-expand/keywords")
async def save_domain_keywords(request: Request):
    """批量保存领域关键词（去重后永久存储）"""
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="请求格式错误")
    
    keywords_data = body.get("keywords", {})  # {domain: [keyword]}
    source = body.get("source", "user")  # 'user' 或 'ai'
    
    if not keywords_data:
        raise HTTPException(status_code=400, detail="请提供关键词数据")
    
    with get_db() as conn:
        saved_count = 0
        for domain, keywords in keywords_data.items():
            for keyword in keywords:
                keyword = keyword.strip()
                if not keyword:
                    continue
                # 使用 INSERT OR IGNORE 避免重复
                cursor = conn.execute(
                    "INSERT OR IGNORE INTO expand_domain_keywords (domain, keyword, source) VALUES (?, ?, ?)",
                    (domain, keyword, source)
                )
                if cursor.rowcount > 0:
                    saved_count += 1
    
    return {"ok": True, "saved": saved_count}


